  // dispatch's per-axis workgroup fold width (the dispatch caps x and spills the rest into y).
  let invocation = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ tunables.WORKGROUP_SIZE }}u;
