{% set needsCount = op == "max" or (op == "average" and not countIncludePad) %}
{% if useSubgroups %}
enable subgroups;
{% endif %}
{{ env.wgsl.resourceDeclarations }}

// Workgroup-cooperative windowed pooling: one workgroup reduces the kernel
// window of ONE output element. The serial route gives each output element a
// single invocation that loops the whole window, so its only parallelism is the
// output element count; when that count launches too few workgroups and the window is
// long, the window itself is the parallelism worth spending. Threads here stride
// the flattened tap index [kD x] kH x kW, each tap resolving its own padded,
// strided and dilated input coordinate, then combine the per-thread partials.
// With subgroups: a subgroup collective, then one shared-memory slot per
// invocation (the subgroup partial from its elected lane, the identity from
// every other lane) that every subgroup folds. Without subgroups, a full
// workgroup tree combines the per-thread partials.
{% if countIncludePad %}
// count_include_pad == 1 with ceil_mode == 0 makes every tap of every window
// land inside the padded extent, so the divisor is the baked tap count and no
// second reduction is needed. The tree changes the association of additions.
{% else %}
// count_include_pad == 0 divides by the in-bounds tap count, which is reduced
// across the workgroup alongside the sum. An output whose window is entirely
// out of bounds writes 0, matching the serial route. The tree changes the
// association of additions.
{% endif %}
const WG: u32 = {{ workgroupSizeSpec }}u;
const KW: u32 = {{ kernelWSpec }}u;
{% if spatialRankSpec >= 2 %}
const KH: u32 = {{ kernelHSpec }}u;
{% endif %}
// Flattened tap count of the whole window; the loop bound and, for
// count_include_pad == 1, the divisor.
const TAPS: u32 = {{ kernelDSpec * kernelHSpec * kernelWSpec }}u;
// One slot per invocation: the cross-subgroup fold below indexes by
// local_invocation_id, never by a subgroup ordinal, so no subgroup width or
// partition can overflow or alias it.
var<workgroup> wg_partials: array<f32, WG>;
{% if needsCount %}
var<workgroup> wg_counts: array<f32, WG>;
{% endif %}

@compute @workgroup_size(WG)
fn main(@builtin(workgroup_id) wid: vec3<u32>,
        @builtin(local_invocation_id) lid: vec3<u32>{% if useSubgroups %},
        @builtin(subgroup_invocation_id) sg_lane: u32,
        @builtin(subgroup_size) sg_size: u32{% endif %}) {
  // One workgroup per output element: the dispatch is exactly numel(y), so no
  // bounds guard is needed here.
  let index = wid.x;
  let tid = lid.x;

  let ow = index % params.outW;
  var t = index / params.outW;
{% if spatialRankSpec >= 2 %}
  let oh = t % params.outH;
  t /= params.outH;
{% endif %}
{% if spatialRankSpec == 3 %}
  let od = t % params.outD;
  t /= params.outD;
{% endif %}
  let channel = t % params.channels;
  let batch = t / params.channels;

  let startW = i32(ow * params.strideW) - params.padW;
{% if spatialRankSpec >= 2 %}
  let startH = i32(oh * params.strideH) - params.padH;
{% endif %}
{% if spatialRankSpec == 3 %}
  let startD = i32(od * params.strideD) - params.padD;
{% endif %}
{% if spatialRankSpec == 1 %}
  let planeBase = (batch * params.channels + channel) * params.inW;
{% elif spatialRankSpec == 2 %}
  let planeBase = (batch * params.channels + channel) * params.inH * params.inW;
{% else %}
  let planeBase = (batch * params.channels + channel) * params.inD * params.inH * params.inW;
{% endif %}

  var partial = 0.0;
{% if needsCount %}
  var counted = 0.0;
{% endif %}
  for (var tap = tid; tap < TAPS; tap = tap + WG) {
    let kw = tap % KW;
{% if spatialRankSpec >= 2 %}
    let rest = tap / KW;
    let kh = rest % KH;
{% endif %}
{% if spatialRankSpec == 3 %}
    let kd = rest / KH;
{% endif %}
    let iw = startW + i32(kw * params.dilationW);
{% if spatialRankSpec >= 2 %}
    let ih = startH + i32(kh * params.dilationH);
{% endif %}
{% if spatialRankSpec == 3 %}
    let id = startD + i32(kd * params.dilationD);
{% endif %}
{% if spatialRankSpec == 1 %}
    let inBounds = iw >= 0 && iw < i32(params.inW);
{% elif spatialRankSpec == 2 %}
    let inBounds = iw >= 0 && iw < i32(params.inW) && ih >= 0 && ih < i32(params.inH);
{% else %}
    let inBounds = iw >= 0 && iw < i32(params.inW) && ih >= 0 && ih < i32(params.inH) && id >= 0 && id < i32(params.inD);
{% endif %}
    if (inBounds) {
{% if spatialRankSpec == 1 %}
      let value = f32(x[planeBase + u32(iw)]);
{% elif spatialRankSpec == 2 %}
      let value = f32(x[planeBase + u32(ih) * params.inW + u32(iw)]);
{% else %}
      let value = f32(x[planeBase + (u32(id) * params.inH + u32(ih)) * params.inW + u32(iw)]);
{% endif %}
      partial = partial + value;
{% if needsCount %}
      counted = counted + 1.0;
{% endif %}
    }
  }

{% if useSubgroups %}
{% filter indent(2, true) %}
var total = subgroupAdd(partial);
{% if needsCount %}
var countTotal = subgroupAdd(counted);
{% endif %}
// Cross-subgroup fold that assumes nothing about which invocations share a
// subgroup or how many subgroups there are (it does require the uniform
// control flow this entry point already has): every invocation owns the slot
// at its own index, the elected lane
// publishes its subgroup partial there and every other lane publishes the
// reduction identity. Each subgroup then folds all WG slots — lane `sg_lane`
// walks slots sg_lane, sg_lane + sg_size, ... — and one more collective merges
// the lane partials, so every slot is merged exactly once at any legal width.
// The coordinates are the BUILTINS, never `subgroupExclusiveAdd(1u)` /
// `subgroupAdd(1u)`: those agree with them under this contract, but a driver
// in the wild answers a claim derived from them with zero. A one-subgroup
// workgroup skips shared memory entirely; that test reads the `subgroup_size`
// builtin, which is uniform, because a collective's result is not uniform to
// WGSL's analysis and may not guard a barrier.
if (sg_size != WG) {
  let rank = sg_lane;
  let lanes = sg_size;
  wg_partials[tid] = select(0.0, total, rank == 0u);
{% if needsCount %}
  wg_counts[tid] = select(0.0, countTotal, rank == 0u);
{% endif %}
  workgroupBarrier();
  var acc = 0.0;
{% if needsCount %}
  var countAcc = 0.0;
{% endif %}
  for (var i = rank; i < WG; i = i + lanes) {
    acc = acc + wg_partials[i];
{% if needsCount %}
    countAcc = countAcc + wg_counts[i];
{% endif %}
  }
  total = subgroupAdd(acc);
{% if needsCount %}
  countTotal = subgroupAdd(countAcc);
{% endif %}
}
{% endfilter %}
{% else %}
  // No-subgroups fallback: full workgroup-tree reduction of the per-thread
  // partials, carrying the unpaired entry forward for odd active widths.
  wg_partials[tid] = partial;
{% if needsCount %}
  wg_counts[tid] = counted;
{% endif %}
  workgroupBarrier();
  for (var liveCount = WG; liveCount > 1u; liveCount = (liveCount + 1u) / 2u) {
    let step = (liveCount + 1u) / 2u;
    if (tid + step < liveCount) {
      wg_partials[tid] = wg_partials[tid] + wg_partials[tid + step];
{% if needsCount %}
      wg_counts[tid] = wg_counts[tid] + wg_counts[tid + step];
{% endif %}
    }
    workgroupBarrier();
  }
  let total = wg_partials[0];
{% if needsCount %}
  let countTotal = wg_counts[0];
{% endif %}
{% endif %}
  if (tid == 0u) {
{% if countIncludePad %}
    y[index] = {{ scalar }}(total / f32(TAPS));
{% else %}
    y[index] = {{ scalar }}(select(0.0, total / countTotal, countTotal > 0.0));
{% endif %}
  }
}

