fn lin(coord: u32, size: u32) -> f32 {
{% if alignCorners %}
  if (size <= 1u) { return 0.0; }
  return -1.0 + 2.0 * f32(coord) / f32(size - 1u);
{% else %}
  return (2.0 * f32(coord) + 1.0) / f32(size) - 1.0;
{% endif %}
