}

fn k_at(b: u32, h: u32, k: u32, d: u32) -> f32 {
{% if layout == "bhsd" %}
  return {{ "f32(" if STORAGE_F16 else "" }}key[((b * KV_HEADS + h) * params.kvSeq + k) * HEAD_DIM + d]{{ ")" if STORAGE_F16 else "" }};
{% else %}
  return {{ "f32(" if STORAGE_F16 else "" }}key[(b * params.kvSeq + k) * KV_HIDDEN + h * HEAD_DIM + d]{{ ")" if STORAGE_F16 else "" }};
{% endif %}
