@compute @workgroup_size(WG_DIM, WG_DIM, 1)
fn main(
  @builtin(workgroup_id) wg: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>
) {
  let h = wg.z % Q_HEADS;
  let b = wg.z / Q_HEADS;
  let hKv = h / (Q_HEADS / KV_HEADS);
  let qBase = wg.y * BM;
  let kBase = wg.x * BN;
  let li = lid.y * WG_DIM + lid.x;

{% if scalarAccumulators %}
  // Keep every register-tile cell statically addressable.
{% for i in range(TM_JINJA) %}
{% for j in range(TN_JINJA) %}
  var acc{{ i }}_{{ j }}: f32 = 0.0;
{% endfor %}
{% endfor %}
{% else %}
  var acc: array<f32, TM * TN>;
  for (var i = 0u; i < TM * TN; i = i + 1u) { acc[i] = 0.0; }
{% endif %}

  for (var dBase = 0u; dBase < HEAD_DIM; dBase = dBase + BK) {
    // Both source tiles are loaded in their physical row-major direction.
    // Each lane stages whole vector words: four adjacent head dimensions of one
    // query row and of one key row, both contiguous in their source tensor.
    for (var linear = li; linear < BM * D_VECS; linear += WG_THREADS) {
      let qr = linear / D_VECS;
