      let kr = linear / D_VECS;
      let kv4 = linear % D_VECS;
      let ki = kBase + kr;
      let kdim = dBase + kv4 * 4u;
      let kLive = ki < params.kvSeq;
      tileK[kr][kv4] = vec4<f32>(
{% for component in range(4) %}
        select(0.0, k_at(b, hKv, ki, kdim + {{ component }}u), kLive && kdim + {{ component }}u < HEAD_DIM){% if not loop.last %},{% endif %}
{% endfor %}
      );
    }
    workgroupBarrier();

    let qr0 = lid.y * TM;
    let kc0 = lid.x * TN;
    for (var dv = 0u; dv < D_VECS; dv = dv + 1u) {
{% if scalarAccumulators %}
{% for i in range(TM_JINJA) %}
      let qv{{ i }} = tileQ[qr0 + {{ i }}u][dv];
{% endfor %}
{% for j in range(TN_JINJA) %}
      let kv{{ j }} = tileK[kc0 + {{ j }}u][dv];
{% endfor %}
{% for i in range(TM_JINJA) %}
{% for j in range(TN_JINJA) %}
      acc{{ i }}_{{ j }} = acc{{ i }}_{{ j }} + dot(qv{{ i }}, kv{{ j }});
{% endfor %}
{% endfor %}
{% else %}
      var qv: array<vec4<f32>, TM>;
      var kv: array<vec4<f32>, TN>;
      for (var i = 0u; i < TM; i = i + 1u) { qv[i] = tileQ[qr0 + i][dv]; }
      for (var j = 0u; j < TN; j = j + 1u) { kv[j] = tileK[kc0 + j][dv]; }
