  }

  let qi0 = qBase + lid.y * TM;
  let ki0 = kBase + lid.x * TN;
  let scoreBase = wg.z * params.qSeq * params.kvSeq;
  let scale = scale_value();
  // Taken on the STORED value, so the max describes exactly the numbers the apply pass will
  // read back — including the mask term, which must be inside it.
  var rowM: array<f32, TM>;
  for (var i = 0u; i < TM; i = i + 1u) { rowM[i] = -FLT_MAX; }
{% if scalarAccumulators %}
{% for i in range(TM_JINJA) %}
  {
    let qi = qi0 + {{ i }}u;
    if (qi < params.qSeq) {
{% for j in range(TN_JINJA) %}
      let ki{{ j }} = ki0 + {{ j }}u;
      if (ki{{ j }} < params.kvSeq) {
        var score = acc{{ i }}_{{ j }} * scale;
        scores[scoreBase + qi * params.kvSeq + ki{{ j }}] = score;
        rowM[{{ i }}u] = max(rowM[{{ i }}u], score);
      }
{% endfor %}
    }
  }
{% endfor %}
{% else %}
  for (var i = 0u; i < TM; i = i + 1u) {
    let qi = qi0 + i;
    if (qi >= params.qSeq) { continue; }
