        var score = acc[i * TN + j] * scale;
        scores[scoreBase + qi * params.kvSeq + ki] = score;
        rowM[i] = max(rowM[i], score);
      }
    }
  }
{% endif %}

  // Fold each row's partial (m, d) across the WG_DIM threads that own its columns. Every lane
  // runs the same trip count, so every barrier is reached by every lane.
  for (var i = 0u; i < TM; i = i + 1u) {
    statScratch[li] = rowM[i];
