// Online-softmax rank-four attention using a workgroup tree reduction. One
// workgroup owns each query row, computes each q·k score once, and updates the
// shared V-weighted output with the online rescale. Scale, softcap, masking, and
// GQA head mapping retain their defined arithmetic order.
const WG: u32 = {{ tunables.WORKGROUP_SIZE }}u;
const V_CAP: u32 = {{ vHeadCap }}u;

var<workgroup> partial: array<f32, WG>;
var<workgroup> running_max: f32;
var<workgroup> running_denom: f32;
var<workgroup> running_out: array<f32, V_CAP>;
var<workgroup> previous_scale: f32;
{% macro wgsl_tree_reduce_f32(name, mode, buffer="partial", wg="WG", trailingBarrier=true, valueType="f32") %}
fn {{ name }}(value: {{ valueType }}, tid: u32) -> {{ valueType }} {
  {{ buffer }}[tid] = value;
  workgroupBarrier();
  // Ceil-halving keeps every lane when the workgroup size is not a power of
  // two. For even n this matches the power-of-two tree order; for odd n, lanes
  // [0, n-half) fold the upper tail while the middle lane carries forward.
  var n: u32 = {{ wg }};
  loop {
    let half = (n + 1u) / 2u;
    if (tid < n - half) {
      {{ buffer }}[tid] = {{ buffer }}[tid] + {{ buffer }}[tid + half];
    }
    workgroupBarrier();
    n = half;
    if (n == 1u) {
      break;
    }
  }
