  let tid = lid.x;

  let qBase = ((batch * params.qHeads + qh) * params.qSeq + qs) * params.headSize;
  let kBase = (batch * params.kvHeads + kh) * params.kvSeq;
  let vBase = (batch * params.kvHeads + kh) * params.kvSeq;
