{% if layout != "bhsd" or hasBias %}
const Q_HIDDEN: u32 = Q_HEADS * HEAD_DIM;
{% endif %}
{% if layout != "bhsd" %}
const KV_HIDDEN: u32 = KV_HEADS * HEAD_DIM;
{% endif %}

const BK: u32 = {{ materializedInnerTile }}u;
const BM: u32 = {{ materializedQueryTile }}u;
const BN: u32 = {{ applyTileN }}u;
const WG_DIM: u32 = {{ materializedWorkgroupDim }}u;
const WG_THREADS: u32 = WG_DIM * WG_DIM;
