    for (var kk: u32 = 0u; kk < TILE_K; kk = kk + 1u) {
      let pk = select(0.0, exp({{ qn("s", qi) }}[kk] - {{ qn("newMax", qi) }}), {{ qn("s", qi) }}[kk] != NEG_INF);
      {{ qn("s", qi) }}[kk] = pk;
      {{ qn("pSum", qi) }} = {{ qn("pSum", qi) }} + pk;
    }
    {{ qn("l", qi) }} = {{ qn("l", qi) }} * {{ qn("corr", qi) }} + {{ qn("pSum", qi) }};
