{% set MASK_BATCH = "batch * params.maskBatchStride + " %}

// Online-softmax attention fallback with no feature requirements: one
// workgroup per (batch, head, query token) walks the keys serially; the
// workgroup cooperates on each q·k dot (compensated tree reduction) and on the
// running V accumulator, with the online rescale applied per key. This path
// requires no subgroup or subgroup-matrix features.
// Layout: rank-3 token-major [batch, seq, heads * headDim].
// An omitted scale uses 1/sqrt(headDim); explicit zero remains zero through
// the scaleIsExplicitZero specialization.
{% if hasMask %}
// Additive per-score attention bias with broadcast strides: a stride of 0
// collapses that axis (batch and/or head broadcast).
{% endif %}
const HEAD_DIM: u32 = {{ headDim }}u;
const Q_HIDDEN: u32 = {{ qHidden }}u;
const KV_HIDDEN: u32 = {{ kvHidden }}u;
const Q_HEADS: u32 = {{ qNumHeads }}u;
const KV_HEADS: u32 = {{ kvNumHeads }}u;
{% set qHeads = "Q_HEADS" %}
{% set kvHeads = "KV_HEADS" %}
const WG: u32 = {{ workgroupSize }}u;

{% set dotType = "f32" %}
// Retain product and addition residuals across a dot product. Explicit fma
// boundaries preserve the addition error transform under reassociation.
struct DotAccumulator {
  hi: {{ dotType }},
  lo: {{ dotType }},
}
fn dot_accumulate(acc: DotAccumulator, a: {{ dotType }}, b: {{ dotType }}) -> DotAccumulator {
  let product = fma(a, b, {{ dotType }}(0.0));
  let productError = fma(a, b, -product);
  let sum = fma(acc.hi, {{ dotType }}(1.0), product);
  let bv = fma({{ dotType }}(-1.0), acc.hi, sum);
  let av = fma({{ dotType }}(-1.0), bv, sum);
  let ae = fma({{ dotType }}(-1.0), av, acc.hi);
  let be = fma({{ dotType }}(-1.0), bv, product);
  let error = fma(fma(fma(ae, {{ dotType }}(1.0), be), {{ dotType }}(1.0), acc.lo), {{ dotType }}(1.0), productError);
  let hi = fma(sum, {{ dotType }}(1.0), error);
  return DotAccumulator(hi, fma({{ dotType }}(-1.0), fma({{ dotType }}(-1.0), sum, hi), error));
}
fn dot_value(acc: DotAccumulator) -> {{ dotType }} {
  return fma(acc.hi, {{ dotType }}(1.0), acc.lo);
}
