    output[qBase + d] = {{ outputScalar }}(running_out[d] * inv_denom);
  }
  // Separate this query's reads of the shared running state from the next
  // iteration's re-initialization (grid-stride; no-op when the loop runs once).
  workgroupBarrier();
  }
}

