{% if hasBias %}
    var acc0 = vec4<f32>(f32(bias[channel]));
    var acc1 = acc0;
{% else %}
    var acc0 = vec4<f32>(0.0);
    var acc1 = vec4<f32>(0.0);
{% endif %}
    // Each lane computes eight adjacent outputs and reuses a weight across them.
    var k = 0u;
