      acc0 = fma(x01, vec4<f32>(w.y), acc0);
      acc0 = fma(x02, vec4<f32>(w.z), acc0);
      acc0 = fma(x03, vec4<f32>(w.w), acc0);
      acc1 = fma(x10, vec4<f32>(w.x), acc1);
      acc1 = fma(x11, vec4<f32>(w.y), acc1);
      acc1 = fma(x12, vec4<f32>(w.z), acc1);
