        state_value = f32(input[bc * params.length + input_pos]);
      } else {
{% if hasState %}
        state_value = f32(past_state[bc * STATE_LENGTH + virtual_pos]);
{% endif %}
      }
      present_state[bc * STATE_LENGTH + s] = {{ outputScalar }}(state_value);
      s = s + WG;
