fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  if (gid.x != 0u) {
    return;
  }
{% if axisMode %}
  var written_axis = 0u;
  let limit = min(params.axisDim, params.conditionCount);
  for (var axis_i = 0u; axis_i < limit; axis_i = axis_i + 1u) {
    if (condition[axis_i] != 0u) {
      for (var outer_i = 0u; outer_i < params.outer; outer_i = outer_i + 1u) {
        for (var inner_i = 0u; inner_i < params.inner; inner_i = inner_i + 1u) {
          let input_i = (outer_i * params.axisDim + axis_i) * params.inner + inner_i;
          let output_i = (outer_i * params.outputAxisDim + written_axis) * params.inner + inner_i;
          output[output_i] = input[input_i];
        }
      }
      written_axis = written_axis + 1u;
    }
  }
{% else %}
  var written = 0u;
  let limit = min(params.inputCount, params.conditionCount);
  for (var i = 0u; i < limit; i = i + 1u) {
    if (condition[i] != 0u) {
      output[written] = input[i];
      written = written + 1u;
