// Rank-5 NCDHW im2col producer for Conv-as-GEMM.
//
// The column matrix is [K = C*KD*KH*KW, N = OD*OH*OW] per batch. Both
// flattening orders match the native OIDHW weight layout, so the following
// subgroup-matrix pass can view W directly as [M = outChannels, K].
// Geometry comes from tensor shapes and Conv attributes. Compiling it into
// constants removes invariant division and address work from
// the inner GEMM while retaining the complete rank-5 Conv contract.
{{ env.wgsl.resourceDeclarations }}

const KERNEL_D: u32 = {{ kernelDSpec }}u;
const KERNEL_H: u32 = {{ kernelHSpec }}u;
const KERNEL_W: u32 = {{ kernelWSpec }}u;
const KERNEL_PLANE: u32 = KERNEL_H * KERNEL_W;
const KERNEL_VOLUME: u32 = KERNEL_D * KERNEL_PLANE;
const STRIDE_D: u32 = {{ strideDSpec }}u;
const STRIDE_H: u32 = {{ strideHSpec }}u;
const STRIDE_W: u32 = {{ strideWSpec }}u;
const DILATION_D: u32 = {{ dilationDSpec }}u;
const DILATION_H: u32 = {{ dilationHSpec }}u;
const DILATION_W: u32 = {{ dilationWSpec }}u;
const PAD_FRONT: i32 = {{ padFrontSpec }};
const PAD_TOP: i32 = {{ padTopSpec }};
const PAD_LEFT: i32 = {{ padLeftSpec }};

@compute @workgroup_size({{ convWorkgroupSize }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let pos = gid.x;
  if (pos >= params.outCount) {
    return;
  }

  let k = gid.y;
  let batch = gid.z;
  let ic = k / KERNEL_VOLUME;
  var tap = k % KERNEL_VOLUME;
  let kd = tap / KERNEL_PLANE;
  tap %= KERNEL_PLANE;
  let kh = tap / KERNEL_W;
  let kw = tap % KERNEL_W;

  let outPlane = params.outH * params.outW;
  let od = pos / outPlane;
  let outOffset = pos % outPlane;
  let oh = outOffset / params.outW;
  let ow = outOffset % params.outW;

  let id = i32(od * STRIDE_D + kd * DILATION_D) - PAD_FRONT;
  let ih = i32(oh * STRIDE_H + kh * DILATION_H) - PAD_TOP;
  let iw = i32(ow * STRIDE_W + kw * DILATION_W) - PAD_LEFT;

  var value = 0.0;
  if (id >= 0 && id < i32(params.inD) &&
      ih >= 0 && ih < i32(params.inH) &&
      iw >= 0 && iw < i32(params.inW)) {
    let xIndex = (((batch * params.inChannels + ic) * params.inD + u32(id)) *
                  params.inH + u32(ih)) * params.inW + u32(iw);
    value = f32(x[xIndex]);
  }
  cols[(batch * params.kRows + k) * params.outCount + pos] = value;
}

