webgpu-kernels/ai.onnx.CumProd.cumprod-tiled-short-rows.wgsl.jinja:
// Ordered CumProd for many short, contiguous rows. A thread-per-row scan issues
// widely strided global accesses when the scan axis is innermost. This kernel
// first moves a batch of adjacent rows through shared memory with contiguous
// loads and stores. One lane then performs each row's serial product in the
// padded tile, preserving ONNX's element-by-element accumulation order. The
// extra column changes the shared-memory row stride and reduces conflict risk on
// banked implementations.
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;
const ROWS_PER_WG: u32 = {{ rowsPerWorkgroup }}u;
const ROW_STRIDE: u32 = {{ rowStride }}u;
var<workgroup> tile: array<{{ accType }}, {{ tileElements }}>;

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(workgroup_id) wg: vec3<u32>,
        @builtin(local_invocation_id) lid: vec3<u32>) {
  // 2D-folded tile index: wg.y carries the high bits past the dispatch limit.
  let rowBase = (wg.x + wg.y * {{ DISPATCH_FOLD_WIDTH }}u) * ROWS_PER_WG;
  if (rowBase >= params.rows) {
    return;
  }
  let activeRows = min(ROWS_PER_WG, params.rows - rowBase);
  let activeElements = activeRows * params.dim;

  // Contiguous cooperative input transfer into the padded row tile.
  for (var flat = lid.x; flat < activeElements; flat = flat + WG) {
    let localRow = flat / params.dim;
    let column = flat - localRow * params.dim;
    tile[localRow * ROW_STRIDE + column] =
        {{ accType }}(x[(rowBase + localRow) * params.dim + column]);
  }
  workgroupBarrier();

  // Each active lane owns one row. This deliberately stays serial: product is
  // not safely reassociative for floating point, and short rows expose enough
  // independent parallelism across the tile.
  if (lid.x < activeRows) {
    let localBase = lid.x * ROW_STRIDE;
    var acc: {{ accType }} = {% if accType == "f32" %}1.0{% elif accType == "i32" %}1i{% else %}1u{% endif %};
    for (var step = 0u; step < params.dim; step = step + 1u) {
{% if reverse %}
      let column = params.dim - 1u - step;
{% else %}
      let column = step;
{% endif %}
      let localIndex = localBase + column;
{% if exclusive %}
      let inputValue = tile[localIndex];
      tile[localIndex] = acc;
      acc = acc * inputValue;
{% else %}
      acc = acc * tile[localIndex];
      tile[localIndex] = acc;
{% endif %}
    }
  }
  workgroupBarrier();

  // Re-coalesce the output transfer across adjacent rows.
  for (var flat = lid.x; flat < activeElements; flat = flat + WG) {
    let localRow = flat / params.dim;
    let column = flat - localRow * params.dim;
    y[(rowBase + localRow) * params.dim + column] =
        {{ scalar }}(tile[localRow * ROW_STRIDE + column]);
  }
}

webgpu-kernels/ai.onnx.CumProd.scan-row-chunked.wgsl.jinja:
/* Workgroup-per-row chunked prefix scan. One workgroup scans one contiguous
 * row whose scan axis is innermost. A running carry links workgroup-sized
 * chunks, so one dispatch supports rows of any length. Each chunk uses either
 * a shared-memory Hillis-Steele sweep or a subgroup scan with cross-subgroup
 * carry. The ordered subgroup route defines its own lane order with
 * the shared logical-lane helper, so it assumes nothing about
 * how the device partitions local invocation indices into subgroups. */
/* Floating-point values accumulate in f32, including values loaded from f16
 * storage. Identity padding preserves partial-chunk NaN, infinity, and zero
 * propagation for products. Integer overflow wraps modulo 2^32, so tree
 * reassociation remains exact for i32 and u32. */
{% if useSubgroups %}
enable subgroups;
{% endif %}
{% set sg_inc = "subgroupInclusiveMul" %}
{% set sg_exc = "subgroupExclusiveMul" %}
{% set sg_tot = "subgroupMul" %}
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;
const IDENTITY: {{ accType }} = {% if accType == "f32" %}1.0{% elif accType == "i32" %}1i{% else %}1u{% endif %};

fn combine(a: {{ accType }}, b: {{ accType }}) -> {{ accType }} {
  return a * b;
}

{% if useSubgroups %}
var<workgroup> sgLaneClaims: atomic<u32>;

struct SubgroupLogicalLanes {
  ltid: u32,
  ord: u32,
  rank: u32,
  count: u32,
}

fn subgroup_logical_lanes(rank: u32, count: u32) -> SubgroupLogicalLanes {
  // Every lane performs the atomic so no collective follows a lane guard: a
  // subgroup op after a closed `if (rank == 0u)` block is a reconvergence
  // hazard, since every subgroup operation must be reached in uniform control
  // flow. Only the lane-0 lane adds its subgroup's claim, every other lane
  // adds 0 and discards its snapshot. Lane 0 is the lowest lane, which is the
  // lane `subgroupBroadcastFirst` reads.
  let ticket = atomicAdd(&sgLaneClaims, select(0u, count | (1u << 16u), rank == 0u));
  let claim = subgroupBroadcastFirst(ticket);
  return SubgroupLogicalLanes((claim & 0xffffu) + rank, claim >> 16u, rank, count);
}

fn subgroup_logical_count() -> u32 {
  return atomicLoad(&sgLaneClaims) >> 16u;
}
// One partial per subgroup, addressed by its logical ordinal. A workgroup of WG
// invocations holds at most WG subgroups at any adapter width, so WG is a sound
// bound with no width guard.
var<workgroup> sgTotals: array<{{ accType }}, WG>;

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(workgroup_id) wg: vec3<u32>,
        @builtin(subgroup_invocation_id) sgLane: u32,
        @builtin(subgroup_size) sgWidth: u32) {
  let row = wg.x;
  if (row >= params.rows) {
    return;
  }
  // `ltid` is the row position this invocation owns and `ord` its subgroup's
  // carry ordinal; both are dense and independent of the device's partition.
  let L = subgroup_logical_lanes(sgLane, sgWidth);
  let tid = L.ltid;
  workgroupBarrier();
  let numSub = subgroup_logical_count();
  let base = row * params.dim;
  var carry: {{ accType }} = IDENTITY;
  let chunks = (params.dim + WG - 1u) / WG;
  for (var c = 0u; c < chunks; c = c + 1u) {
    let j = c * WG + tid;
    let valid = j < params.dim;
{% if reverse %}
    let src = base + (params.dim - 1u - j);
{% else %}
    let src = base + j;
{% endif %}
    var v: {{ accType }} = IDENTITY;
    if (valid) {
      v = {{ accType }}(x[src]);
    }
    // Level 1: scan within each subgroup (collectives, no barriers).
    // `totSg` carries the subgroup total to level 2.
{% if exclusive %}
    let excSg = {{ sg_exc }}(v);
{% else %}
    let incSg = {{ sg_inc }}(v);
{% endif %}
    let totSg = {{ sg_tot }}(v);
    // Publish each subgroup's total, then every lane serially folds the
    // (<= numSub) totals into its own exclusive offset + the full chunk total.
    if (L.rank == 0u) {
      sgTotals[L.ord] = totSg;
    }
    workgroupBarrier();
    var sgOffset: {{ accType }} = IDENTITY;
    for (var s = 0u; s < L.ord; s = s + 1u) {
      sgOffset = combine(sgOffset, sgTotals[s]);
    }
    var chunkTotal: {{ accType }} = IDENTITY;
    for (var s = 0u; s < numSub; s = s + 1u) {
      chunkTotal = combine(chunkTotal, sgTotals[s]);
    }
{% if exclusive %}
    let value = combine(carry, combine(sgOffset, excSg));
{% else %}
    let value = combine(carry, combine(sgOffset, incSg));
{% endif %}
    if (valid) {
      y[src] = {{ scalar }}(value);
    }
    carry = combine(carry, chunkTotal);
    // Barrier before the next chunk overwrites sgTotals.
    workgroupBarrier();
  }
}
{% else %}
var<workgroup> wgScan: array<{{ accType }}, WG>;

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(workgroup_id) wg: vec3<u32>,
        @builtin(local_invocation_id) lid: vec3<u32>) {
  let row = wg.x;
  let tid = lid.x;
  if (row >= params.rows) {
    return;
  }
  let base = row * params.dim;
  var carry: {{ accType }} = IDENTITY;
  let chunks = (params.dim + WG - 1u) / WG;
  for (var c = 0u; c < chunks; c = c + 1u) {
    let j = c * WG + tid;
    let valid = j < params.dim;
{% if reverse %}
    let src = base + (params.dim - 1u - j);
{% else %}
    let src = base + j;
{% endif %}
    var v: {{ accType }} = IDENTITY;
    if (valid) {
      v = {{ accType }}(x[src]);
    }
    workgroupBarrier();
    wgScan[tid] = v;
    for (var step = 1u; step < WG; step = step << 1u) {
      workgroupBarrier();
      var prev: {{ accType }} = IDENTITY;
      if (tid >= step) {
        prev = wgScan[tid - step];
      }
      workgroupBarrier();
      wgScan[tid] = combine(prev, wgScan[tid]);
    }
    workgroupBarrier();
{% if exclusive %}
    var value = carry;
    if (tid > 0u) {
      value = combine(carry, wgScan[tid - 1u]);
    }
{% else %}
    let value = combine(carry, wgScan[tid]);
{% endif %}
    if (valid) {
      y[src] = {{ scalar }}(value);
    }
    carry = combine(carry, wgScan[WG - 1u]);
  }
}
{% endif %}

webgpu-kernels/ai.onnx.CumProd.scan-thread-row.wgsl.jinja:
// Thread-per-row serial product scan. Each thread owns one
// (outer, inner) row and accumulates serially along the scanned axis. Total work
// is O(numel), versus O(numel * dim) for a naive per-output-element kernel.
// At each scan step, consecutive threads access consecutive inner indices. The
// accumulation order is element-by-element in scan order.
{% macro flat_index_2d(workgroupSize, name="i", bound="params.count", guardInline=false) %}
{% set wgTerm = workgroupSize ~ "u" if workgroupSize is number else workgroupSize %}
  // 2D-folded flat index: gid.y carries the high bits past the dispatch's
  // per-axis workgroup fold width.
  let {{ name }} = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ wgTerm }};
  if ({{ name }} >= {{ bound }}) {
    return;
  }{% endmacro %}
{{ env.wgsl.resourceDeclarations }}

const IDENTITY: {{ accType }} = {% if accType == "f32" %}1.0{% elif accType == "i32" %}1i{% else %}1u{% endif %};

fn combine(a: {{ accType }}, b: {{ accType }}) -> {{ accType }} {
  return a * b;
}

@compute @workgroup_size({{ workgroupSize }}, 1, 1)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
{{ flat_index_2d(workgroupSize, "r", "params.rows") }}
  let outer_i = r / params.inner;
  let inner_i = r % params.inner;
  let base = outer_i * params.dim * params.inner + inner_i;
  var acc: {{ accType }} = IDENTITY;
  for (var step = 0u; step < params.dim; step = step + 1u) {
{% if reverse %}
    let d = params.dim - 1u - step;
{% else %}
    let d = step;
{% endif %}
    let idx = base + d * params.inner;
{% if exclusive %}
    y[idx] = {{ scalar }}(acc);
    acc = combine(acc, {{ accType }}(x[idx]));
{% else %}
    acc = combine(acc, {{ accType }}(x[idx]));
    y[idx] = {{ scalar }}(acc);
{% endif %}
  }
}

webgpu-kernels/ai.onnx.CumProd.scan-row-chunked-vec4.wgsl.jinja:
// Register-blocked vec4 workgroup-per-row prefix product scan on a
// forward innermost dimension divisible by four.
//
// Each thread owns four consecutive row elements as one vec4 load, scans them
// locally in registers, and the cooperative
// cross-thread scan runs over per-thread totals only. A workgroup therefore
// covers 4*WG elements per chunk while preserving one cross-thread
// contribution per lane.
//
// For a thread holding vv = elements [4j .. 4j+3], p0..p3 are its local
// inclusive prefixes and p3 is its local total. tbase combines the prior-chunk
// carry, earlier subgroups in this chunk, and earlier lanes in this subgroup,
// so it is the reduction of every element strictly before this thread's block.
// Inclusive output k is combine(tbase, p_k); exclusive output k uses p_{k-1},
// with p_{-1} equal to the identity.
{% set sg_exc = "subgroupExclusiveMul" %}
{% set sg_tot = "subgroupMul" %}
{% if useSubgroups %}
enable subgroups;
{% endif %}
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;
const IDENTITY: {{ accType }} = {% if accType == "f32" %}1.0{% elif accType == "i32" %}1i{% else %}1u{% endif %};

fn combine(a: {{ accType }}, b: {{ accType }}) -> {{ accType }} {
  return a * b;
}

{% if useSubgroups %}
var<workgroup> sgLaneClaims: atomic<u32>;

struct SubgroupLogicalLanes {
  ltid: u32,
  ord: u32,
  rank: u32,
  count: u32,
}

fn subgroup_logical_lanes(rank: u32, count: u32) -> SubgroupLogicalLanes {
  // Every lane performs the atomic so no collective follows a lane guard: a
  // subgroup op after a closed `if (rank == 0u)` block is a reconvergence
  // hazard, since every subgroup operation must be reached in uniform control
  // flow. Only the lane-0 lane adds its subgroup's claim, every other lane
  // adds 0 and discards its snapshot. Lane 0 is the lowest lane, which is the
  // lane `subgroupBroadcastFirst` reads.
  let ticket = atomicAdd(&sgLaneClaims, select(0u, count | (1u << 16u), rank == 0u));
  let claim = subgroupBroadcastFirst(ticket);
  return SubgroupLogicalLanes((claim & 0xffffu) + rank, claim >> 16u, rank, count);
}

fn subgroup_logical_count() -> u32 {
  return atomicLoad(&sgLaneClaims) >> 16u;
}
{% endif %}
var<workgroup> sgTotals: array<{{ accType }}, WG>;

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(workgroup_id) wg: vec3<u32>{% if useSubgroups %},
        @builtin(subgroup_invocation_id) sgLane: u32,
        @builtin(subgroup_size) sgWidth: u32{% else %},
        @builtin(local_invocation_id) lid: vec3<u32>{% endif %}) {
  let row = wg.x;
{% if not useSubgroups %}
  let tid = lid.x;
{% endif %}
  if (row >= params.rows) {
    return;
  }
  let base4 = row * params.dim4;  // vec4 element offset of this row
{% if useSubgroups %}
  // `ltid` is the vec4 block this invocation owns and `ord` its subgroup's carry
  // ordinal; both are dense and independent of the device's partition.
  let L = subgroup_logical_lanes(sgLane, sgWidth);
  let tid = L.ltid;
  workgroupBarrier();
  let numSub = subgroup_logical_count();
{% endif %}
  var carry: {{ accType }} = IDENTITY;
  let chunks = (params.dim4 + WG - 1u) / WG;
  for (var c = 0u; c < chunks; c = c + 1u) {
    let j = c * WG + tid;
    let valid = j < params.dim4;
    var vv: vec4<{{ accType }}> = vec4<{{ accType }}>(IDENTITY);
    if (valid) {
      vv = vec4<{{ accType }}>(x[base4 + j]);
    }
    // Local inclusive scan of the 4 lanes (registers, no barriers).
    let p0 = vv.x;
    let p1 = combine(p0, vv.y);
    let p2 = combine(p1, vv.z);
    let p3 = combine(p2, vv.w);
    // Cross-thread scan over per-thread totals (p3) within the chunk.
{% if useSubgroups %}
    let excSg = {{ sg_exc }}(p3);
    let totSg = {{ sg_tot }}(p3);
    if (L.rank == 0u) {
      sgTotals[L.ord] = totSg;
    }
    workgroupBarrier();
    var sgOffset: {{ accType }} = IDENTITY;
    for (var s = 0u; s < L.ord; s = s + 1u) {
      sgOffset = combine(sgOffset, sgTotals[s]);
    }
    var chunkTotal: {{ accType }} = IDENTITY;
    for (var s = 0u; s < numSub; s = s + 1u) {
      chunkTotal = combine(chunkTotal, sgTotals[s]);
    }
