    let chunkTotal = sgTotals[WG - 1u];
    let tbase = combine(carry, excPrefix);
{% endif %}
    var ov: vec4<{{ accType }}>;
{% if exclusive %}
    ov.x = tbase;
    ov.y = combine(tbase, p0);
    ov.z = combine(tbase, p1);
    ov.w = combine(tbase, p2);
{% else %}
    ov.x = combine(tbase, p0);
    ov.y = combine(tbase, p1);
    ov.z = combine(tbase, p2);
    ov.w = combine(tbase, p3);
{% endif %}
    if (valid) {
      y[base4 + j] = vec4<{{ scalar }}>(ov);
    }
    carry = combine(carry, chunkTotal);
    workgroupBarrier();
