// Blocked-axis scale and zero-point indexing for linear quantization.
{% macro flat_index_2d(workgroupSize, name="i", bound="params.count", guardInline=false) %}
{% set wgTerm = workgroupSize ~ "u" if workgroupSize is number else workgroupSize %}
  // 2D-folded flat index: gid.y carries the high bits past the dispatch's
  // per-axis workgroup fold width.
  let {{ name }} = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ wgTerm }};
  if ({{ name }} >= {{ bound }}) { return; }{% endmacro %}
{{ env.wgsl.resourceDeclarations }}

fn read_x(index: u32) -> i32 {
{% if xUnsigned %}
  return i32(x[index]);
{% else %}
  return x[index];
{% endif %}
}

fn read_zero({% if hasZero %}index: u32{% endif %}) -> i32 {
{% if hasZero %}
{% if xUnsigned %}
  return i32(x_zero_point[index]);
{% else %}
  return x_zero_point[index];
{% endif %}
{% else %}
  return 0;
{% endif %}
}

fn scale_index(index: u32) -> u32 {
  let inner_index = index % params.inner;
  let axis_index = (index / params.inner) % params.axisDim;
  let outer_index = index / (params.axisDim * params.inner);
  return (outer_index * params.scaleAxisDim + axis_index / params.blockSize) * params.inner + inner_index;
}

@compute @workgroup_size({{ tunables.WORKGROUP_SIZE }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
{{ flat_index_2d(tunables.WORKGROUP_SIZE, "index", guardInline=true) }}
  let scaleIndex = scale_index(index);
  let result = f32(read_x(index) - read_zero({% if hasZero %}scaleIndex{% endif %})) * f32(x_scale[scaleIndex]);
  y[index] = {{ yScalar }}(result);
}

