/* Workgroup-per-row chunked prefix scan. One workgroup scans one contiguous
 * row whose scan axis is innermost. A running carry links workgroup-sized
 * chunks, so one dispatch supports rows of any length. Each chunk uses either
 * a shared-memory Hillis-Steele sweep or a subgroup scan with cross-subgroup
 * carry. The ordered subgroup route defines its own lane order with
 * the shared logical-lane helper, so it assumes nothing about
 * how the device partitions local invocation indices into subgroups. */
/* Floating-point values accumulate in f32, including values loaded from f16
 * storage. Identity padding preserves partial-chunk NaN, infinity, and zero
 * propagation for products. Integer overflow wraps modulo 2^32, so tree
 * reassociation remains exact for i32 and u32. */
{% if useSubgroups %}
enable subgroups;
{% endif %}
{% set sg_inc = "subgroupInclusiveAdd" %}
{% set sg_exc = "subgroupExclusiveAdd" %}
{% set sg_tot = "subgroupAdd" %}
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;
const IDENTITY: {{ accType }} = {% if accType == "f32" %}0.0{% elif accType == "i32" %}0i{% else %}0u{% endif %};

fn combine(a: {{ accType }}, b: {{ accType }}) -> {{ accType }} {
  return a + b;
}

{% if useSubgroups %}
var<workgroup> sgLaneClaims: atomic<u32>;

struct SubgroupLogicalLanes {
  ltid: u32,
  ord: u32,
  rank: u32,
  count: u32,
}

fn subgroup_logical_lanes(rank: u32, count: u32) -> SubgroupLogicalLanes {
  // Every lane performs the atomic so no collective follows a lane guard: a
  // subgroup op after a closed `if (rank == 0u)` block is a reconvergence
  // hazard, since every subgroup operation must be reached in uniform control
  // flow. Only the lane-0 lane adds its subgroup's claim, every other lane
  // adds 0 and discards its snapshot. Lane 0 is the lowest lane, which is the
  // lane `subgroupBroadcastFirst` reads.
  let ticket = atomicAdd(&sgLaneClaims, select(0u, count | (1u << 16u), rank == 0u));
  let claim = subgroupBroadcastFirst(ticket);
  return SubgroupLogicalLanes((claim & 0xffffu) + rank, claim >> 16u, rank, count);
}

fn subgroup_logical_count() -> u32 {
  return atomicLoad(&sgLaneClaims) >> 16u;
}
// One partial per subgroup, addressed by its logical ordinal. A workgroup of WG
// invocations holds at most WG subgroups at any adapter width, so WG is a sound
// bound with no width guard.
var<workgroup> sgTotals: array<{{ accType }}, WG>;

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(workgroup_id) wg: vec3<u32>,
        @builtin(subgroup_invocation_id) sgLane: u32,
        @builtin(subgroup_size) sgWidth: u32) {
  let row = wg.x;
  if (row >= params.rows) {
    return;
  }
  // `ltid` is the row position this invocation owns and `ord` its subgroup's
  // carry ordinal; both are dense and independent of the device's partition.
  let L = subgroup_logical_lanes(sgLane, sgWidth);
  let tid = L.ltid;
  workgroupBarrier();
  let numSub = subgroup_logical_count();
  let base = row * params.dim;
  var carry: {{ accType }} = IDENTITY;
  let chunks = (params.dim + WG - 1u) / WG;
  for (var c = 0u; c < chunks; c = c + 1u) {
    let j = c * WG + tid;
    let valid = j < params.dim;
{% if reverse %}
    let src = base + (params.dim - 1u - j);
{% else %}
    let src = base + j;
{% endif %}
    var v: {{ accType }} = IDENTITY;
    if (valid) {
      v = {{ accType }}(x[src]);
    }
    // Level 1: scan within each subgroup (collectives, no barriers).
    // `totSg` carries the subgroup total to level 2.
{% if exclusive %}
    let excSg = {{ sg_exc }}(v);
{% else %}
    let incSg = {{ sg_inc }}(v);
{% endif %}
    let totSg = {{ sg_tot }}(v);
    // Publish each subgroup's total, then every lane serially folds the
    // (<= numSub) totals into its own exclusive offset + the full chunk total.
    if (L.rank == 0u) {
      sgTotals[L.ord] = totSg;
    }
    workgroupBarrier();
    var sgOffset: {{ accType }} = IDENTITY;
    for (var s = 0u; s < L.ord; s = s + 1u) {
      sgOffset = combine(sgOffset, sgTotals[s]);
    }
    var chunkTotal: {{ accType }} = IDENTITY;
    for (var s = 0u; s < numSub; s = s + 1u) {
      chunkTotal = combine(chunkTotal, sgTotals[s]);
    }
{% if exclusive %}
    let value = combine(carry, combine(sgOffset, excSg));
{% else %}
    let value = combine(carry, combine(sgOffset, incSg));
{% endif %}
    if (valid) {
      y[src] = {{ scalar }}(value);
    }
    carry = combine(carry, chunkTotal);
    // Barrier before the next chunk overwrites sgTotals.
    workgroupBarrier();
  }
}
{% else %}
var<workgroup> wgScan: array<{{ accType }}, WG>;

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(workgroup_id) wg: vec3<u32>,
        @builtin(local_invocation_id) lid: vec3<u32>) {
  let row = wg.x;
  let tid = lid.x;
  if (row >= params.rows) {
    return;
  }
  let base = row * params.dim;
