// an exclusive prefix: carries[row, segment] is the sum of all earlier segment
// totals in scan order. One thread walks each row serially, preserving that
// order; pass 3 adds the result to every element in the segment.
{% macro flat_index_2d(workgroupSize, name="i", bound="params.count", guardInline=false) %}
{% set wgTerm = workgroupSize ~ "u" if workgroupSize is number else workgroupSize %}
  // 2D-folded flat index: gid.y carries the high bits past the dispatch's
  // per-axis workgroup fold width.
  let {{ name }} = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ wgTerm }};
  if ({{ name }} >= {{ bound }}) {
    return;
  }{% endmacro %}
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;
const SPLIT: u32 = {{ split }}u;
const IDENTITY: {{ accType }} = {% if accType == "f32" %}0.0{% elif accType == "i32" %}0i{% elif accType == "u32" %}0u{% else %}{{ accType }}(0.0){% endif %};

fn combine(a: {{ accType }}, b: {{ accType }}) -> {{ accType }} {
  return a + b;
}

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
{{ flat_index_2d("WG", "row", "params.rows") }}
  let base = row * SPLIT;
  var acc: {{ accType }} = IDENTITY;
  for (var seg = 0u; seg < SPLIT; seg = seg + 1u) {
    carries[base + seg] = acc;
    acc = combine(acc, chunkTotals[base + seg]);
  }
}

