// Register-blocked vec4 workgroup-per-row prefix sum scan on a
// forward innermost dimension divisible by four.
//
// Each thread owns four consecutive row elements as one vec4 load, scans them
// locally in registers, and the cooperative
// cross-thread scan runs over per-thread totals only. A workgroup therefore
// covers 4*WG elements per chunk while preserving one cross-thread
// contribution per lane.
//
// For a thread holding vv = elements [4j .. 4j+3], p0..p3 are its local
// inclusive prefixes and p3 is its local total. tbase combines the prior-chunk
// carry, earlier subgroups in this chunk, and earlier lanes in this subgroup,
// so it is the reduction of every element strictly before this thread's block.
// Inclusive output k is combine(tbase, p_k); exclusive output k uses p_{k-1},
// with p_{-1} equal to the identity.
{% set sg_exc = "subgroupExclusiveAdd" %}
{% set sg_tot = "subgroupAdd" %}
{% if useSubgroups %}
enable subgroups;
{% endif %}
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;
const IDENTITY: {{ accType }} = {% if accType == "f32" %}0.0{% elif accType == "i32" %}0i{% else %}0u{% endif %};

fn combine(a: {{ accType }}, b: {{ accType }}) -> {{ accType }} {
  return a + b;
}

{% if useSubgroups %}
var<workgroup> sgLaneClaims: atomic<u32>;

struct SubgroupLogicalLanes {
  ltid: u32,
  ord: u32,
  rank: u32,
  count: u32,
}

fn subgroup_logical_lanes(rank: u32, count: u32) -> SubgroupLogicalLanes {
  // Every lane performs the atomic so no collective follows a lane guard: a
  // subgroup op after a closed `if (rank == 0u)` block is a reconvergence
  // hazard, since every subgroup operation must be reached in uniform control
  // flow. Only the lane-0 lane adds its subgroup's claim, every other lane
  // adds 0 and discards its snapshot. Lane 0 is the lowest lane, which is the
  // lane `subgroupBroadcastFirst` reads.
  let ticket = atomicAdd(&sgLaneClaims, select(0u, count | (1u << 16u), rank == 0u));
  let claim = subgroupBroadcastFirst(ticket);
  return SubgroupLogicalLanes((claim & 0xffffu) + rank, claim >> 16u, rank, count);
}

fn subgroup_logical_count() -> u32 {
  return atomicLoad(&sgLaneClaims) >> 16u;
}
{% endif %}
var<workgroup> sgTotals: array<{{ accType }}, WG>;

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(workgroup_id) wg: vec3<u32>{% if useSubgroups %},
        @builtin(subgroup_invocation_id) sgLane: u32,
        @builtin(subgroup_size) sgWidth: u32{% else %},
        @builtin(local_invocation_id) lid: vec3<u32>{% endif %}) {
  let row = wg.x;
{% if not useSubgroups %}
  let tid = lid.x;
{% endif %}
  if (row >= params.rows) {
    return;
  }
  let base4 = row * params.dim4;  // vec4 element offset of this row
{% if useSubgroups %}
  // `ltid` is the vec4 block this invocation owns and `ord` its subgroup's carry
  // ordinal; both are dense and independent of the device's partition.
  let L = subgroup_logical_lanes(sgLane, sgWidth);
  let tid = L.ltid;
  workgroupBarrier();
  let numSub = subgroup_logical_count();
{% endif %}
  var carry: {{ accType }} = IDENTITY;
  let chunks = (params.dim4 + WG - 1u) / WG;
  for (var c = 0u; c < chunks; c = c + 1u) {
    let j = c * WG + tid;
    let valid = j < params.dim4;
    var vv: vec4<{{ accType }}> = vec4<{{ accType }}>(IDENTITY);
    if (valid) {
      vv = vec4<{{ accType }}>(x[base4 + j]);
    }
    // Local inclusive scan of the 4 lanes (registers, no barriers).
    let p0 = vv.x;
    let p1 = combine(p0, vv.y);
    let p2 = combine(p1, vv.z);
    let p3 = combine(p2, vv.w);
    // Cross-thread scan over per-thread totals (p3) within the chunk.
{% if useSubgroups %}
    let excSg = {{ sg_exc }}(p3);
    let totSg = {{ sg_tot }}(p3);
    if (L.rank == 0u) {
      sgTotals[L.ord] = totSg;
    }
    workgroupBarrier();
    var sgOffset: {{ accType }} = IDENTITY;
    for (var s = 0u; s < L.ord; s = s + 1u) {
      sgOffset = combine(sgOffset, sgTotals[s]);
    }
    var chunkTotal: {{ accType }} = IDENTITY;
    for (var s = 0u; s < numSub; s = s + 1u) {
      chunkTotal = combine(chunkTotal, sgTotals[s]);
    }
    // Reduction of every element strictly before this thread's 4-block.
    let tbase = combine(carry, combine(sgOffset, excSg));
{% else %}
    // No-subgroup tier: workgroup Hillis-Steele inclusive scan over the per-thread
    // totals (p3). The exclusive prefix at tid is the reduction of every element in
    // earlier threads' 4-blocks; sgTotals[WG-1] is the full chunk total.
    workgroupBarrier();
    sgTotals[tid] = p3;
    for (var step = 1u; step < WG; step = step << 1u) {
      workgroupBarrier();
      var prev: {{ accType }} = IDENTITY;
      if (tid >= step) {
        prev = sgTotals[tid - step];
      }
      workgroupBarrier();
      sgTotals[tid] = combine(prev, sgTotals[tid]);
    }
    workgroupBarrier();
    var excPrefix: {{ accType }} = IDENTITY;
    if (tid > 0u) {
      excPrefix = sgTotals[tid - 1u];
    }
    let chunkTotal = sgTotals[WG - 1u];
