// Each tile transformed one residue class. Combine the classes at the desired
// frequency, retaining root and accumulation residuals through the final sum.
fn fft_residual_bin(transform_base: u32, frequency: u32) -> vec4<f32> {
  var real = vec2<f32>(0.0);
