// Input must be in [-pi, pi]. Returns (cos(x), sin(x)).
fn precise_sincos_centered(x: f32) -> vec2<f32> {
  var folded = x;
  var cosineSign = 1.0;
  if (folded > PRECISE_TRIG_HALF_PI) {
    folded = PRECISE_TRIG_PI - folded;
    cosineSign = -1.0;
  } else if (folded < -PRECISE_TRIG_HALF_PI) {
    folded = -PRECISE_TRIG_PI - folded;
    cosineSign = -1.0;
