// Reduce around the nearest quarter turn in integer space, including odd
// periods. The polynomial sees only [-pi/4, pi/4]. Division and pi/2 residuals
// avoid cancellation near cardinal roots. FFT lengths fit exact f32 integers.
fn fft_quarter_twiddle(phase: u32, period: u32, sign: f32) -> vec2<f32> {
  let p = phase % period;
  let quadrant = (4u * p + period / 2u) / period;
  let remainder = f32(i32(4u * p) - i32(quadrant * period));
  let t = remainder / f32(period);
  let tl = fma(-t, f32(period), remainder) / f32(period);
  let half_pi = 1.5707963705062866;
  let half_pi_low = -4.3711390001862426e-8;
  let x = t * half_pi;
  let xl = fma(tl, half_pi, fma(t, half_pi_low, fma(t, half_pi, -x)));
  let root = precise_sincos_half_pi(x);
  let c = fma(-root.y, xl, root.x);
  let s = fma(root.x, xl, root.y);
  switch (quadrant % 4u) {
    case 0u: { return vec2<f32>(c, sign * s); }
    case 1u: { return vec2<f32>(-s, sign * c); }
    case 2u: { return vec2<f32>(-c, -sign * s); }
    default: { return vec2<f32>(s, -sign * c); }
  }
