// Carry the rounding residual across butterfly stages and direct-tail sums.
// Explicit fma boundaries retain the error-free addition evaluation tree.
fn fft_pair_add(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
  let s = fma(a.x, 1.0, b.x);
  let bv = fma(-1.0, a.x, s);
  let av = fma(-1.0, bv, s);
  let ae = fma(-1.0, av, a.x);
  let be = fma(-1.0, bv, b.x);
  let e = fma(fma(fma(ae, 1.0, be), 1.0, a.y), 1.0, b.y);
  let hi = fma(s, 1.0, e);
  return vec2<f32>(hi, fma(-1.0, fma(-1.0, s, hi), e));
}

fn fft_pair_scale(a: vec2<f32>, b: f32) -> vec2<f32> {
  let p = fma(a.x, b, 0.0);
  let e = fma(a.y, b, fma(a.x, b, -p));
