@compute @workgroup_size({{ tunables.WORKGROUP_SIZE }})
fn main(
  @builtin(workgroup_id) wgid: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>,
  @builtin(num_workgroups) nwg: vec3<u32>,
) {
  let tid = lid.x;
  let transform = wgid.x + wgid.y * nwg.x;
  let transformBase = transform * N * 2u;

  let outerIndex = transform / params.inner;
  let innerIndex = transform - outerIndex * params.inner;

  for (var n = tid; n < N; n = n + WG) {
    var value = vec2<f32>(0.0);
    let inputBase = ((outerIndex * N + n) * params.inner + innerIndex) * {{ inComp }}u;
    value.x = {{ sample("inputBase") }};
{% if inComp == 2 %}
