fn sample(n: u32, c: u32, baseH: i32, baseW: i32, dy: f32, dx: f32) -> f32 {
  if (dy <= f32(-1 - baseH) || dy >= f32(i32(params.inH) - baseH)
      || dx <= f32(-1 - baseW) || dx >= f32(i32(params.inW) - baseW)) {
    return 0.0;
  }
  let dyFloor = floor(dy);
  let dxFloor = floor(dx);
  let h0 = baseH + i32(dyFloor);
  let w0 = baseW + i32(dxFloor);
  let h1 = h0 + 1;
  let w1 = w0 + 1;
  let lh = dy - dyFloor;
  let lw = dx - dxFloor;
  if (lh == 0.0 && lw == 0.0) {
    return x[((n * params.inChannels + c) * params.inH + u32(h0)) * params.inW + u32(w0)];
