// Shape-driven, register-blocked f32 GEMM for all four transpose combinations.
// Runtime M/N/K share one compiled pipeline for each tile configuration.
// Register micro-tiles reuse staged K slices; transpose modes change load strides and
// keep the stored-contiguous axis coalesced. M/N/K tails are bounds-checked
// unless an authored dimension proves that its tile has no tail.
// Both tiles are indexed by their own output axis and group four K values per
// vector word, so the micro-tile accumulates through dot() and one step reads
// TM + TN words instead of 4 * (TM + TN) scalars.
{% set epiOpen = "" %}
{% set epiClose = "" %}
{% set gemmTileRows = 64 %}
{% set gemmTileCols = 64 %}
{% set gemmMicroRows = 4 %}
{% set gemmMicroCols = 4 %}
{% set gemmWgX = 16 %}
{% set gemmWgY = 16 %}
{% set gemmTileK = 16 %}
const BK: u32 = {{ gemmTileK }}u;
const BM: u32 = {{ gemmTileRows }}u;
const BN: u32 = {{ gemmTileCols }}u;
const TM: u32 = {{ gemmMicroRows }}u;   // per-thread micro-tile rows
const TN: u32 = {{ gemmMicroCols }}u;   // per-thread micro-tile cols

// Stage tiles at the operands' storage width. For f16 inputs this is
// bit-identical to widening on shared load, keeps f32 FMA registers, and halves
// workgroup storage.
{% set tileT = OUT %}
const K_VECS: u32 = BK / 4u;
var<workgroup> tileA: array<array<vec4<{{ tileT }}>, K_VECS>, BM>;   // logical A'[m][k/4]
var<workgroup> tileB: array<array<vec4<{{ tileT }}>, K_VECS>, BN>;   // logical B'[n][k/4]

@compute @workgroup_size({{ gemmWgX }}, {{ gemmWgY }}, 1)
fn main(
  @builtin(workgroup_id) wg: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>,
  @builtin(num_workgroups) nwg: vec3<u32>
) {
  let li = lid.y * {{ gemmWgX }}u + lid.x;
  let M = params.M;
  let N = params.N;
  let K = params.K;
  let n_tiles = (N + BN - 1u) / BN;
  let m_tiles = (M + BM - 1u) / BM;
  for (var nt: u32 = wg.x; nt < n_tiles; nt = nt + nwg.x) {
    let nBase = nt * BN;
    for (var mt: u32 = wg.y; mt < m_tiles; mt = mt + nwg.y) {
      let mBase = mt * BM;

      var acc: array<f32, TM * TN>;
      for (var i: u32 = 0u; i < TM * TN; i = i + 1u) { acc[i] = 0.0; }

      let numTiles = (K + BK - 1u) / BK;
