          let ar = idx % BM;
          let ac4 = idx / BM;
{% else %}
          // A stored [M, K]: logical A[m,k] = a[m*K + k]. Coalesce on k (contiguous).
          let ar = idx / K_VECS;
          let ac4 = idx % K_VECS;
{% endif %}
          let am = mBase + ar;
          let ak = kBase + ac4 * 4u;
          var aWord = vec4<{{ tileT }}>({{ tileT }}(0.0));
          if (am < M) {
{% for component in range(4) %}
            if (ak + {{ component }}u < K) {
{% if transA %}
              aWord[{{ component }}u] = {{ tileT }}(a[(ak + {{ component }}u) * M + am]);
{% else %}
              aWord[{{ component }}u] = {{ tileT }}(a[am * K + ak + {{ component }}u]);
{% endif %}
            }
{% endfor %}
          }
          tileA[ar][ac4] = aWord;
        }
        for (var idx: u32 = li; idx < BN * K_VECS; idx = idx + {{ gemmWgX * gemmWgY }}u) {
{% if transB is defined and transB %}
          // B stored [N, K]: logical B[k,n] = b[n*K + k]. Coalesce on k (contiguous).
          let bc = idx / K_VECS;
          let br4 = idx % K_VECS;
{% else %}
          // B stored [K, N]: logical B[k,n] = b[k*N + n]. Coalesce on n (contiguous).
          let bc = idx % BN;
          let br4 = idx / BN;
{% endif %}
          let bn = nBase + bc;
          let bk = kBase + br4 * 4u;
