    for (var j: u32 = 0u; j < TN; j = j + 1u) {
      {{ regAccumulator }}[i * TN + j] = {{ regAccumulator }}[i * TN + j] + dot(av[i], bv[j]);
    }
  }
}
{% endfilter %}
        workgroupBarrier();
      }

      let m0 = mBase + lid.y * TM;
      let n0 = nBase + lid.x * TN;
      for (var ti: u32 = 0u; ti < TM; ti = ti + 1u) {
        let m = m0 + ti;
        if (m >= M) { continue; }
        for (var tj: u32 = 0u; tj < TN; tj = tj + 1u) {
          let n = n0 + tj;
