// logical [K,N] transpose, reducing conflict risk on banked implementations.
var<workgroup> tileB: array<array<f32, BN + 1u>, BK>;
{% else %}
var<workgroup> tileA: array<array<f32, BK>, BM>;
var<workgroup> tileB: array<array<f32, BN>, BK>;
{% endif %}

