            tileB[kk + 2u][bCol + 2u], tileB[kk + 2u][bCol + 3u]);
          let bv3 = vec4<f32>(
            tileB[kk + 3u][bCol + 0u], tileB[kk + 3u][bCol + 1u],
            tileB[kk + 3u][bCol + 2u], tileB[kk + 3u][bCol + 3u]);
