    let normed = (v - vec4<f32>(row_mean)) / vec4<f32>(denom);
    y[idx] = {{ vecType }}(normed * vec4<f32>(f32(scale[ch])) + vec4<f32>(f32(bias[ch])));
  }
{% else %}
  for (var i = tid; i < HIDDEN; i = i + WG) {
    let idx = base + i;
    let v = f32(x[idx]);
    let ch = g_ch_base + i / SPATIAL;
    let normed = (v - row_mean) / denom;
