webgpu-kernels/ai.onnx.GRU.gru-recur-gates-step.wgsl.jinja:
// GRU update/reset phase for one globally synchronized timestep. Workgroups
// tile hidden outputs; the following candidate dispatch consumes z and r*h.

fn clip_input(x: f32) -> f32 {
{% if hasClip %}
  return clamp(x, -{{ clip }}, {{ clip }});
{% else %}
  return x;
{% endif %}
}

fn sigmoid(x: f32) -> f32 {
  let clipped = clip_input(x);
  return 1.0 / (1.0 + exp(-clipped));
}
{% macro rnn_recurrent_packed_storage_gates_dot4_fn(name, result_type, array, gate_count) %}
struct {{ result_type }} {
{% for q in range(gate_count) %}
  g{{ q }}: vec4<f32>,
{% endfor %}
}

fn {{ name }}(
  acc_in: {{ result_type }}, first_gate: u32, h4: u32, state_base: u32,
) -> {{ result_type }} {
  var acc = acc_in;
  let hidden = params.hidden;
  let vec_hidden = hidden / 4u;
  for (var k = 0u; k < vec_hidden; k += 1u) {
    let j = 4u * k;
    let hv = {{ array }}[state_base + k];
{% for q in range(gate_count) %}
    let gate_base{{ q }} = (first_gate + {{ q }}u) * hidden * vec_hidden;
    let r{{ q }}0 = rpack[gate_base{{ q }} + (j + 0u) * vec_hidden + h4];
    let r{{ q }}1 = rpack[gate_base{{ q }} + (j + 1u) * vec_hidden + h4];
    let r{{ q }}2 = rpack[gate_base{{ q }} + (j + 2u) * vec_hidden + h4];
    let r{{ q }}3 = rpack[gate_base{{ q }} + (j + 3u) * vec_hidden + h4];
    acc.g{{ q }}.x += dot(hv, vec4<f32>(r{{ q }}0.x, r{{ q }}1.x, r{{ q }}2.x, r{{ q }}3.x));
    acc.g{{ q }}.y += dot(hv, vec4<f32>(r{{ q }}0.y, r{{ q }}1.y, r{{ q }}2.y, r{{ q }}3.y));
    acc.g{{ q }}.z += dot(hv, vec4<f32>(r{{ q }}0.z, r{{ q }}1.z, r{{ q }}2.z, r{{ q }}3.z));
    acc.g{{ q }}.w += dot(hv, vec4<f32>(r{{ q }}0.w, r{{ q }}1.w, r{{ q }}2.w, r{{ q }}3.w));
{% endfor %}
  }
  return acc;
}
{% endmacro %}

{{ env.wgsl.resourceDeclarations }}

{{ rnn_recurrent_packed_storage_gates_dot4_fn("recurrent_zr_dot4", "PackedGruZr", "y", 2) }}
const WG: u32 = {{ recurrentWorkgroupSize }}u;

@compute @workgroup_size({{ recurrentWorkgroupSize }})
fn main(
  @builtin(workgroup_id) wg_id: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>,
) {
  let vec_hidden = params.hidden / 4u;
  let h4 = wg_id.x * WG + lid.x;
  let batch_index = wg_id.y;
  if (h4 >= vec_hidden || batch_index >= params.batch) { return; }

  let x_row = params.t * params.batch + batch_index;
  var gates = PackedGruZr(
    b[h4] + b[3u * vec_hidden + h4] + xproj[(x_row * 3u + 0u) * vec_hidden + h4],
    b[vec_hidden + h4] + b[4u * vec_hidden + h4] + xproj[(x_row * 3u + 1u) * vec_hidden + h4],
  );
  var prev = vec4<f32>(0.0);
  if (params.t != 0u) {
    let prev_base = ((params.t - 1u) * params.batch + batch_index) * vec_hidden;
    prev = y[prev_base + h4];
    gates = recurrent_zr_dot4(gates, 0u, h4, prev_base);
  }

  let z = vec4<f32>(
    sigmoid(gates.g0.x), sigmoid(gates.g0.y), sigmoid(gates.g0.z), sigmoid(gates.g0.w));
  let reset = vec4<f32>(
    sigmoid(gates.g1.x), sigmoid(gates.g1.y), sigmoid(gates.g1.z), sigmoid(gates.g1.w));
  let state_offset = batch_index * vec_hidden + h4;
  z_gate[state_offset] = z;
  scaled_h[state_offset] = reset * prev;
}

webgpu-kernels/ai.onnx.GRU.rnn-sequence-mask.wgsl.jinja:
// Post-processes a forward, layout-0 recurrent result for arbitrary
// sequence_lens. This pass zeroes each padded tail and gathers the last valid
// state into Y_h.
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;

@compute @workgroup_size({{ workgroupSize }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>,
        @builtin(num_workgroups) nwg: vec3<u32>) {
  let stride = nwg.x * nwg.y * WG;
  let count = params.seq * params.batch * params.hidden;
  for (var i = gid.y * ({{ DISPATCH_FOLD_WIDTH }}u * WG) + gid.x; i < count; i += stride) {
    let h = i % params.hidden;
    let tb = i / params.hidden;
    let batch_index = tb % params.batch;
    let t = tb / params.batch;
    let seq_len = min(params.seq, u32(max(sequence_lens[batch_index], 0)));

    // One thread per final-state element gathers the last valid prefix state.
    // A zero-length sequence has an all-zero final state.
    if (t == 0u) {
      let state_offset = batch_index * params.hidden + h;
      if (seq_len == 0u) {
        y_h[state_offset] = 0.0;
      } else {
        let final_offset = ((seq_len - 1u) * params.batch + batch_index) * params.hidden + h;
        y_h[state_offset] = y[final_offset];
      }
    }

    if (t >= seq_len) {
      y[i] = 0.0;
    }
  }
}

