{% set tileSize = 32 %}
// Tiled 2D transpose (optionally batched) over vec4 elements.
//
// Layout contract:
// - src is row-major [batch, ROWS, COLS], dst is row-major [batch, COLS, ROWS]
// - ROWS % 4 == 0 and COLS % 4 == 0, so both buffers bind as vec4<T>
// - dispatch: x = ceil(COLS / TILE), y = ceil(ROWS / TILE), z = batch
//
// Each (TILE / 4) x TILE workgroup moves one TILE x TILE scalar tile through
// workgroup memory.
// Global loads and stores each traverse consecutive vec4 addresses. The extra
// workgroup-memory column changes the transposed stride and reduces
// bank-conflict risk on banked implementations.
{{ env.wgsl.resourceDeclarations }}

const ROWS: u32 = {{ rowCount }}u;
const COLS: u32 = {{ cols }}u;
const ROWS_V: u32 = {{ ((rowCount / 4) | int) }}u;
const COLS_V: u32 = {{ ((cols / 4) | int) }}u;
const MAT_V: u32 = {{ (((rowCount * cols * (transposePlaneMiddle | default(1))) / 4) | int) }}u;
const TILE: u32 = {{ tileSize }}u;

var<workgroup> tile: array<array<{{ scalar }}, {{ tileSize + 1 }}>, {{ tileSize }}>;

@compute @workgroup_size({{ (tileSize / 4) | int }}, {{ tileSize }}, 1)
fn main(
  @builtin(workgroup_id) wid: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>
) {
  let batch_base = wid.z * MAT_V;
  let row_base = wid.y * TILE;
  let col_base = wid.x * TILE;

  let r = row_base + lid.y;
  let cv = (col_base / 4u) + lid.x;
  if (r < ROWS && cv < COLS_V) {
    let v = src[batch_base + r * COLS_V + cv];
    tile[lid.y][lid.x * 4u + 0u] = v.x;
    tile[lid.y][lid.x * 4u + 1u] = v.y;
    tile[lid.y][lid.x * 4u + 2u] = v.z;
    tile[lid.y][lid.x * 4u + 3u] = v.w;
  }
  workgroupBarrier();

  let out_row = col_base + lid.y;
  let rv = (row_base / 4u) + lid.x;
  if (out_row < COLS && rv < ROWS_V) {
    dst[batch_base + out_row * ROWS_V + rv] = {{ vectorScalar }}(
      tile[lid.x * 4u + 0u][lid.y],
      tile[lid.x * 4u + 1u][lid.y],
      tile[lid.x * 4u + 2u][lid.y],
      tile[lid.x * 4u + 3u][lid.y]
    );
  }
}

