// Parallel GRU forward for hidden state that does not fit workgroup storage.
// One workgroup owns each batch element, with storageBarrier() sequencing the
// timestep stages over storage-backed state and gates. Bias, input, and recurrent
// terms accumulate in that order. The reset-scaled state is folded into the
// candidate dot as left-associative `(r * h) * R` to preserve rounding.
//
// prev_h, z_gate, r_gate, and new_h are equal, disjoint slices of one storage
// binding. SCRATCH_REGION is batch * hidden; keep every slice on that extent and
// use [region + h_base + h] indexing.
{% set vec4Tail = vec4Tail is defined and vec4Tail %}

fn clip_input(x: f32) -> f32 {
{% if hasClip %}
  return clamp(x, -{{ clip }}, {{ clip }});
{% else %}
  return x;
{% endif %}
}

fn sigmoid(x: f32) -> f32 {
  let clipped = clip_input(x);
  return 1.0 / (1.0 + exp(-clipped));
}

fn tanh_safe(x: f32) -> f32 {
  // tanh rounds to +/-1 for these tails in f32. Return the saturated value
  // directly, including for infinite input, before invoking the builtin.
  if (x > 10.0) { return 1.0; }
  if (x < -10.0) { return -1.0; }
  return tanh(x);
}

// Input projection: acc_in + sum_i x[x_row, i] * w[w_row, i]. The contraction
// visits i in ascending order after seeding the accumulator with acc_in.
fn input_dot(acc_in: f32, x_row: u32, w_row: u32) -> f32 {
  var acc = acc_in;
{% if useVec4 or useInputVec4 %}
