  // assembled vec4s, then a scalar remainder over inputSize % 4. dot(vec4(...))
  // over 4 contiguous f32 is bit-identical to a vec4-load dot. The scalar tail
  // retains ascending term order.
  let x_base = x_row * params.inputSize;
  let w_base = w_row * params.inputSize;
  let vec_input = params.inputSize / 4u;
  for (var i = 0u; i < vec_input; i = i + 1u) {
    let xb = x_base + 4u * i;
    let wb = w_base + 4u * i;
    let xv = vec4<f32>(x[xb], x[xb + 1u], x[xb + 2u], x[xb + 3u]);
    let wv = vec4<f32>(w[wb], w[wb + 1u], w[wb + 2u], w[wb + 3u]);
    acc = acc + dot(xv, wv);
  }
  for (var i = vec_input * 4u; i < params.inputSize; i = i + 1u) {
    acc = acc + x[x_base + i] * w[w_base + i];
  }
{% else %}
