{% if useVec4 %}
      let vec_hidden = hidden / 4u;
      let r_base = gate_h * vec_hidden;
      for (var rh4 = 0u; rh4 < vec_hidden; rh4 = rh4 + 1u) {
        let rh = 4u * rh4;
