  sinPolynomial = fma(sinPolynomial, x2, -1.984126984126984e-4);
  sinPolynomial = fma(sinPolynomial, x2, 8.333333333333333e-3);
  sinPolynomial = fma(sinPolynomial, x2, -1.6666666666666666e-1);
