  cosPolynomial = fma(cosPolynomial, x2, 2.48015873015873e-5);
  cosPolynomial = fma(cosPolynomial, x2, -1.388888888888889e-3);
  cosPolynomial = fma(cosPolynomial, x2, 4.1666666666666664e-2);
