// A lane's TILE_V components are adjacent, so they are stored as one {{ redT }} word
// and fold with {{ redWidth }}-wide adds in the scalar fold's per-component order.
// Folds stay within each lane group: groups own disjoint value tiles and
// must not see each other's partials.
var<workgroup> wg_fold: array<{{ redT }}, WG * {{ redSlots }}u>;
var<workgroup> wg_fold_out: array<{{ redT }}, DV_GROUPS * {{ redSlots }}u>;
{% endif %}
@compute @workgroup_size(WG, 1, 1)
fn main(
  @builtin(workgroup_id) wg: vec3<u32>,
{% if useSubgroups %}
  @builtin(subgroup_invocation_id) sgLane: u32,
  @builtin(subgroup_size) sgWidth: u32,
{% else %}
  @builtin(local_invocation_id) lid: vec3<u32>,
{% endif %}
) {
{% if useSubgroups %}
  // Subgroup tier: selection admits this arm only on adapters whose fixed subgroup
  // width equals LANES, so every subgroup of the workgroup is exactly one lane group
  // and subgroupAdd over it is the group's reduction. The group and the lane come from
  // the subgroup itself -- the dense claim order of the subgroup and the invocation's
  // dense rank among its active lanes -- not from a partition of local_invocation_id,
  // because WGSL does not promise which invocations share a subgroup.
  let L = subgroup_logical_lanes(sgLane, sgWidth);
  let lane = L.rank;
  let dv_group = L.ord;
{% else %}
  let tid = lid.x;
  let lane = tid % LANES;
  let dv_group = tid / LANES;
{% endif %}
  let dk_base = lane * VEC4_LANES;
{{ emit_tiled_setup(dvGroups=(2 if useSubgroups else dvGroups)) }}
  let lane_active = dk_base < head_dim_k;

  // state[j] holds 4 consecutive dk rows (the 4 components) for dv slot j.
  var state: array<vec4<f32>, TILE_V>;
  for (var j = 0u; j < TILE_V; j = j + 1u) {
    state[j] = vec4<f32>(0.0);
  }
{% if hasPastState %}

  if (lane_active) {
    let state_row_base = ((batch_idx * params.kvNumHeads + head_idx) * head_dim_k + dk_base) * head_dim_v + dv_start;
    for (var j = 0u; j < TILE_V; j = j + 1u) {
      if (dv_start + j < head_dim_v) {
        state[j] = vec4<f32>(
          {{ read_scalar("past_state", "state_row_base + 0u * head_dim_v + j", stateDtype) }},
          {{ read_scalar("past_state", "state_row_base + 1u * head_dim_v + j", stateDtype) }},
          {{ read_scalar("past_state", "state_row_base + 2u * head_dim_v + j", stateDtype) }},
          {{ read_scalar("past_state", "state_row_base + 3u * head_dim_v + j", stateDtype) }},
        );
      }
    }
  }

{% endif %}
  // A token's key and query do not depend on the recurrent state. Fetch t+1
  // before completing the reductions for t so the independent load is issued
  // ahead of its first use.
{% macro load_key(token) %}
    if (lane_active) {
      let k_base = ({{ token }} * params.kPackedDim + key_head_idx * head_dim_k) / VEC4_LANES + lane;
      k_next = vec4<f32>(key[k_base]);
    }{% endmacro %}
{% if usesBeta %}
{% macro load_query0(token) %}
    if (lane_active) {
      let q0_base = ({{ token }} * params.qPackedDim + q_head_0 * head_dim_k) / VEC4_LANES + lane;
      q0_next = vec4<f32>(query[q0_base]);
    }{% endmacro %}
  let q_head_0 = (head_idx * params.qNumHeads) / params.kvNumHeads;
  let out_head_0 = head_idx * heads_per_group;
  var q0_next = vec4<f32>(0.0);
{% endif %}
  var k_next = vec4<f32>(0.0);
  let bt_first = batch_idx * params.seqLength;
{{ load_key("bt_first") }}
{% if usesBeta %}
{{ load_query0("bt_first") }}
{% endif %}
  for (var t = 0u; t < params.seqLength; t = t + 1u) {
    let bt = batch_idx * params.seqLength + t;

    let k_vec = k_next;
{% if usesBeta %}
    let q0_vec = q0_next;
{% endif %}
    // Issued here, consumed on the next trip.
    let bt_next = bt + 1u;
    if (t + 1u < params.seqLength) {
{{ load_key("bt_next") }}
{% if usesBeta %}
{{ load_query0("bt_next") }}
{% endif %}
    }
{% if usesDecay %}

    var decay_vec = vec4<f32>(1.0);
    if (params.decayPackedDim == params.kvNumHeads) {
      let factor = exp({{ read_scalar("decay", "bt * params.kvNumHeads + head_idx", queryDtype) }});
      decay_vec = vec4<f32>(factor);
    } else if (lane_active) {
      let decay_base = bt * params.decayPackedDim + head_idx * head_dim_k + dk_base;
      decay_vec = vec4<f32>(
        exp({{ read_scalar("decay", "decay_base + 0u", queryDtype) }}),
        exp({{ read_scalar("decay", "decay_base + 1u", queryDtype) }}),
        exp({{ read_scalar("decay", "decay_base + 2u", queryDtype) }}),
        exp({{ read_scalar("decay", "decay_base + 3u", queryDtype) }}),
      );
    }
    for (var j = 0u; j < TILE_V; j = j + 1u) {
      state[j] = state[j] * decay_vec;
    }

{% endif %}
{% if usesBeta %}
    var ret_vals: array<f32, TILE_V>;
    var pre_vals: array<f32, TILE_V>;
{% if useSubgroups %}
    let kq_dot = subgroupAdd(dot(k_vec, q0_vec));
    for (var j = 0u; j < TILE_V; j = j + 1u) {
      ret_vals[j] = subgroupAdd(dot(state[j], k_vec));
      pre_vals[j] = subgroupAdd(dot(state[j], q0_vec));
    }
{% else %}
    // kq and both state projections are known before any of them is consumed, so all
    // three stage together and cross one barrier pair rather than two.
{% for v in range(redVecs) %}
    wg_fold[{{ v }}u * WG + tid] = {{ redT }}({% for c in range(redWidth) %}dot(state[{{ v * redWidth + c }}], k_vec){{ ", " if not loop.last else "" }}{% endfor %});
    wg_fold[{{ redVecs + v }}u * WG + tid] = {{ redT }}({% for c in range(redWidth) %}dot(state[{{ v * redWidth + c }}], q0_vec){{ ", " if not loop.last else "" }}{% endfor %});
{% endfor %}
    wg_fold[{{ 2 * redVecs }}u * WG + tid] = {{ redT }}(dot(k_vec, q0_vec){% for c in range(redWidth - 1) %}, 0.0{% endfor %});
    workgroupBarrier();
    for (var sl = lane; sl < {{ redSlots }}u; sl = sl + LANES) {
      var t = {{ redT }}(0.0);
      for (var i = 0u; i < LANES; i = i + 1u) {
        t = t + wg_fold[sl * WG + dv_group * LANES + i];
      }
      wg_fold_out[dv_group * {{ redSlots }}u + sl] = t;
    }
    workgroupBarrier();
    let kq_dot = wg_fold_out[dv_group * {{ redSlots }}u + {{ 2 * redVecs }}u]{{ ("." ~ redComps[0]) if redWidth > 1 else "" }};
{% for j in range(tileV) %}
    ret_vals[{{ j }}] = wg_fold_out[dv_group * {{ redSlots }}u + {{ (j / redWidth)|int }}u]{{ ("." ~ redComps[j % redWidth]) if redWidth > 1 else "" }};
    pre_vals[{{ j }}] = wg_fold_out[dv_group * {{ redSlots }}u + {{ redVecs + (j / redWidth)|int }}u]{{ ("." ~ redComps[j % redWidth]) if redWidth > 1 else "" }};
{% endfor %}
{% endif %}

    var beta_idx = bt * params.kvNumHeads + head_idx;
    if (params.betaPackedDim == 1u) {
      beta_idx = bt;
    }
    let beta_val = {{ read_scalar("beta", "beta_idx", queryDtype) }};
    let v_base = bt * params.vPackedDim + head_idx * head_dim_v + dv_start;
    let out_base = bt * packed_out + out_head_0 * head_dim_v + dv_start;
    var deltas: array<f32, TILE_V>;
    for (var j = 0u; j < TILE_V; j = j + 1u) {
      if (dv_start + j < head_dim_v) {
        let v_val = {{ read_scalar("value", "v_base + j", queryDtype) }};
        let delta_j = beta_val * (v_val - ret_vals[j]);
        deltas[j] = delta_j;
        if (lane == 0u) {
          output[out_base + j] = {{ write_scalar("(pre_vals[j] + delta_j * kq_dot) * scale", queryDtype) }};
        }
      } else {
        deltas[j] = 0.0;
      }
    }

    for (var j = 0u; j < TILE_V; j = j + 1u) {
      state[j] = state[j] + k_vec * deltas[j];
    }

{{ emit_vec4_query_groups(1) }}
{% else %}
    let v_base = bt * params.vPackedDim + head_idx * head_dim_v + dv_start;
    for (var j = 0u; j < TILE_V; j = j + 1u) {
      if (dv_start + j < head_dim_v) {
        let v_val = {{ read_scalar("value", "v_base + j", queryDtype) }};
        state[j] = state[j] + k_vec * v_val;
      }
    }

{{ emit_vec4_query_groups(0) }}
{% endif %}
  }

  if (lane_active) {
    let state_row_base = ((batch_idx * params.kvNumHeads + head_idx) * head_dim_k + dk_base) * head_dim_v + dv_start;
    for (var j = 0u; j < TILE_V; j = j + 1u) {
      if (dv_start + j < head_dim_v) {
        present_state[state_row_base + 0u * head_dim_v + j] = {{ write_scalar("state[j].x", stateDtype) }};
        present_state[state_row_base + 1u * head_dim_v + j] = {{ write_scalar("state[j].y", stateDtype) }};
        present_state[state_row_base + 2u * head_dim_v + j] = {{ write_scalar("state[j].z", stateDtype) }};
        present_state[state_row_base + 3u * head_dim_v + j] = {{ write_scalar("state[j].w", stateDtype) }};
      }
    }
  }
}

