fn main(@builtin(workgroup_id) wg: vec3<u32>,
        @builtin(local_invocation_id) lid: vec3<u32>) {
  let block = wg.x;
  let row = wg.y;
  let rowBase = row * params.cols;
  let colStart = block * BLOCK_COLS;
  let colEnd = min(params.cols, colStart + BLOCK_COLS);

