  // derived from the row sum (a constant NaN bit pattern is rejected at
  // WGSL const-evaluation).
  let rowIsNan = m > FLT_MAX || is_nan_f32(d) || d == 0.0;
  let nanOut = bitcast<f32>(bitcast<u32>(d) | 0x7fc00000u);
