// one contiguous load per channel while retaining f32 accumulation.
const WG: u32 = {{ workgroupSizeSpec }}u;

@compute @workgroup_size({{ workgroupSizeSpec }})
fn main(
  @builtin(global_invocation_id) gid: vec3<u32>,
  @builtin(num_workgroups) nwg: vec3<u32>
) {
  let stride = nwg.x * WG;
  for (var index = gid.x; index < params.{% if vectorized %}countVec{% else %}count{% endif %}; index += stride) {
    let widthSlot = index % params.{% if vectorized %}widthVec{% else %}width{% endif %};
    var outerIndex = index / params.{% if vectorized %}widthVec{% else %}width{% endif %};
    let h = outerIndex % params.height;
    outerIndex = outerIndex / params.height;
    let c = outerIndex % params.channels;
    let n = outerIndex / params.channels;

    // ONNX window: max(0, c - floor((size-1)/2)) .. min(C-1, c + ceil((size-1)/2)).
    // An even size reaches one channel further ahead than behind (size=4: c-1..c+2).
    let before = (params.size - 1u) / 2u;
    let after = params.size - 1u - before;
    let first = select(0u, c - before, c > before);
    let last = min(params.channels - 1u, c + after);
{% if vectorized %}
    var sumSq = vec4<f32>(0.0);
{% else %}
    var sumSq = 0.0;
{% endif %}
    for (var jc = first; jc <= last; jc = jc + 1u) {
