webgpu-kernels/ai.onnx.LpNormalization.lp-norm-reduce.wgsl.jinja:
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;
{% if segmented %}
const SPLIT: u32 = {{ split }}u;

{% endif %}
{% if segmented %}
// Reduce a strided normalization axis in segments. Workgroup rows divide a long
// axis and write partial sums for the final reduction.
{% else %}
// Reduce a strided normalization axis and write the finished norm directly.
{% endif %}
// Logical rows use a grid-stride loop so the dispatch limit cannot truncate the
// tensor.
@compute @workgroup_size(WG)
fn main(
  @builtin(global_invocation_id) gid: vec3<u32>,
{% if segmented %}
  @builtin(workgroup_id) wid: vec3<u32>,
{% endif %}
  @builtin(num_workgroups) nwg: vec3<u32>
) {
  let stride = nwg.x * WG;
{% if segmented %}
  let segment = wid.y;
  let chunk = (params.dim + SPLIT - 1u) / SPLIT;
  let begin = segment * chunk;
  let end = min(begin + chunk, params.dim);
{% else %}
  let begin = 0u;
  let end = params.dim;
{% endif %}
  for (var r = gid.x; r < params.rows; r += stride) {
    let outer_i = r / params.inner;
    let inner_i = r % params.inner;
    let base = outer_i * params.dim * params.inner + inner_i;
    var norm = 0.0;
    for (var j = begin; j < end; j += 1u) {
      let v = f32(input[base + j * params.inner]);
      norm += select(v * v, abs(v), params.p == 1u);
    }
{% if segmented %}
    normOutput[segment * params.rows + r] = norm;
{% else %}
    if (params.p == 2u) { norm = sqrt(norm); }
    normOutput[r] = norm;
{% endif %}
  }
}

