// windows. The p-norm is accumulated in f32 (sum of
// |x|^p over the 2x2 window, same four elements / same count as the scalar
// fallback) and reduced by the p-th root; p=2 specialises to sum-of-squares +
// sqrt, p=1 to sum-of-abs.
const OUT_W: u32 = {{ outW }}u;        // == IN_W / 2 (no pad, stride 2)
const OUT_H: u32 = {{ outH }}u;
const OUT_W_HALF: u32 = {{ outWHalf }}u;
const IN_W_VEC4: u32 = {{ inWVec4 }}u; // input row length in vec4 units
const IN_PLANE_VEC4: u32 = {{ inPlaneVec4 }}u;
{% if p != 1 and p != 2 %}
const P: f32 = f32({{ p }});
{% endif %}

