// Post-processes a forward, layout-0 recurrent result for arbitrary
// sequence_lens. This pass zeroes each padded tail and gathers the last valid
// state into Y_h.
// It also gathers Y_c from the per-timestep cell history.
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;

@compute @workgroup_size({{ workgroupSize }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>,
        @builtin(num_workgroups) nwg: vec3<u32>) {
  let stride = nwg.x * nwg.y * WG;
  let count = params.seq * params.batch * params.hidden;
  for (var i = gid.y * ({{ DISPATCH_FOLD_WIDTH }}u * WG) + gid.x; i < count; i += stride) {
    let h = i % params.hidden;
    let tb = i / params.hidden;
    let batch_index = tb % params.batch;
    let t = tb / params.batch;
    let seq_len = min(params.seq, u32(max(sequence_lens[batch_index], 0)));

    // One thread per final-state element gathers the last valid prefix state.
    // A zero-length sequence has an all-zero final state.
    if (t == 0u) {
      let state_offset = batch_index * params.hidden + h;
      if (seq_len == 0u) {
        y_h[state_offset] = 0.0;
        y_c[state_offset] = 0.0;
      } else {
        let final_offset = ((seq_len - 1u) * params.batch + batch_index) * params.hidden + h;
        y_h[state_offset] = y[final_offset];
        y_c[state_offset] = cell_history[final_offset];
      }
    }

    if (t >= seq_len) {
      y[i] = 0.0;
    }
  }
}

