// This uses an exact Sterbenz scaled-subtraction reduction: each
// `x - scaled` is exact because `scaled <= x < 2*scaled`, and scaling by powers
// of two is exact, so the final remainder carries no rounding error.
fn fmod_trunc(a: f32, b: f32) -> f32 {
  let aa = abs(a);
  let ab = abs(b);
