fn box_corners(batch: u32, box: u32) -> vec4<f32> {
  let offset = box_offset(batch, box);
  let v0 = boxes[offset];
  let v1 = boxes[offset + 1u];
  let v2 = boxes[offset + 2u];
  let v3 = boxes[offset + 3u];
