  return iou_between_corners(box_corners(batch, a), b_box);
}

fn iou_between_corners(a_box: vec4<f32>, b_box: vec4<f32>) -> f32 {
  let ay1_raw = a_box.x;
  let ax1_raw = a_box.y;
  let ay2_raw = a_box.z;
  let ax2_raw = a_box.w;
  let by1_raw = b_box.x;
  let bx1_raw = b_box.y;
  let by2_raw = b_box.z;
  let bx2_raw = b_box.w;
  let ay1 = min(ay1_raw, ay2_raw);
  let ax1 = min(ax1_raw, ax2_raw);
  let ay2 = max(ay1_raw, ay2_raw);
  let ax2 = max(ax1_raw, ax2_raw);
  let by1 = min(by1_raw, by2_raw);
  let bx1 = min(bx1_raw, bx2_raw);
  let by2 = max(by1_raw, by2_raw);
  let bx2 = max(bx1_raw, bx2_raw);
  let inter_y1 = max(ay1, by1);
  let inter_x1 = max(ax1, bx1);
  let inter_y2 = min(ay2, by2);
  let inter_x2 = min(ax2, bx2);
  let inter = max(0.0, inter_y2 - inter_y1) * max(0.0, inter_x2 - inter_x1);
  let area_a = max(0.0, ay2 - ay1) * max(0.0, ax2 - ax1);
  let area_b = max(0.0, by2 - by1) * max(0.0, bx2 - bx1);
