// Greedy NMS over bounded sorted-rank windows. Every subsequent window checks
// all earlier selections; no fixed top-L prefix truncates the candidate set.
{{ env.wgsl.resourceDeclarations }}
const WG: u32 = {{ workgroupSize }}u;
const WINDOW_WORDS: u32 = WG / 32u;
const SORT_N: u32 = {{ sortN }}u;
const MAX_KEEP: u32 = {{ maxKeepSpec }}u;
const INVALID: u32 = 0xffffffffu;

fn box_offset(batch: u32, box: u32) -> u32 {
  return (batch * params.boxesPerBatch + box) * 4u;
}

fn box_corners(batch: u32, box: u32) -> vec4<f32> {
  let offset = box_offset(batch, box);
  let v0 = boxes[offset];
  let v1 = boxes[offset + 1u];
  let v2 = boxes[offset + 2u];
  let v3 = boxes[offset + 3u];
  if (params.centerPointBox != 0u) {
    let x_center = v0;
    let y_center = v1;
    let half_w = v2 * 0.5;
    let half_h = v3 * 0.5;
    return vec4<f32>(y_center - half_h, x_center - half_w, y_center + half_h, x_center + half_w);
  }
  return vec4<f32>(v0, v1, v2, v3);
}

fn iou_with_box(batch: u32, a: u32, b_box: vec4<f32>) -> f32 {
  return iou_between_corners(box_corners(batch, a), b_box);
}

fn iou_between_corners(a_box: vec4<f32>, b_box: vec4<f32>) -> f32 {
  let ay1_raw = a_box.x;
  let ax1_raw = a_box.y;
  let ay2_raw = a_box.z;
  let ax2_raw = a_box.w;
  let by1_raw = b_box.x;
  let bx1_raw = b_box.y;
  let by2_raw = b_box.z;
  let bx2_raw = b_box.w;
  let ay1 = min(ay1_raw, ay2_raw);
  let ax1 = min(ax1_raw, ax2_raw);
  let ay2 = max(ay1_raw, ay2_raw);
  let ax2 = max(ax1_raw, ax2_raw);
  let by1 = min(by1_raw, by2_raw);
  let bx1 = min(bx1_raw, bx2_raw);
  let by2 = max(by1_raw, by2_raw);
  let bx2 = max(bx1_raw, bx2_raw);
  let inter_y1 = max(ay1, by1);
  let inter_x1 = max(ax1, bx1);
  let inter_y2 = min(ay2, by2);
  let inter_x2 = min(ax2, bx2);
  let inter = max(0.0, inter_y2 - inter_y1) * max(0.0, inter_x2 - inter_x1);
  let area_a = max(0.0, ay2 - ay1) * max(0.0, ax2 - ax1);
  let area_b = max(0.0, by2 - by1) * max(0.0, bx2 - bx1);
  let denom = area_a + area_b - inter;
  if (denom <= 0.0) { return 0.0; }
  return inter / denom;
}

var<workgroup> windowCorners: array<vec4<f32>, WG>;
var<workgroup> admissible: array<u32, WG>;
var<workgroup> slices: array<u32, WG * WINDOW_WORDS>;
var<workgroup> wgCount: u32;

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
  let tid = lid.x;
  let group = wid.x;
  let batch = group / params.classes;
  let base = group * SORT_N;
  let selBase = group * MAX_KEEP;
  let cap = min(max_output_boxes_per_class[0], MAX_KEEP);
  let threshold = iou_threshold[0];
  var kept = 0u;
  for (var window = 0u; window < params.boxesPerBatch && kept < cap; window += WG) {
    let rank = window + tid;
    var open = 0u;
    var corners = vec4<f32>(0.0);
    if (rank < params.boxesPerBatch) {
      let index = sortIdx[base + rank];
      if (index != INVALID) {
        open = 1u;
        corners = box_corners(batch, index);
        for (var k = 0u; k < kept; k++) {
          if (iou_with_box(batch, groupSel[selBase + k], corners) > threshold) { open = 0u; break; }
        }
      }
    }
    admissible[tid] = open;
    windowCorners[tid] = corners;
    workgroupBarrier();
    for (var flat = tid; flat < WG * WINDOW_WORDS; flat += WG) {
      let row = flat / WINDOW_WORDS;
      let word = flat % WINDOW_WORDS;
      var bits = 0u;
      if (admissible[row] != 0u) {
        let rowCorners = windowCorners[row];
        for (var bit = 0u; bit < 32u; bit++) {
          let other = word * 32u + bit;
          if (other > row && admissible[other] != 0u && iou_between_corners(windowCorners[other], rowCorners) > threshold) { bits |= 1u << bit; }
        }
      }
      slices[flat] = bits;
    }
    workgroupBarrier();
    if (tid == 0u) {
      var mask: array<u32, WINDOW_WORDS>;
      var found = 0u;
      for (var row = 0u; row < WG && kept + found < cap; row++) {
        if (admissible[row] == 0u || (mask[row / 32u] & (1u << (row % 32u))) != 0u) { continue; }
        groupSel[selBase + kept + found] = sortIdx[base + window + row];
        found++;
        for (var word = 0u; word < WINDOW_WORDS; word++) { mask[word] |= slices[row * WINDOW_WORDS + word]; }
      }
      wgCount = found;
    }
    kept += workgroupUniformLoad(&wgCount);
    storageBarrier();
    workgroupBarrier();
  }
  if (tid == 0u) { groupCount[group] = kept; }
}

