@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let rowWords = params.boxesPerBatch * MASK_WORDS;
  let total = NUM_GROUPS * rowWords;
  let t = gid.x;
  if (t >= total) { return; }
  let group = t / rowWords;
  let rem = t % rowWords;
  let i = rem / MASK_WORDS;
  let word = rem % MASK_WORDS;
  let base = group * SORT_N;
  let batch = group / params.classes;

  var bits = 0u;
  let idx_i = sortIdx[base + i];
  if (idx_i != INVALID) {
    let corners_i = box_corners(batch, idx_i);
    let iou_threshold_value = iou_threshold[0];
    let j_start = word * 32u;
    for (var b = 0u; b < 32u; b = b + 1u) {
      let j = j_start + b;
      if (j > i && j < params.boxesPerBatch) {
        let idx_j = sortIdx[base + j];
        if (idx_j != INVALID && iou_with_box(batch, idx_j, corners_i) > iou_threshold_value) {
          bits = bits | (1u << b);
        }
      }
    }
  }
  pairMask[(base + i) * MASK_WORDS + word] = bits;
