{% else %}
const MAX_KEEP: u32 = {{ maxKeepSpec }}u;

const WINDOW_WORDS: u32 = WG / 32u;

var<workgroup> running: array<atomic<u32>, MASK_WORDS>;
var<workgroup> admissible: array<u32, WG>;
var<workgroup> windowSlices: array<u32, WG * WINDOW_WORDS>;
var<workgroup> picks: array<u32, WG>;
var<workgroup> wgPickCount: u32;

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
  let tid = lid.x;
  let group = wid.x;
  let base = group * SORT_N;
  let selBase = group * MAX_KEEP;
  let max_per_class = min(max_output_boxes_per_class[0], MAX_KEEP);

  for (var w = tid; w < MASK_WORDS; w = w + WG) {
    atomicStore(&running[w], 0u);
  }

  // Replay greedy selection one WG-rank window at a time. Lanes pre-test their
  // rank against the running words (stable between windows), one lane resolves
  // the window serially through the pair-mask window slice -- the only place
  // rank order matters -- and the kept rows fold into the running words in a
  // single barrier-free pass with atomic updates shared across lanes.
  var kept = 0u;
  var window_base = 0u;
