    if (kept >= max_per_class || window_base >= params.boxesPerBatch) { break; }
    workgroupBarrier();
    let r = window_base + tid;
    var open = 0u;
    if (r < params.boxesPerBatch) {
      let idx_r = sortIdx[base + r];
