        open = 1u;
      }
    }
    admissible[tid] = open;
    // Stage every window rank's pair-mask window slice cooperatively, so the
    // serial resolution below reads workgroup memory instead of chasing
    // dependent global loads.
    let sliceBase = (base + window_base) * MASK_WORDS + window_base / 32u;
    for (var i = tid; i < WG * WINDOW_WORDS; i = i + WG) {
      let t = i / WINDOW_WORDS;
      let w = i % WINDOW_WORDS;
      var words = 0u;
      if (window_base + t < params.boxesPerBatch) {
        words = pairMask[sliceBase + t * MASK_WORDS + w];
      }
      windowSlices[t * WINDOW_WORDS + w] = words;
    }
    workgroupBarrier();

    if (tid == 0u) {
      // Serial window resolution: a window rank is kept iff it survives the
      // running mask (admissible) and no earlier kept rank of this same
      // window suppresses it, read straight from its pair-mask row's slice.
      var window_mask: array<u32, WINDOW_WORDS>;
      for (var w = 0u; w < WINDOW_WORDS; w = w + 1u) { window_mask[w] = 0u; }
      var found = 0u;
      for (var t = 0u; t < WG && kept + found < max_per_class; t = t + 1u) {
        if (admissible[t] == 0u) { continue; }
        if ((window_mask[t / 32u] & (1u << (t % 32u))) != 0u) { continue; }
        let pick = window_base + t;
        picks[found] = pick;
        groupSel[selBase + kept + found] = sortIdx[base + pick];
        found = found + 1u;
        for (var w = 0u; w < WINDOW_WORDS; w = w + 1u) {
          window_mask[w] = window_mask[w] | windowSlices[t * WINDOW_WORDS + w];
