    kept = kept + found;
    // No later rank can affect an already complete selection.
    if (kept >= max_per_class || window_base + WG >= params.boxesPerBatch) { break; }

    // Only future windows read the running mask. Fold each kept row into
    // those words over a flat (row, word) grid; atomicOr combines concurrent
    // same-word updates. The completed window needs no further mask writes.
    let first_word = (window_base + WG) / 32u;
    let future_words = MASK_WORDS - first_word;
    for (var i = tid; i < found * future_words; i = i + WG) {
      let k = i / future_words;
      let w = first_word + i % future_words;
      atomicOr(&running[w], pairMask[(base + picks[k]) * MASK_WORDS + w]);
    }
    window_base = window_base + WG;
  }

