webgpu-kernels/ai.onnx.NonMaxSuppression.nms-groups-compact.wgsl.jinja:
// Pass 2 of group-parallel NonMaxSuppression. One workgroup walks per-group
// selections in (batch, class)-major order and compacts them into the final
// [num_selected, 3] tensor. The running offset is the sum of prior group counts;
// the destination's data-dependent first dimension is supplied as output
// metadata. Selections within a group are already in score-descending greedy
// order. Defensive bounds and
// initialization keep an invalid allocation from producing out-of-bounds writes.
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;
const MAX_KEEP: u32 = {{ maxKeepSpec }}u;

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(local_invocation_id) lid: vec3<u32>) {
  let tid = lid.x;
  let numGroups = params.batches * params.classes;

  // Every lane walks the same uniform group-count prefix, so the running offset
  // needs no shared state while each group's rows copy in workgroup-wide strides.
  var total = 0u;
  for (var group = 0u; group < numGroups; group = group + 1u) {
    let batch = group / params.classes;
    let class_id = group % params.classes;
    let selBase = group * MAX_KEEP;
    let n = groupCount[group];
    for (var k = tid; k < n; k = k + WG) {
      if (total + k < params.capacity) {
        let box = groupSel[selBase + k];
        let row = (total + k) * 3u;
        selected_indices[row] = batch;
        selected_indices[row + 1u] = class_id;
        selected_indices[row + 2u] = box;
      }
    }
    total = total + n;
  }

  // Initialize any defensive tail rows to (0,0,0).
  let written = min(total, params.capacity);
  for (var row = written + tid; row < params.capacity; row = row + WG) {
    let base = row * 3u;
    selected_indices[base] = 0u;
    selected_indices[base + 1u] = 0u;
    selected_indices[base + 2u] = 0u;
  }
}

