    let j = c * WG + tid;
    var v = 0u;
    if (j < params.numBlocks) {
      v = blockSums[j];
    }
    workgroupBarrier();
    wgScan[tid] = v;
    for (var step = 1u; step < WG; step = step << 1u) {
      workgroupBarrier();
      var prev = 0u;
      if (tid >= step) {
        prev = wgScan[tid - step];
      }
      workgroupBarrier();
      wgScan[tid] = wgScan[tid] + prev;
