{{ env.wgsl.resourceDeclarations }}

// Each output is evaluated independently as start + i*delta rather than by
// accumulating deltas, preserving the same result across vector widths.
{% macro value(i) %}
{% if isI32 %}start[0] + i32({{ i }}) * delta[0]{% elif isF16 %}f16(f32(start[0]) + f32({{ i }}) * f32(delta[0])){% else %}start[0] + f32({{ i }}) * delta[0]{% endif %}
{% endmacro %}
@compute @workgroup_size({{ tunables.WORKGROUP_SIZE }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  // Generate four adjacent values per invocation while retaining scalar
  // storage for arbitrary output lengths.
  let q = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ tunables.WORKGROUP_SIZE }}u;
  let base = q * 4u;
{% if vec4 %}
  // A whole number of quads lets each invocation write one vec4 without a tail.
  if (q >= params.countV4) {
    return;
  }
  output[q] = vec4<{{ scalar }}>(
    {{ value('base') }},
    {{ value('(base + 1u)') }},
    {{ value('(base + 2u)') }},
    {{ value('(base + 3u)') }});
{% else %}
  if (base >= params.count) {
    return;
  }
  let end = min(base + 4u, params.count);
  for (var i = base; i < end; i = i + 1u) {
    output[i] = {{ value('i') }};
  }
{% endif %}
}

