  // Reserve two significands plus carry bits above FTZ, and a factor of two
  // below overflow for products, division and the expansion midpoint product.
  if (((a_bits | b_bits | y_bits) & 0x80000000u) != 0u ||
      min(ea, eb) == 0u || max(ea, eb) >= 255u ||
      ea + eb < 180u || ea + eb > 347u ||
      ey < 53u || ey > 242u || ea + eb > ey + 220u) {
    return quant_round_binary64(acc, a_s, b_s, y_s);
  }
  let scale = fma(a_s, b_s, 0.0);
  let product = fma(f32(acc), scale, 0.0);
  let estimate = product / y_s;
  if (estimate <= -1024.0) { return -1024; }
  if (estimate >= 1024.0) { return 1024; }
  let nearest = round(estimate);
  // 32 binary32 unit roundoffs reserve room for the i32 conversion, two
  // products, quotient, and distance arithmetic, plus binary64 rounding.
  let margin = max(1.0, abs(estimate)) * 0x1p-19;
  if (abs(estimate - nearest) < 0.5 - margin) { return i32(nearest); }
{% if device.adapterInfo.vendor != "apple" %}
