{% endif %}

  for (var r = lid; r < REDUCED; r = r + WG) {
{% set at = "x[input_offset(i, r)]" %}
{% if castF32 %}
{% set at = "f32(" ~ at ~ ")" %}
{% endif %}
{% if op == "l1" %}
