webgpu-kernels/ai.onnx.QuantizeLinear.quant-linear-blocked-axis.wgsl.jinja:
// Blocked-axis scale and zero-point indexing for linear quantization.
{% set operation = op if op is defined else "quantize" %}
{% set vectorized = vectorizedSpec if vectorizedSpec is defined else false %}
{% set lastAxisVectorized = lastAxisVectorized if lastAxisVectorized is defined else false %}
{% set blockVectors = blockVectors | default(1) %}
{% macro flat_index_2d(workgroupSize, name="i", bound="params.count", guardInline=false) %}
{% set wgTerm = workgroupSize ~ "u" if workgroupSize is number else workgroupSize %}
  // 2D-folded flat index: gid.y carries the high bits past the dispatch's
  // per-axis workgroup fold width.
  let {{ name }} = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ wgTerm }};
  if ({{ name }} >= {{ bound }}) { return; }{% endmacro %}
{{ env.wgsl.resourceDeclarations }}
{% if operation == "dequantize" %}

fn read_x(index: u32) -> i32 {
  return x[index];
}

fn read_zero({% if hasZero %}index: u32{% endif %}) -> i32 {
{% if hasZero %}
  return x_zero_point[index];
{% else %}
  return 0;
{% endif %}
}
{% elif not vectorized and not lastAxisVectorized %}

fn read_zero({% if hasZero %}index: u32{% endif %}) -> i32 {
{% if hasZero %}
{% if yUnsigned %}
  return i32(y_zero_point[index]);
{% else %}
  return y_zero_point[index];
{% endif %}
{% else %}
  return 0;
{% endif %}
}

fn write_quantized(index: u32, value: i32) {
{% if yUnsigned %}
  y[index] = u32(value);
{% else %}
  y[index] = value;
{% endif %}
}
{% endif %}
{% if not lastAxisVectorized %}

fn scale_index(index: u32) -> u32 {
  let inner_index = index % params.inner;
  let axis_index = (index / params.inner) % params.axisDim;
  let outer_index = index / (params.axisDim * params.inner);
  return (outer_index * params.scaleAxisDim + axis_index / params.blockSize) * params.inner + inner_index;
}
{% endif %}
{% if operation == "quantize" %}

// Exact ONNX QuantizeLinear round-to-nearest-even, with identical handling of
// infinities, saturation, and halfway values across every kernel route.
{% if divisionF16 %}
fn round_quotient_half_to_even(quotient: f32) -> i32 {
  let v = clamp(quotient, -2.0e9, 2.0e9);
  let fl = floor(v);
  let hi = fl + 1.0;
  let fraction = v - fl;
  if (fraction < 0.5) { return i32(fl); }
  if (fraction > 0.5) { return i32(hi); }
