  let magnitude = select(u32(acc), 0u - u32(acc), acc < 0);
  var rounded = 0u;
  if (exponent >= 0) {
    if (exponent >= 10) { return select(1024, -1024, acc < 0); }
    rounded = min(magnitude, 1024u >> u32(exponent)) << u32(exponent);
  } else {
    let shift = u32(-exponent);
    if (shift >= 32u) { return 0; }
    let whole = magnitude >> shift;
    let remainder = magnitude & ((1u << shift) - 1u);
    let half = 1u << (shift - 1u);
    rounded = min(1024u, whole + u32(remainder > half || (remainder == half && (whole & 1u) != 0u)));
  }
  return select(i32(rounded), -i32(rounded), acc < 0);
