  // Recover the conversion residual without an out-of-range i32(acc_f)
  // conversion when INT_MAX rounds up to 2^31.
  let acc_tail = fma(-1.0, acc_f - f32(acc & -256), f32(acc & 255));
  // Equal b/y scales cancel exactly. Bypass their product and division so a
  // rounded intermediate cannot move a near-half value onto the tie.
  if (bitcast<u32>(b_s) == bitcast<u32>(y_s)) {
    let direct_hi = fma(acc_f, a_s, 0.0);
    let direct_lo = fma(acc_tail, a_s, fma(acc_f, a_s, -direct_hi));
