  return round_expansion_ratio(product_hi, product_tail, y_s, ab_hi, dyadic_candidate, acc, a_s, b_s, y_s);
}

// A conservative binary32 error filter accepts only a result safely inside one
// integer rounding bin. Ambiguous boundaries keep the full expansion/binary64
// path; this is an exact-result shortcut, not an approximate quantization mode.
fn round_requantized(acc: i32, a_s: f32, b_s: f32, y_s: f32) -> i32 {
  if (acc == 0) { return 0; }
  let a_bits = bitcast<u32>(a_s);
  let b_bits = bitcast<u32>(b_s);
  let y_bits = bitcast<u32>(y_s);
  let ea = (a_bits >> 23u) & 255u;
  let eb = (b_bits >> 23u) & 255u;
  let ey = (y_bits >> 23u) & 255u;
  // Certify the range before arithmetic: overflow need not produce infinity.
  // Any nonzero i32 converts to a float with biased exponent <=158. These
  // scale-only bounds cover every accumulator and can be shared across lanes.
  // Reserve two significands plus carry bits above FTZ, and a factor of two
  // below overflow for products, division and the expansion midpoint product.
  if (((a_bits | b_bits | y_bits) & 0x80000000u) != 0u ||
      min(ea, eb) == 0u || max(ea, eb) >= 255u ||
      ea + eb < 180u || ea + eb > 347u ||
      ey < 53u || ey > 242u || ea + eb > ey + 220u) {
    return quant_round_binary64(acc, a_s, b_s, y_s);
  }
  let scale = fma(a_s, b_s, 0.0);
  let product = fma(f32(acc), scale, 0.0);
  let estimate = product / y_s;
  if (estimate <= -1024.0) { return -1024; }
  if (estimate >= 1024.0) { return 1024; }
  let nearest = round(estimate);
  // 32 binary32 unit roundoffs reserve room for the i32 conversion, two
  // products, quotient, and distance arithmetic, plus binary64 rounding.
  let margin = max(1.0, abs(estimate)) * 0x1p-19;
  if (abs(estimate - nearest) < 0.5 - margin) { return i32(nearest); }
{% if device.adapterInfo.vendor != "apple" %}
  // A rounded half-integer estimate can hide which side the exact f32-scale
  // ratio lies on. Resolve that one-ulp neighborhood conservatively outside
  // the compact fast path; exact power-of-two ratios already have a cheap
  // and correct path in round_requantized_precise.
  if (abs(abs(estimate - nearest) - 0.5) <= max(1.0, abs(estimate)) * 0x1p-24) {
    let dyadic_scales = ((a_bits | b_bits | y_bits) & 0x807fffffu) == 0u &&
      min(a_bits, min(b_bits, y_bits)) != 0u &&
      max(a_bits, max(b_bits, y_bits)) < 0x7f800000u;
    if (!dyadic_scales) { return quant_round_binary64(acc, a_s, b_s, y_s); }
  }
{% endif %}
  return round_requantized_precise(acc, a_s, b_s, y_s);
}

