// A power-of-two division and an exactly represented <=48-bit product need
// no binary64 boundary resolver. This includes ordinary dyadic quantization.
fn quant_exact_dyadic_product(acc: i32, scale: f32) -> bool {
  let magnitude = select(u32(acc), 0u - u32(acc), acc < 0);
  let significand = quant_float_significand(bitcast<u32>(scale));
  let integer_bits = 32u - countLeadingZeros(magnitude) - countTrailingZeros(magnitude);
  let scale_bits = 32u - countLeadingZeros(significand) - countTrailingZeros(significand);
