    if (!dyadic_candidate || !quant_exact_dyadic_product(acc, dyadic_scale)) { return quant_round_binary64(acc, a_s, b_s, y_s); }
  }
  if (midpoint_delta < 0.0) {
    return i32(lo);
  }
  if (midpoint_delta > 0.0) {
    return i32(hi);
  }
  let half_lo = floor(lo * 0.5);
  let lo_is_even = lo - half_lo * 2.0 == 0.0;
  return i32(select(hi, lo, lo_is_even));
