  // rounded intermediate cannot move a near-half value onto the tie.
  if (bitcast<u32>(b_s) == bitcast<u32>(y_s)) {
    let direct_hi = fma(acc_f, a_s, 0.0);
    let direct_lo = fma(acc_tail, a_s, fma(acc_f, a_s, -direct_hi));
