  // ratio lies on. Resolve that one-ulp neighborhood conservatively outside
  // the compact fast path; exact power-of-two ratios already have a cheap
  // and correct path in round_requantized_precise.
  if (abs(abs(estimate - nearest) - 0.5) <= max(1.0, abs(estimate)) * 0x1p-24) {
    let dyadic_scales = ((a_bits | b_bits | y_bits) & 0x807fffffu) == 0u &&
      min(a_bits, min(b_bits, y_bits)) != 0u &&
      max(a_bits, max(b_bits, y_bits)) < 0x7f800000u;
    if (!dyadic_scales) { return quant_round_binary64(acc, a_s, b_s, y_s); }
  }
{% endif %}
  return round_requantized_precise(acc, a_s, b_s, y_s);
}
{% endif %}

