    var nan_value_lanes = partial[col_lane];
    for (var lane = 1u; lane < ROW_LANES; lane = lane + 1u) {
      nan_value_lanes = nan_value_lanes + partial[lane * TILE_COLS + col_lane];
    }
    partial[col_lane] = nan_value_lanes;
