{% if op == "max" %}
    var total = reduction_identity();
{% elif op == "min" %}
    var total = reduction_identity();
{% elif op == "prod" %}
    var total = 1.0;
{% else %}
    var total = 0.0;
{% endif %}
    for (var seg = 0u; seg < SPLIT; seg = seg + 1u) {
      let p = partials[seg * params.cols + col];
{% if op == "max" or op == "min" %}
      total = {{ op }}(total, p);
{% elif op == "prod" %}
      total = total * p;
{% else %}
      total = total + p;
{% endif %}
    }
{% if op == "l2" %}
    y[col] = {{ yv }}sqrt(total){{ vy }};
{% elif op == "logsum" %}
    y[col] = {{ yv }}log(total){{ vy }};
{% elif op == "mean" %}
    y[col] = {{ yv }}total / f32(params.rows){{ vy }};
