{% if op == "logsumexp" %}
  var local_max = F32_MIN;
  var local_nan_count = 0.0;
  var local_nan_value = 0.0;
  for (var row = r0; row < r1; row = row + 1u) {
    let value = {{ xa }}x[row * params.cols + col]{{ ax }};
    if (is_nan_f32(value)) {
