fn main(@builtin(workgroup_id) wg: vec3<u32>,
        @builtin(local_invocation_id) lid: vec3<u32>,
        @builtin(subgroup_invocation_id) sgLid: u32,
        @builtin(subgroup_id) sgId: u32,
        @builtin(num_subgroups) numSg: u32) {
