{% elif op == "min" %}
    acc4 = min(acc4, v);
{% elif op == "prod" %}
    acc4 = acc4 * v;
{% elif op == "l1" %}
    acc4 = acc4 + abs(v);
{% elif op == "l2" or op == "sumsquare" %}
    acc4 = acc4 + v * v;
{% else %}
    acc4 = acc4 + v;
{% endif %}
  }
{% if op == "max" %}
  let acc = max(max(acc4.x, acc4.y), max(acc4.z, acc4.w));
{% elif op == "min" %}
  let acc = min(min(acc4.x, acc4.y), min(acc4.z, acc4.w));
{% elif op == "prod" %}
