{% elif op == "min" %}
    acc = min(acc, v);
{% elif op == "prod" %}
    acc = acc * v;
{% elif op == "l1" %}
    acc = acc + abs(v);
{% elif op == "l2" or op == "sumsquare" %}
    acc = acc + v * v;
