{{ env.wgsl.resourceDeclarations }}

const RANK: u32 = {{ rank }}u;
const BATCH_AXIS: u32 = {{ batchAxis }}u;
const TIME_AXIS: u32 = {{ timeAxis }}u;
const SHAPE: array<u32, {{ rank }}> = array<u32, {{ rank }}>({% for d in shape %}{{ d }}u{% if not loop.last %}, {% endif %}{% endfor %});

fn stride(axis: u32) -> u32 {
  var value = 1u;
  var i = axis + 1u;
  loop {
    if (i >= RANK) { break; }
    value = value * SHAPE[i];
    i = i + 1u;
  }
  return value;
}

fn sequence_length(batch: u32) -> u32 {
  return min(sequence_lens[batch], SHAPE[TIME_AXIS]);
}

@compute @workgroup_size({{ tunables.WORKGROUP_SIZE }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
{{ flat_index_2d(tunables.WORKGROUP_SIZE, "index") }}

  var coords: array<u32, {{ rank }}>;
  var rem = index;
  for (var axis = 0u; axis < RANK; axis = axis + 1u) {
    let s = stride(axis);
    coords[axis] = rem / s;
    rem = rem % s;
  }

  let len = sequence_length(coords[BATCH_AXIS]);
  if (coords[TIME_AXIS] < len) {
    coords[TIME_AXIS] = len - 1u - coords[TIME_AXIS];
  }

  var src = 0u;
  for (var axis = 0u; axis < RANK; axis = axis + 1u) {
    src = src + coords[axis] * stride(axis);
  }
  y[index] = input[src];
}

