webgpu-kernels/ai.onnx.Resize.resize-cubic.wgsl.jinja:
// Generic NCHW Resize with separable Keys cubic interpolation. Each output
// coordinate maps to input space and samples the four taps around floor(src)
// at offsets {-1, 0, 1, 2}. The rows-then-columns pass uses 16 taps in 2D.
// Sample coordinates clamp to [0, dim - 1] when exclude_outside is disabled.
// The coefficient `a` is cubic_coeff_a (default -0.75). The selected coordinate
// mode determines how each output coordinate maps into input space.
{% set EXCL = excludeOutside is defined and excludeOutside == 1 %}
{% macro flat_index_2d(workgroupSize, name="i", bound="params.count", guardInline=false) %}
{% set wgTerm = workgroupSize ~ "u" if workgroupSize is number else workgroupSize %}
  // 2D-folded flat index: gid.y carries the high bits past the dispatch's
  // per-axis workgroup fold width.
  let {{ name }} = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ wgTerm }};
  if ({{ name }} >= {{ bound }}) { return; }{% endmacro %}
{{ env.wgsl.resourceDeclarations }}
{% set wg = workgroupSize %}

fn source_coord(out_coord: u32, in_size: u32, out_size: u32{% if coordinateMode != "align_corners" %}, explicit_scale: f32{% endif %}) -> f32 {
{% if coordinateMode != "align_corners" %}
  let inferred_scale = f32(out_size) / f32(in_size);
  let scale = select(inferred_scale, explicit_scale, explicit_scale > 0.0);
{% endif %}
  {% if coordinateMode == "align_corners" %}
  if (out_size == 1u) { return 0.0; }
  return f32(out_coord) * f32(in_size - 1u) / f32(out_size - 1u);
  {% elif coordinateMode == "asymmetric" %}
  return f32(out_coord) / scale;
  {% elif coordinateMode == "pytorch_half_pixel" %}
  return select(0.0, (f32(out_coord) + 0.5) / scale - 0.5, out_size > 1u);
  {% elif coordinateMode == "half_pixel_symmetric" %}
  let output_width = f32(in_size) * scale;
  let adjustment = f32(out_size) / output_width;
  let center = f32(in_size) * 0.5;
  let offset = center * (1.0 - adjustment);
  return offset + (f32(out_coord) + 0.5) / scale - 0.5;
  {% else %}
  return (f32(out_coord) + 0.5) / scale - 0.5;
  {% endif %}
}

// Keys cubic convolution kernel with coefficient params.coeffA.
fn cubic_weight(s_in: f32) -> f32 {
  let a = params.coeffA;
  let s = abs(s_in);
  let s2 = s * s;
  let s3 = s2 * s;
  if (s <= 1.0) {
    return (a + 2.0) * s3 - (a + 3.0) * s2 + 1.0;
  }
  if (s < 2.0) {
    return a * s3 - 5.0 * a * s2 + 8.0 * a * s - 4.0 * a;
  }
  return 0.0;
}

fn input_at(base: u32, h: i32, w: i32) -> f32 {
  let hh = u32(clamp(h, 0, i32(params.inH) - 1));
  let ww = u32(clamp(w, 0, i32(params.inW) - 1));
  return f32(x[base + hh * params.inW + ww]);
}

// Cubic interpolation along the W axis for a fixed input row `h`, at source
// column `sx`. Four taps at floor(sx)-1 .. floor(sx)+2.
fn cubic_x(base: u32, h: i32, sx: f32) -> f32 {
  let x0 = i32(floor(sx));
  let t = sx - f32(x0);
  var w0 = cubic_weight(1.0 + t);
  var w1 = cubic_weight(t);
  var w2 = cubic_weight(1.0 - t);
  var w3 = cubic_weight(2.0 - t);
{% if EXCL %}
  // exclude_outside: zero taps outside the input range, renormalize the rest.
  let wlim = i32(params.inW);
  if (x0 - 1 < 0 || x0 - 1 >= wlim) { w0 = 0.0; }
  if (x0 < 0 || x0 >= wlim) { w1 = 0.0; }
  if (x0 + 1 < 0 || x0 + 1 >= wlim) { w2 = 0.0; }
  if (x0 + 2 < 0 || x0 + 2 >= wlim) { w3 = 0.0; }
  let wsum = w0 + w1 + w2 + w3;
  w0 = w0 / wsum;
  w1 = w1 / wsum;
  w2 = w2 / wsum;
  w3 = w3 / wsum;
{% endif %}
  return w0 * input_at(base, h, x0 - 1)
       + w1 * input_at(base, h, x0)
       + w2 * input_at(base, h, x0 + 1)
       + w3 * input_at(base, h, x0 + 2);
}

@compute @workgroup_size({{ wg }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
{{ flat_index_2d(wg, guardInline=true) }}
  let ow = i % params.outW;
  let oh = (i / params.outW) % params.outH;
  let c = (i / (params.outW * params.outH)) % params.C;
  let n = i / (params.outW * params.outH * params.C);
  let base = (n * params.C + c) * params.inH * params.inW;
  let sy = source_coord(oh, params.inH, params.outH{% if coordinateMode != "align_corners" %}, params.scaleH{% endif %});
  let sx = source_coord(ow, params.inW, params.outW{% if coordinateMode != "align_corners" %}, params.scaleW{% endif %});
  // Separable: cubic along W for each of the 4 source rows, then cubic along H.
  let y0 = i32(floor(sy));
  let t = sy - f32(y0);
  var wy0 = cubic_weight(1.0 + t);
  var wy1 = cubic_weight(t);
  var wy2 = cubic_weight(1.0 - t);
  var wy3 = cubic_weight(2.0 - t);
{% if EXCL %}
  let hlim = i32(params.inH);
  if (y0 - 1 < 0 || y0 - 1 >= hlim) { wy0 = 0.0; }
  if (y0 < 0 || y0 >= hlim) { wy1 = 0.0; }
  if (y0 + 1 < 0 || y0 + 1 >= hlim) { wy2 = 0.0; }
  if (y0 + 2 < 0 || y0 + 2 >= hlim) { wy3 = 0.0; }
  let wysum = wy0 + wy1 + wy2 + wy3;
  wy0 = wy0 / wysum;
  wy1 = wy1 / wysum;
  wy2 = wy2 / wysum;
  wy3 = wy3 / wysum;
{% endif %}
  let result = wy0 * cubic_x(base, y0 - 1, sx)
             + wy1 * cubic_x(base, y0, sx)
             + wy2 * cubic_x(base, y0 + 1, sx)
             + wy3 * cubic_x(base, y0 + 2, sx);
  y[i] = {{ scalar }}(result);
}

webgpu-kernels/ai.onnx.Resize.resize-nearest-integer-scale.wgsl.jinja:
// NCHW nearest-neighbor resize with compile-time integer upscale factors. The
// source index is exactly out_coord / scale using u32 division, with no floating
// point coordinate calculation.
//
// This is valid for asymmetric + floor because floor(ow / s) is u32 division.
// It is also valid for half_pixel with either round-prefer rule: writing
// ow = q*s + r gives an offset whose magnitude is strictly below one half, so
// ties cannot occur and every nearest rounding rule returns q. Downsampling and
// other coordinate-mode combinations require the generic coordinate transform.
{{ env.wgsl.resourceDeclarations }}
{% set wg = workgroupSize if workgroupSize is defined else tunables.WORKGROUP_SIZE %}
{% set inH = xShape[2] %}
{% set inW = xShape[3] %}
{% set outH = yShape[2] %}
{% set outW = yShape[3] %}
{% set scaleW = ((outW / inW) | int) %}
{% set rows = yShape[0] * yShape[1] * outH %}
const WG: u32 = {{ wg }}u;
const IN_W: u32 = {{ inW }}u;
const IN_HW: u32 = {{ inH * inW }}u;
const OUT_H: u32 = {{ outH }}u;
const SCALE_H: u32 = {{ ((outH / inH) | int) }}u;
{% if not vec4 or scaleW == 3 %}
const SCALE_W: u32 = {{ scaleW }}u;
{% endif %}
{% if vec4 %}
const OUT_W_VECS: u32 = {{ ((outW / 4) | int) }}u;
const COUNT: u32 = {{ (((rows * outW) / 4) | int) }}u;
{% else %}
const OUT_W: u32 = {{ outW }}u;
const COUNT: u32 = {{ rows * outW }}u;
{% endif %}

@compute @workgroup_size({{ wg }})
fn main(
  @builtin(global_invocation_id) gid: vec3<u32>,
  @builtin(num_workgroups) nwg: vec3<u32>
) {
  let stride = nwg.x * WG;
{% if vec4 %}
  for (var v = gid.x; v < COUNT; v += stride) {
    let ow0 = (v % OUT_W_VECS) * 4u;
    let t = v / OUT_W_VECS;
    let oh = t % OUT_H;
    let nc = t / OUT_H;
    let rowBase = nc * IN_HW + (oh / SCALE_H) * IN_W;
{% if scaleW == 4 %}
    y[v] = {{ vectorScalar }}(x[rowBase + ow0 / 4u]);
{% elif scaleW == 2 %}
    let a = x[rowBase + ow0 / 2u];
    let b = x[rowBase + ow0 / 2u + 1u];
    y[v] = {{ vectorScalar }}(a, a, b, b);
{% else %}
    y[v] = {{ vectorScalar }}(
      x[rowBase + ow0 / SCALE_W],
      x[rowBase + (ow0 + 1u) / SCALE_W],
      x[rowBase + (ow0 + 2u) / SCALE_W],
      x[rowBase + (ow0 + 3u) / SCALE_W]
    );
{% endif %}
  }
{% else %}
  for (var i = gid.x; i < COUNT; i += stride) {
    let ow = i % OUT_W;
    let t = i / OUT_W;
    let oh = t % OUT_H;
    let nc = t / OUT_H;
    y[i] = x[nc * IN_HW + (oh / SCALE_H) * IN_W + ow / SCALE_W];
  }
{% endif %}
}

