{{ env.wgsl.resourceDeclarations }}

// Exact-2x f16 bilinear resize with two adjacent vec4 outputs per invocation.
// Neighboring output quads overlap by two source columns, so an x8 tile needs
// only six horizontal taps per source row instead of two independent x4
// stencils' eight. Coordinate/parity work and thread count are also halved.
const WG: u32 = {{ workgroupSize }}u;
const IN_H: u32 = {{ xShape[2] }}u;
const IN_W: u32 = {{ xShape[3] }}u;
const IN_HW: u32 = {{ xShape[2] * xShape[3] }}u;
const OUT_H: u32 = {{ yShape[2] }}u;
const OUT_W: u32 = {{ yShape[3] }}u;
const COUNT: u32 = {{ yShape[0] * yShape[1] * yShape[2] * yShape[3] }}u;

fn input_at(base: u32, h: i32, w: i32) -> f32 {
  let hh = u32(clamp(h, 0, i32(IN_H) - 1));
  let ww = u32(clamp(w, 0, i32(IN_W) - 1));
  return f32(x[base + hh * IN_W + ww]);
}

@compute @workgroup_size(WG, 1, 1)
fn main(
  @builtin(global_invocation_id) gid: vec3<u32>,
  @builtin(num_workgroups) workgroup_count: vec3<u32>
) {
  let stride = workgroup_count.x * WG;
  let groups_per_row = OUT_W / 8u;
  let group_count = COUNT / 8u;
  for (var group = gid.x; group < group_count; group = group + stride) {
    let group_in_row = group % groups_per_row;
    let row = group / groups_per_row;
    let oh = row % OUT_H;
    let nc = row / OUT_H;
    let base = nc * IN_HW;
    let qx = i32(group_in_row * 4u);
{% if coordinateMode == "asymmetric" %}
    let y0 = i32(oh / 2u);
    let wy = select(0.0, 0.5, (oh & 1u) == 1u);
    let a0 = input_at(base, y0, qx + 0);
    let b0 = input_at(base, y0, qx + 1);
    let c0 = input_at(base, y0, qx + 2);
    let d0 = input_at(base, y0, qx + 3);
    let e0 = input_at(base, y0, qx + 4);
    let y1 = y0 + 1;
    let a1 = input_at(base, y1, qx + 0);
    let b1 = input_at(base, y1, qx + 1);
    let c1 = input_at(base, y1, qx + 2);
    let d1 = input_at(base, y1, qx + 3);
    let e1 = input_at(base, y1, qx + 4);
    let top0 = vec4<f32>(a0, 0.5 * a0 + 0.5 * b0, b0, 0.5 * b0 + 0.5 * c0);
    let top1 = vec4<f32>(c0, 0.5 * c0 + 0.5 * d0, d0, 0.5 * d0 + 0.5 * e0);
    let bottom0 = vec4<f32>(a1, 0.5 * a1 + 0.5 * b1, b1, 0.5 * b1 + 0.5 * c1);
    let bottom1 = vec4<f32>(c1, 0.5 * c1 + 0.5 * d1, d1, 0.5 * d1 + 0.5 * e1);
{% else %}
    let y0 = i32(oh / 2u) - 1 + i32(oh & 1u);
    let wy = select(0.75, 0.25, (oh & 1u) == 1u);
    let a0 = input_at(base, y0, qx - 1);
    let b0 = input_at(base, y0, qx + 0);
    let c0 = input_at(base, y0, qx + 1);
    let d0 = input_at(base, y0, qx + 2);
    let e0 = input_at(base, y0, qx + 3);
    let f0 = input_at(base, y0, qx + 4);
    let y1 = y0 + 1;
    let a1 = input_at(base, y1, qx - 1);
    let b1 = input_at(base, y1, qx + 0);
    let c1 = input_at(base, y1, qx + 1);
    let d1 = input_at(base, y1, qx + 2);
    let e1 = input_at(base, y1, qx + 3);
    let f1 = input_at(base, y1, qx + 4);
    let top0 = vec4<f32>(0.25 * a0 + 0.75 * b0, 0.75 * b0 + 0.25 * c0, 0.25 * b0 + 0.75 * c0, 0.75 * c0 + 0.25 * d0);
    let top1 = vec4<f32>(0.25 * c0 + 0.75 * d0, 0.75 * d0 + 0.25 * e0, 0.25 * d0 + 0.75 * e0, 0.75 * e0 + 0.25 * f0);
    let bottom0 = vec4<f32>(0.25 * a1 + 0.75 * b1, 0.75 * b1 + 0.25 * c1, 0.25 * b1 + 0.75 * c1, 0.75 * c1 + 0.25 * d1);
    let bottom1 = vec4<f32>(0.25 * c1 + 0.75 * d1, 0.75 * d1 + 0.25 * e1, 0.25 * d1 + 0.75 * e1, 0.75 * e1 + 0.25 * f1);
{% endif %}
    let output0 = vec4<f32>(1.0 - wy) * top0 + vec4<f32>(wy) * bottom0;
    let output1 = vec4<f32>(1.0 - wy) * top1 + vec4<f32>(wy) * bottom1;
    y[group * 2u] = vec4<f16>(output0);
    y[group * 2u + 1u] = vec4<f16>(output1);
  }
}

webgpu-kernels/ai.onnx.Resize.resize-antialias.wgsl.jinja:
// Downsample-aware antialiased Resize. A separable filter runs over each resized
// axis. The filter scale is max(1, downsample ratio), so downsampling widens the
// support and averages a source window. Linear mode uses a triangle/area filter;
// cubic mode uses a Keys kernel at distance/filter-scale. Excluding outside
// samples zeroes out-of-bounds taps before per-window normalization.
//
// An explicit per-axis scale drives both coordinate transformation and filter
// scale. Because out = floor(in*scale), it may differ from the output/input
// shape ratio. The window start is dynamic, while its maximum size is baked.
{{ env.wgsl.resourceDeclarations }}
{% set wg = workgroupSize %}
{% set xs = xShape %}
{% set ys = yShape %}
{% set r = xs | length %}
{% set FILTER = filter if filter is defined else "linear" %}
{% set supmul = 2 if FILTER == "cubic" else 1 %}
{% set resolvedScales = namespace(values = []) %}
{% for a in range(r) %}
{% set axisScale = namespace(value = 0) %}
{% if scales is defined and scales %}
{% if axes is defined and axes %}
{% for j in range(axes | length) %}
{% set scaleAxis = axes[j] if axes[j] >= 0 else axes[j] + r %}
{% if scaleAxis == a %}{% set axisScale.value = scales[j] %}{% endif %}
{% endfor %}
{% else %}
{% set axisScale.value = scales[a] %}
{% endif %}
{% endif %}
{% set resolvedScales.values = resolvedScales.values + [axisScale.value] %}
{% endfor %}
