  // A negative half-pixel coordinate is in [-0.5, 0). Every nearest mode may
  // choose -1 or 0 there, but Resize clamps both to source index zero.
  if (scaled <= shift) {
    return 0;
  }
  return rational_value_nearest_index(scaled - shift, out_size * 2u);
}
{% endif %}
{% if noRoi %}

fn nearest_coord_index(
  out_coord: u32,
  in_size: u32,
  out_size: u32{% if usesExplicitScale %},
  explicit_scale: f32
  {% endif %}
) -> i32 {
  {% if coordinateMode == "align_corners" %}
  if (out_size <= 1u || in_size <= 1u) {
    return 0;
  }
  return rational_nearest_index(out_coord, in_size - 1u, out_size - 1u);
  {% else %}
  {% if coordinateMode == "asymmetric" %}
  if (explicit_scale <= 0.0) {
    return rational_nearest_index(out_coord, in_size, out_size);
  }
  {% elif coordinateMode == "pytorch_half_pixel" %}
  if (out_size <= 1u) {
    return 0;
  }
  if (explicit_scale <= 0.0) {
    return inferred_half_pixel_nearest_index(out_coord, in_size, out_size, true);
  }
  {% elif coordinateMode == "tf_crop_and_resize" %}
  {% else %}
  if (explicit_scale <= 0.0) {
    return inferred_half_pixel_nearest_index(out_coord, in_size, out_size, true);
  }
  {% endif %}
  return nearest_index(source_coord(out_coord, in_size, out_size{% if usesExplicitScale %}, explicit_scale{% endif %}));
  {% endif %}
}
{% endif %}
{% endif %}

fn input_at(base: u32, d: i32, h: i32, w: i32) -> f32 {
  let dd = u32(clamp(d, 0, i32(params.inD) - 1));
  let hh = u32(clamp(h, 0, i32(params.inH) - 1));
  let ww = u32(clamp(w, 0, i32(params.inW) - 1));
  return f32(x[base + (dd * params.inH + hh) * params.inW + ww]);
}

@compute @workgroup_size({{ wg }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
{{ flat_index_2d(wg, guardInline=true) }}
  let ow = i % params.outW;
  let oh = (i / params.outW) % params.outH;
  let od = (i / (params.outW * params.outH)) % params.outD;
  let c = (i / (params.outW * params.outH * params.outD)) % params.C;
  let n = i / (params.outW * params.outH * params.outD * params.C);
  let base = (n * params.C + c) * params.inD * params.inH * params.inW;
{% if modeSpec != "nearest" %}
  let sd = source_coord(od, params.inD, params.outD{% if not alignCorners %}, params.scaleD{% endif %});
  let sy = source_coord(oh, params.inH, params.outH{% if not alignCorners %}, params.scaleH{% endif %});
  let sx = source_coord(ow, params.inW, params.outW{% if not alignCorners %}, params.scaleW{% endif %});
{% endif %}
  {% if modeSpec == "nearest" %}
  let id = nearest_coord_index(od, params.inD, params.outD{% if not alignCorners %}, params.scaleD{% endif %});
  let ih = nearest_coord_index(oh, params.inH, params.outH{% if not alignCorners %}, params.scaleH{% endif %});
  let iw = nearest_coord_index(ow, params.inW, params.outW{% if not alignCorners %}, params.scaleW{% endif %});
  let result = input_at(base, id, ih, iw);
  {% else %}
  let z0 = i32(floor(sd));
  let y0 = i32(floor(sy));
  let x0 = i32(floor(sx));
  let z1 = z0 + 1;
  let y1 = y0 + 1;
  let x1 = x0 + 1;
  let wz = sd - f32(z0);
  let wy = sy - f32(y0);
  let wx = sx - f32(x0);
  let c000 = input_at(base, z0, y0, x0);
  let c001 = input_at(base, z0, y0, x1);
  let c010 = input_at(base, z0, y1, x0);
  let c011 = input_at(base, z0, y1, x1);
  let c100 = input_at(base, z1, y0, x0);
  let c101 = input_at(base, z1, y0, x1);
  let c110 = input_at(base, z1, y1, x0);
  let c111 = input_at(base, z1, y1, x1);
  let front = (1.0 - wy) * ((1.0 - wx) * c000 + wx * c001) + wy * ((1.0 - wx) * c010 + wx * c011);
  let back = (1.0 - wy) * ((1.0 - wx) * c100 + wx * c101) + wy * ((1.0 - wx) * c110 + wx * c111);
  let result = (1.0 - wz) * front + wz * back;
  {% endif %}
  y[i] = {{ scalar }}(result);
}

webgpu-kernels/ai.onnx.Resize.resize-linear-2x-stencil.wgsl.jinja:
// NCHW bilinear 2x upscale on both spatial axes. The
// interpolation weights collapse to fixed per-parity stencils, replacing
// per-element floating-point coordinate divisions with integer parity tests
// and constants.
//
{% if coordinateMode == "asymmetric" %}
// With asymmetric coordinates, src = o / 2: even outputs use fraction 0.0 and
// odd outputs use fraction 0.5.
{% else %}
// With half-pixel coordinates, src = o / 2 - 0.25: even outputs use
// floor q - 1 with fraction 0.75, and odd outputs use floor q with fraction
// 0.25.
{% endif %}
//
// Input coordinates clamp at the edges, including the q - 1 and q + 1 border
// taps. Interpolation weights are constructed in f32 before the output cast.
{{ env.wgsl.resourceDeclarations }}
{% set wg = workgroupSize if workgroupSize is defined else tunables.WORKGROUP_SIZE %}

const WG: u32 = {{ wg }}u;
const IN_H: u32 = {{ xShape[2] }}u;
const IN_W: u32 = {{ xShape[3] }}u;
const IN_HW: u32 = {{ xShape[2] * xShape[3] }}u;
const OUT_H: u32 = {{ yShape[2] }}u;
const OUT_W: u32 = {{ yShape[3] }}u;
const COUNT: u32 = {{ yShape[0] * yShape[1] * yShape[2] * yShape[3] }}u;

fn input_at(base: u32, h: i32, w: i32) -> f32 {
  let hh = u32(clamp(h, 0, i32(IN_H) - 1));
  let ww = u32(clamp(w, 0, i32(IN_W) - 1));
  return f32(x[base + hh * IN_W + ww]);
}

@compute @workgroup_size({{ wg }})
fn main(
  @builtin(global_invocation_id) gid: vec3<u32>,
  @builtin(num_workgroups) nwg: vec3<u32>
) {
  let stride = nwg.x * WG;
{% if vec4 %}
  // Vec4 path: one thread owns 4 contiguous output columns (OUT_W % 4 == 0, so
  // a 4-group never crosses a row). All 4 lanes share the same oh -> same source
  // rows (y0,y1) and the same 4-column source window (qx0-1 .. qx0+2); load that
  // window once, compute the 4 bilinear results with the baked per-lane parity
  // weights, and emit a single vec4 store. Each component uses the same
  // input_at calls, weight split, and f32 operation order.
  let OUT_W4 = OUT_W / 4u;
  let COUNT4 = COUNT / 4u;
  for (var v = gid.x; v < COUNT4; v += stride) {
    let ow4 = v % OUT_W4;
    let tt = v / OUT_W4;
    let oh = tt % OUT_H;
    let nc = tt / OUT_H;
    let base = nc * IN_HW;
    let ow0 = ow4 * 4u;
    let qx0 = i32(ow0 / 2u);
{% if coordinateMode == "asymmetric" %}
    let y0 = i32(oh / 2u);
    let wy = select(0.0, 0.5, (oh & 1u) == 1u);
{% else %}
    let y0 = i32(oh / 2u) - 1 + i32(oh & 1u);
    let wy = select(0.75, 0.25, (oh & 1u) == 1u);
{% endif %}
    let y1 = y0 + 1;
{% if coordinateMode != "asymmetric" %}
    // The q-1 left tap is only weighted by the half-pixel stencils; the
    // asymmetric stencils (weights 0.0/0.5) never read it.
    let a0 = input_at(base, y0, qx0 - 1);
    let a1 = input_at(base, y1, qx0 - 1);
{% endif %}
    let b0 = input_at(base, y0, qx0);
    let c0 = input_at(base, y0, qx0 + 1);
    let d0 = input_at(base, y0, qx0 + 2);
    let b1 = input_at(base, y1, qx0);
    let c1 = input_at(base, y1, qx0 + 1);
    let d1 = input_at(base, y1, qx0 + 2);
{% if coordinateMode == "asymmetric" %}
    // lanes (ow0..ow0+3): wx 0.0,0.5,0.0,0.5 ; (v00,v01) cols (b,c),(b,c),(c,d),(c,d)
    let o0 = (1.0 - wy) * (1.0 * b0 + 0.0 * c0) + wy * (1.0 * b1 + 0.0 * c1);
    let o1 = (1.0 - wy) * (0.5 * b0 + 0.5 * c0) + wy * (0.5 * b1 + 0.5 * c1);
    let o2 = (1.0 - wy) * (1.0 * c0 + 0.0 * d0) + wy * (1.0 * c1 + 0.0 * d1);
    let o3 = (1.0 - wy) * (0.5 * c0 + 0.5 * d0) + wy * (0.5 * c1 + 0.5 * d1);
{% else %}
    // lanes (ow0..ow0+3): wx 0.75,0.25,0.75,0.25 ; (v00,v01) cols (a,b),(b,c),(b,c),(c,d)
    let o0 = (1.0 - wy) * (0.25 * a0 + 0.75 * b0) + wy * (0.25 * a1 + 0.75 * b1);
    let o1 = (1.0 - wy) * (0.75 * b0 + 0.25 * c0) + wy * (0.75 * b1 + 0.25 * c1);
    let o2 = (1.0 - wy) * (0.25 * b0 + 0.75 * c0) + wy * (0.25 * b1 + 0.75 * c1);
    let o3 = (1.0 - wy) * (0.75 * c0 + 0.25 * d0) + wy * (0.75 * c1 + 0.25 * d1);
{% endif %}
    y[v] = vec4<{{ scalar }}>(vec4<f32>(o0, o1, o2, o3));
  }
{% else %}
  for (var i = gid.x; i < COUNT; i += stride) {
    let ow = i % OUT_W;
    let t = i / OUT_W;
    let oh = t % OUT_H;
    let nc = t / OUT_H;
    let base = nc * IN_HW;
    let qy = i32(oh / 2u);
    let qx = i32(ow / 2u);
    let oddY = (oh & 1u) == 1u;
    let oddX = (ow & 1u) == 1u;
{% if coordinateMode == "asymmetric" %}
    let y0 = qy;
    let x0 = qx;
    let wy = select(0.0, 0.5, oddY);
    let wx = select(0.0, 0.5, oddX);
{% else %}
    let y0 = qy - 1 + i32(oh & 1u);
    let x0 = qx - 1 + i32(ow & 1u);
    let wy = select(0.75, 0.25, oddY);
    let wx = select(0.75, 0.25, oddX);
{% endif %}
    let y1 = y0 + 1;
    let x1 = x0 + 1;
    let v00 = input_at(base, y0, x0);
    let v01 = input_at(base, y0, x1);
    let v10 = input_at(base, y1, x0);
    let v11 = input_at(base, y1, x1);
    let result = (1.0 - wy) * ((1.0 - wx) * v00 + wx * v01) + wy * ((1.0 - wx) * v10 + wx * v11);
    y[i] = {{ scalar }}(result);
  }
{% endif %}
}

