{% macro flat_index_2d(workgroupSize, name="i", bound="params.count", guardInline=false) %}
{% set wgTerm = workgroupSize ~ "u" if workgroupSize is number else workgroupSize %}
  // 2D-folded flat index: gid.y carries the high bits past the dispatch's
  // per-axis workgroup fold width.
  let {{ name }} = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ wgTerm }};
  if ({{ name }} >= {{ bound }}) {
    return;
  }{% endmacro %}
{{ env.wgsl.resourceDeclarations }}

fn read_x(index: u32) -> f32 {
  return f32(x[index / 4u][index % 4u]);
}

@compute @workgroup_size({{ rotaryOutputWg }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
{{ flat_index_2d(rotaryOutputWg, "q", "params.quadCount") }}
  let head = q / {{ (headElements / 4) | int }}u;
  let d0 = (q % {{ (headElements / 4) | int }}u) * 4u;
  let base = head * {{ headElements }}u;
{% if (rotationPairs * 2) % 4 != 0 %}
  var result = x[q];
{% else %}
  var result: {{ vector }};
{% endif %}
{% if rotationPairs * 2 < headElements %}
  if (d0 >= {{ rotationPairs * 2 }}u) {
    y[q] = x[q];
    return;
  }
{% endif %}
{% if rank == 3 %}
  let token = (head / {{ max(1, headCount) }}u) % {{ max(1, tokenCount) }}u;
  let batch = head / {{ max(1, headCount * tokenCount) }}u;
{% else %}
  let token = head % {{ max(1, tokenCount) }}u;
  let batch = head / {{ max(1, tokenCount * headCount) }}u;
{% endif %}
{% if hasPositionIds %}
  let cache = u32(position_ids[batch * {{ tokenCount }}u + token]) * {{ rotationPairs }}u;
{% else %}
  let cache = (batch * {{ tokenCount }}u + token) * {{ rotationPairs }}u;
{% endif %}
{% for lane in range(4) %}
  {
    let d = d0 + {{ lane }}u;
{% if (rotationPairs * 2) % 4 != 0 %}
    if (d < {{ rotationPairs * 2 }}u) {
{% endif %}
      let first = d < {{ rotationPairs }}u;
      let pair = select(d - {{ rotationPairs }}u, d, first);
      let a = read_x(base + pair);
      let b = read_x(base + pair + {{ rotationPairs }}u);
      let c = f32(cos_cache[cache + pair]);
      let s = f32(sin_cache[cache + pair]);
      result[{{ lane }}] = {{ scalar }}(select(a * s + b * c, a * c - b * s, first));
{% if (rotationPairs * 2) % 4 != 0 %}
    }
{% endif %}
  }
{% endfor %}
  y[q] = result;
}

