{% macro flat_index_2d(workgroupSize, name="i", bound="params.count", guardInline=false) %}
{% set wgTerm = workgroupSize ~ "u" if workgroupSize is number else workgroupSize %}
  // 2D-folded flat index: gid.y carries the high bits past the dispatch's
  // per-axis workgroup fold width.
  let {{ name }} = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ wgTerm }};
  if ({{ name }} >= {{ bound }}) {
    return;
  }{% endmacro %}
{{ env.wgsl.resourceDeclarations }}
// One invocation owns four consecutive rotated pairs, so x, cos and sin are read as vec4s and
// both rotated outputs are written as vec4s; the head size and rotary dim are multiples of
// eight, so no quad straddles a head or the rotated/tail boundary. Partial rotations use the
// remaining quad lanes to copy two unchanged tail vec4s. Every index below counts vec4s.
@compute @workgroup_size({{ tunables.WORKGROUP_SIZE }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
{{ flat_index_2d(tunables.WORKGROUP_SIZE, "q", "params.quadCount") }}

  let task = q % params.headQuads;
  let headFlat = q / params.headQuads;
  let base = headFlat * params.headVec4;

  if (task >= params.halfRotaryVec4) {
    let tail = params.rotaryVec4 + (task - params.halfRotaryVec4) * 2u;
    y[base + tail] = x[base + tail];
    y[base + tail + 1u] = x[base + tail + 1u];
    return;
  }

  let pair = task;
{% if rank == 3 %}
  let token = (headFlat / params.numHeads) % params.sequenceLength;
  let batch = headFlat / (params.numHeads * params.sequenceLength);
{% else %}
  let token = headFlat % params.sequenceLength;
  let batch = (headFlat / params.sequenceLength) / params.numHeads;
{% endif %}
{% if hasPositionIds is defined and hasPositionIds %}
  // Gather the 2D cache tables through this token's position index.
  let cache = u32(position_ids[batch * params.sequenceLength + token]) * params.halfRotaryVec4 + pair;
{% else %}
  // The standard no-index cache owns one row per (batch, token).
  let cache = batch * params.cacheBatchStrideVec4 + token * params.halfRotaryVec4 + pair;
{% endif %}
  let cf = vec4<f32>(cos_cache[cache]);
  let sf = vec4<f32>(sin_cache[cache]);
{% if interleaved %}
  // Four interleaved pairs span two vec4s: (x0.x, x0.y), (x0.z, x0.w), (x1.x, x1.y), (x1.z, x1.w).
  let x0 = vec4<f32>(x[base + pair * 2u]);
  let x1 = vec4<f32>(x[base + pair * 2u + 1u]);
  let a = vec4<f32>(x0.x, x0.z, x1.x, x1.z);
  let b = vec4<f32>(x0.y, x0.w, x1.y, x1.w);
  let ra = a * cf - b * sf;
  let rb = a * sf + b * cf;
  y[base + pair * 2u] = {{ vector }}(vec4<f32>(ra.x, rb.x, ra.y, rb.y));
  y[base + pair * 2u + 1u] = {{ vector }}(vec4<f32>(ra.z, rb.z, ra.w, rb.w));
{% else %}
  let a = vec4<f32>(x[base + pair]);
  let b = vec4<f32>(x[base + params.halfRotaryVec4 + pair]);
  y[base + pair] = {{ vector }}(a * cf - b * sf);
  y[base + params.halfRotaryVec4 + pair] = {{ vector }}(a * sf + b * cf);
{% endif %}
}

webgpu-kernels/ai.onnx.RotaryEmbedding.rotary-embedding.wgsl.jinja:
{% macro flat_index_2d(workgroupSize, name="i", bound="params.count", guardInline=false) %}
{% set wgTerm = workgroupSize ~ "u" if workgroupSize is number else workgroupSize %}
  // 2D-folded flat index: gid.y carries the high bits past the dispatch's
  // per-axis workgroup fold width.
  let {{ name }} = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ wgTerm }};
  if ({{ name }} >= {{ bound }}) {
    return;
  }{% endmacro %}
{{ env.wgsl.resourceDeclarations }}
// One invocation owns both outputs of a rotated pair, so x/cos/sin are read once.
// Partial rotations use the remaining pair lanes to copy two unchanged tail values.
@compute @workgroup_size({{ tunables.WORKGROUP_SIZE }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
{{ flat_index_2d(tunables.WORKGROUP_SIZE, "p", "params.pairCount") }}

  let tasksPerHead = params.headSize / 2u;
  let task = p % tasksPerHead;
  let headFlat = p / tasksPerHead;
  let base = headFlat * params.headSize;

  if (task >= params.halfRotaryDim) {
    let tail = params.rotaryDim + (task - params.halfRotaryDim) * 2u;
    y[base + tail] = x[base + tail];
    y[base + tail + 1u] = x[base + tail + 1u];
    return;
  }

  let pair = task;
{% if rank == 3 %}
  let token = (headFlat / params.numHeads) % params.sequenceLength;
  let batch = headFlat / (params.numHeads * params.sequenceLength);
{% else %}
  let token = headFlat % params.sequenceLength;
  let batch = (headFlat / params.sequenceLength) / params.numHeads;
{% endif %}
{% if hasPositionIds is defined and hasPositionIds %}
  // Gather the 2D cache tables through this token's position index.
  let cache = u32(position_ids[batch * params.sequenceLength + token]) * params.halfRotaryDim + pair;
{% else %}
  // The standard no-index cache owns one row per (batch, token).
  let cache = batch * params.cacheBatchStride + token * params.halfRotaryDim + pair;
{% endif %}
  let cf = f32(cos_cache[cache]);
  let sf = f32(sin_cache[cache]);
{% if interleaved %}
  let aOffset = pair * 2u;
  let bOffset = aOffset + 1u;
{% else %}
  let aOffset = pair;
  let bOffset = pair + params.halfRotaryDim;
{% endif %}
  let a = f32(x[base + aOffset]);
  let b = f32(x[base + bOffset]);
  y[base + aOffset] = {{ scalar }}(a * cf - b * sf);
  y[base + bOffset] = {{ scalar }}(a * sf + b * cf);
}

