webgpu-kernels/ai.onnx.RNN.rnn-sequence-mask.wgsl.jinja:
// Post-processes a forward, layout-0 recurrent result for arbitrary
// sequence_lens. This pass zeroes each padded tail and gathers the last valid
// state into Y_h.
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;

@compute @workgroup_size({{ workgroupSize }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>,
        @builtin(num_workgroups) nwg: vec3<u32>) {
  let stride = nwg.x * nwg.y * WG;
  let count = params.seq * params.batch * params.hidden;
  for (var i = gid.y * ({{ DISPATCH_FOLD_WIDTH }}u * WG) + gid.x; i < count; i += stride) {
    let h = i % params.hidden;
    let tb = i / params.hidden;
    let batch_index = tb % params.batch;
    let t = tb / params.batch;
    let seq_len = min(params.seq, u32(max(sequence_lens[batch_index], 0)));

    // One thread per final-state element gathers the last valid prefix state.
    // A zero-length sequence has an all-zero final state.
    if (t == 0u) {
      let state_offset = batch_index * params.hidden + h;
      if (seq_len == 0u) {
        y_h[state_offset] = 0.0;
      } else {
        let final_offset = ((seq_len - 1u) * params.batch + batch_index) * params.hidden + h;
        y_h[state_offset] = y[final_offset];
      }
    }

    if (t >= seq_len) {
      y[i] = 0.0;
    }
  }
}

webgpu-kernels/ai.onnx.RNN.rnn-input-proj.wgsl.jinja:
// Precompute, for every timestep t, batch element n, and gate-hidden row gate_h,
// the input contribution
//   xproj[(t*batch + n)*GH + gate_h] = sum_i X[t, n, i] * W[gate_h, i]
// where GH = gates*hidden. This exposes [seq*batch,in] x [in,GH] as a
// data-parallel matrix multiplication before the serial recurrence.
//
// The bias-free contraction keeps ascending input order. The recurrence adds
// this partial where its inline input dot would occur; only the bias association
// changes, while recurrent terms retain their original ordering.
{% macro flat_index_2d(workgroupSize, name="i", bound="params.count", guardInline=false) %}
{% set wgTerm = workgroupSize ~ "u" if workgroupSize is number else workgroupSize %}
  // 2D-folded flat index: gid.y carries the high bits past the dispatch's
  // per-axis workgroup fold width.
  let {{ name }} = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ wgTerm }};
  if ({{ name }} >= {{ bound }}) { return; }{% endmacro %}
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;
// GATES is the number of W output blocks; GH = GATES * hidden.
const GATES: u32 = {{ gates }}u;

@compute @workgroup_size({{ workgroupSize }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let hidden = params.hidden;
  let gh = GATES * hidden;
  let total = params.seq * params.batch * gh;
{{ flat_index_2d("WG", "idx", "total", guardInline=true) }}
  // idx = (t*batch + n) * gh + gate_h ; the X row is (t*batch + n), the W row is gate_h.
  let x_row = idx / gh;
  let w_row = idx % gh;
  var acc = 0.0;
{% if useVec4 or useInputVec4 %}
  let vec_input = params.inputSize / 4u;
  let x_base = x_row * vec_input;
  let w_base = w_row * vec_input;
  for (var i = 0u; i < vec_input; i = i + 1u) {
    acc = acc + dot(x[x_base + i], w[w_base + i]);
  }
{% elif vec4Tail %}
  let x_base = x_row * params.inputSize;
  let w_base = w_row * params.inputSize;
  let vec_input = params.inputSize / 4u;
  for (var i = 0u; i < vec_input; i = i + 1u) {
    let j = 4u * i;
    let xv = vec4<f32>(x[x_base + j], x[x_base + j + 1u], x[x_base + j + 2u], x[x_base + j + 3u]);
    let wv = vec4<f32>(w[w_base + j], w[w_base + j + 1u], w[w_base + j + 2u], w[w_base + j + 3u]);
    acc += dot(xv, wv);
  }
  for (var i = vec_input * 4u; i < params.inputSize; i += 1u) {
    acc += x[x_base + i] * w[w_base + i];
  }
{% else %}
  let x_base = x_row * params.inputSize;
  let w_base = w_row * params.inputSize;
  for (var i = 0u; i < params.inputSize; i = i + 1u) {
    acc = acc + x[x_base + i] * w[w_base + i];
  }
{% endif %}
  xproj[idx] = acc;
}

webgpu-kernels/ai.onnx.RNN.rnn-parallel-global.wgsl.jinja:
// Parallel RNN forward for hidden state that does not fit workgroup storage.
// One workgroup owns each batch element, with storageBarrier() sequencing the
// recurrence over storage-backed state. Bias, input, and recurrent terms
// accumulate in that order.
{% set vec4Tail = vec4Tail is defined and vec4Tail %}

fn clip_input(x: f32) -> f32 {
{% if hasClip %}
  return clamp(x, -{{ clip }}, {{ clip }});
{% else %}
  return x;
{% endif %}
}

fn tanh_safe(x: f32) -> f32 {
  // tanh rounds to +/-1 for these tails in f32. Return the saturated value
  // directly, including for infinite input, before invoking the builtin.
  if (x > 10.0) { return 1.0; }
  if (x < -10.0) { return -1.0; }
  return tanh(x);
}

// Input projection: acc_in + sum_i x[x_row, i] * w[w_row, i]. The contraction
// visits i in ascending order after seeding the accumulator with acc_in.
fn input_dot(acc_in: f32, x_row: u32, w_row: u32) -> f32 {
  var acc = acc_in;
{% if useVec4 or useInputVec4 %}
  let vec_input = params.inputSize / 4u;
  let x_base = x_row * vec_input;
  let w_base = w_row * vec_input;
  for (var i = 0u; i < vec_input; i = i + 1u) {
    acc = acc + dot(x[x_base + i], w[w_base + i]);
  }
{% elif vec4Tail %}
  // f32-bound x/w (any inputSize alignment): dot floor(inputSize/4) manually
  // assembled vec4s, then a scalar remainder over inputSize % 4. dot(vec4(...))
  // over 4 contiguous f32 is bit-identical to a vec4-load dot. The scalar tail
  // retains ascending term order.
  let x_base = x_row * params.inputSize;
  let w_base = w_row * params.inputSize;
  let vec_input = params.inputSize / 4u;
  for (var i = 0u; i < vec_input; i = i + 1u) {
    let xb = x_base + 4u * i;
    let wb = w_base + 4u * i;
    let xv = vec4<f32>(x[xb], x[xb + 1u], x[xb + 2u], x[xb + 3u]);
    let wv = vec4<f32>(w[wb], w[wb + 1u], w[wb + 2u], w[wb + 3u]);
    acc = acc + dot(xv, wv);
  }
  for (var i = vec_input * 4u; i < params.inputSize; i = i + 1u) {
    acc = acc + x[x_base + i] * w[w_base + i];
  }
{% else %}
  let x_base = x_row * params.inputSize;
  let w_base = w_row * params.inputSize;
  for (var i = 0u; i < params.inputSize; i = i + 1u) {
    acc = acc + x[x_base + i] * w[w_base + i];
  }
{% endif %}
  return acc;
}

{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ workgroupSize }}u;

@compute @workgroup_size({{ workgroupSize }})
fn main(@builtin(workgroup_id) wg_id: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
  // Fold the batch index across x/y. The uniform guard must precede every
  // barrier and memory access.
  let batch_index = wg_id.x + wg_id.y * {{ DISPATCH_FOLD_WIDTH }}u;
  if (batch_index >= params.batch) { return; }
  let hidden = params.hidden;
  let h_base = batch_index * hidden;
  for (var h = lid.x; h < hidden; h = h + WG) {
    prev_h[h_base + h] = 0.0;
  }
  storageBarrier();
  for (var t = 0u; t < params.seq; t = t + 1u) {
    let x_row = t * params.batch + batch_index;
    let has_next = t + 1u < params.seq;
    // Stage 1: hidden-unit activations. Writes go to new_h so the recurrent
    // reads of prev_h stay stable within the stage.
    for (var h = lid.x; h < hidden; h = h + WG) {
      var acc = b[h] + b[hidden + h];
      acc = input_dot(acc, x_row, h);
      let r_base = h * hidden;
      for (var rh = 0u; rh < hidden; rh = rh + 1u) {
        acc = acc + prev_h[h_base + rh] * r[r_base + rh];
      }
      let value = tanh_safe(clip_input(acc));
      if (has_next) {
        new_h[h_base + h] = value;
      }
      y[x_row * hidden + h] = value;
      if (t + 1u == params.seq) {
        y_h[h_base + h] = value;
      }
    }
    if (has_next) {
      storageBarrier();
      // Stage 2: publish the updated hidden state for the next timestep.
      for (var h = lid.x; h < hidden; h = h + WG) {
        prev_h[h_base + h] = new_h[h_base + h];
      }
      storageBarrier();
    }
  }
}

webgpu-kernels/ai.onnx.RNN.datamove-transpose-2d-tiled.wgsl.jinja:
{% set tileSize = 32 %}
// Tiled 2D transpose (optionally batched) over vec4 elements.
//
// Layout contract:
// - src is row-major [batch, ROWS, COLS], dst is row-major [batch, COLS, ROWS]
// - ROWS % 4 == 0 and COLS % 4 == 0, so both buffers bind as vec4<T>
// - dispatch: x = ceil(COLS / TILE), y = ceil(ROWS / TILE), z = batch
//
// Each (TILE / 4) x TILE workgroup moves one TILE x TILE scalar tile through
// workgroup memory.
// Global loads and stores each traverse consecutive vec4 addresses. The extra
// workgroup-memory column changes the transposed stride and reduces
// bank-conflict risk on banked implementations.
{{ env.wgsl.resourceDeclarations }}

const ROWS: u32 = {{ rowCount }}u;
const COLS: u32 = {{ cols }}u;
const ROWS_V: u32 = {{ ((rowCount / 4) | int) }}u;
const COLS_V: u32 = {{ ((cols / 4) | int) }}u;
const MAT_V: u32 = {{ (((rowCount * cols * (transposePlaneMiddle | default(1))) / 4) | int) }}u;
const TILE: u32 = {{ tileSize }}u;

var<workgroup> tile: array<array<{{ scalar }}, {{ tileSize + 1 }}>, {{ tileSize }}>;

@compute @workgroup_size({{ (tileSize / 4) | int }}, {{ tileSize }}, 1)
fn main(
  @builtin(workgroup_id) wid: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>
) {
  let batch_base = wid.z * MAT_V;
  let row_base = wid.y * TILE;
  let col_base = wid.x * TILE;

  let r = row_base + lid.y;
  let cv = (col_base / 4u) + lid.x;
  if (r < ROWS && cv < COLS_V) {
    let v = src[batch_base + r * COLS_V + cv];
    tile[lid.y][lid.x * 4u + 0u] = v.x;
    tile[lid.y][lid.x * 4u + 1u] = v.y;
    tile[lid.y][lid.x * 4u + 2u] = v.z;
    tile[lid.y][lid.x * 4u + 3u] = v.w;
  }
  workgroupBarrier();

  let out_row = col_base + lid.y;
  let rv = (row_base / 4u) + lid.x;
  if (out_row < COLS && rv < ROWS_V) {
    dst[batch_base + out_row * ROWS_V + rv] = {{ vectorScalar }}(
      tile[lid.x * 4u + 0u][lid.y],
      tile[lid.x * 4u + 1u][lid.y],
      tile[lid.x * 4u + 2u][lid.y],
      tile[lid.x * 4u + 3u][lid.y]
    );
  }
}

webgpu-kernels/ai.onnx.RNN.dense-tiled-matmul.wgsl.jinja:
{% set mPerThread = 1 %}
{% set rowVar = "m_local" %}
{% set F32_OPEN = "" %}
{% set F32_CLOSE = "" %}
{{ env.wgsl.resourceDeclarations }}

// Dense GEMM: A[M,K] · Bᵀ from B[N,K] → Y[M,N]. Each workgroup stages
// M_TILE rows and OUT_TILE weights, then reuses them across the output tile.
const K: u32 = {{ inFeatures }}u;
const N: u32 = {{ outFeatures }}u;
const K_V4: u32 = {{ kV4 }}u;
const M_TILE: u32 = {{ mTile }}u;
const N_TILE: u32 = {{ nTile }}u;
const OUT_TILE: u32 = {{ outTile }}u;
const K_TILE: u32 = {{ kTile }}u;
const K_TILE_V4: u32 = {{ kTileV4 }}u;
const WG: u32 = {{ workgroupSize }}u;
var<workgroup> aTile: array<vec4<{{ tileDtype }}>, {{ aTileElements }}>;
var<workgroup> bTile: array<vec4<{{ tileDtype }}>, {{ bTileElements }}>;

@compute @workgroup_size(WG, 1, 1)
fn main(@builtin(workgroup_id) wg: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>, @builtin(num_workgroups) nwg: vec3<u32>) {
  let tid = lid.x;
  let m_local = tid / N_TILE;
  let n_local = tid - m_local * N_TILE;
  // Grid-striding preserves coverage when either tile count exceeds the
  // per-dimension dispatch limit; otherwise both loops execute once.
  let n_tiles = (N + OUT_TILE - 1u) / OUT_TILE;
  let m_tiles = (params.M + M_TILE - 1u) / M_TILE;
  for (var wgx: u32 = wg.x; wgx < n_tiles; wgx = wgx + nwg.x) {
    let n0 = wgx * OUT_TILE + n_local;
    for (var wgy: u32 = wg.y; wgy < m_tiles; wgy = wgy + nwg.y) {
      let m = wgy * M_TILE + {{ rowVar }};
{% for acc in range(mPerThread * nPerThread) %}
      var acc{{ acc }}: f32 = 0.0;
{% endfor %}

      for (var k_base: u32 = 0u; k_base < K; k_base = k_base + K_TILE) {
        let k_base_v4 = k_base / 4u;
        for (var i: u32 = tid; i < {{ aTileElements }}u; i = i + WG) {
          let tm = i / K_TILE_V4;
          let kv = i - tm * K_TILE_V4;
          let gm = wgy * M_TILE + tm;
          if (gm < params.M) {
            aTile[i] = a[gm * K_V4 + k_base_v4 + kv];
          } else {
            aTile[i] = vec4<{{ tileDtype }}>(0.0);
          }
        }
        for (var i: u32 = tid; i < {{ bTileElements }}u; i = i + WG) {
          let tn = i / K_TILE_V4;
          let kv = i - tn * K_TILE_V4;
          let gn = wgx * OUT_TILE + tn;
          if (gn < N) {
            bTile[i] = w[gn * K_V4 + k_base_v4 + kv];
          } else {
            bTile[i] = vec4<{{ tileDtype }}>(0.0);
          }
        }
        workgroupBarrier();

        if (m < params.M) {
          for (var kv: u32 = 0u; kv < K_TILE_V4; kv = kv + 1u) {
            let a_idx = m_local * K_TILE_V4 + kv;
            let a_vec = aTile[a_idx];
{% for nn in range(nPerThread) %}
            let b_idx{{ nn }} = (n_local + {{ nn * nTile }}u) * K_TILE_V4 + kv;
            acc{{ nn }} = acc{{ nn }} + dot({{ F32_OPEN }}a_vec{{ F32_CLOSE }}, {{ F32_OPEN }}bTile[b_idx{{ nn }}]{{ F32_CLOSE }});
{% endfor %}
          }
        }
        workgroupBarrier();
      }

{% for mm in range(mPerThread) %}{% set mRow = "m" if mPerThread == 1 else "(m + " ~ mm ~ "u)" %}{% set aBase = mm * nPerThread %}
      if ({{ mRow }} < params.M) {
{% for nn in range(nPerThread) %}
        if (n0 + {{ nn * nTile }}u < N) {
          y[{{ mRow }} * N + n0 + {{ nn * nTile }}u] = acc{{ aBase + nn }};
        }
{% endfor %}
      }
{% endfor %}
    }
  }
}

