// One globally synchronized RNN timestep. Workgroups tile the output-hidden
// dimension while each lane owns one vec4 of outputs. The previous timestep is
// already materialized in Y by the preceding dispatch, so no workgroup-local
// state or cross-workgroup software barrier is needed.

fn clip_input(x: f32) -> f32 {
{% if hasClip %}
  return clamp(x, -{{ clip }}, {{ clip }});
{% else %}
  return x;
{% endif %}
}

fn tanh_safe(x: f32) -> f32 {
  // tanh rounds to +/-1 for these tails in f32. Return the saturated value
  // directly, including for infinite input, before invoking the builtin.
  if (x > 10.0) { return 1.0; }
  if (x < -10.0) { return -1.0; }
  return tanh(x);
}
