const WG: u32 = {{ recurrentWorkgroupSize }}u;

@compute @workgroup_size({{ recurrentWorkgroupSize }})
fn main(
  @builtin(workgroup_id) wg_id: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>,
) {
  let vec_hidden = params.hidden / 4u;
  let h4 = wg_id.x * WG + lid.x;
  let batch_index = wg_id.y;
  if (h4 >= vec_hidden || batch_index >= params.batch) { return; }

  let x_row = params.t * params.batch + batch_index;
  let row_base = x_row * vec_hidden;
  var gate = PackedRnnStep(b[h4] + b[vec_hidden + h4] + xproj[row_base + h4]);

  // t=0 has an implicit all-zero initial state. Avoid reading the full HxH
  // matrix for a product that is identically zero; later timesteps retain the
  // packed kernel's ascending groups-of-four accumulation order.
  if (params.t != 0u) {
    let prev_base = ((params.t - 1u) * params.batch + batch_index) * vec_hidden;
    gate = recurrent_rnn_dot4(gate, 0u, h4, prev_base);
  }

  let value = vec4<f32>(
    tanh_safe(clip_input(gate.g0.x)), tanh_safe(clip_input(gate.g0.y)),
    tanh_safe(clip_input(gate.g0.z)), tanh_safe(clip_input(gate.g0.w)));
  y[row_base + h4] = value;
  if (params.t + 1u == params.seq) {
    y_h[batch_index * vec_hidden + h4] = value;
  }
}

