// One workgroup per update row computes its normalized output offset and
// vec4-copies the contiguous inner slice from updates[row] into
// output[scatter_index]. This path handles indexDepth == 1 (scatter along
// data axis 0) with an inner size divisible by four. It performs no reduction;
// indices must be unique, as required by ONNX for reduction=none.
{{ env.wgsl.resourceDeclarations }}

const WG: u32 = {{ tunables.WORKGROUP_SIZE }}u;
const NUM_INDICES: u32 = {{ numIndices }}u;
const AXIS_DIM: u32 = {{ axisDimSpec }}u;
const ROW_VECS: u32 = {{ rowVecs }}u;
const INVALID_INDEX: u32 = 0xffffffffu;

fn normalize_index(raw: {{ indexScalar }}, dim: u32) -> u32 {
  let dim_i = i32(dim);
  var index = raw;
  if (index < 0) {
    index = index + dim_i;
  }
  if (index < 0 || index >= dim_i) {
    return INVALID_INDEX;
  }
  return u32(index);
}

@compute @workgroup_size({{ tunables.WORKGROUP_SIZE }})
fn main(
  @builtin(workgroup_id) wid: vec3<u32>,
  @builtin(num_workgroups) nwg: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>
) {
  for (var row = wid.x; row < NUM_INDICES; row += nwg.x) {
    let scatter_index = normalize_index(indices[row], AXIS_DIM);
    // Defensively skip out-of-range indices, which are invalid ONNX inputs.
    // The continue is uniform across the workgroup (all threads share `row`).
    if (scatter_index == INVALID_INDEX) {
      continue;
    }
    let src_base = row * ROW_VECS;
    let dst_base = scatter_index * ROW_VECS;
    for (var j = lid.x; j < ROW_VECS; j += WG) {
      output[dst_base + j] = updates[src_base + j];
    }
  }
}

