fn normalize_index(raw: {{ indexScalar }}, dim: u32) -> u32 {
  let dim_i = i32(dim);
  var index = raw;
  if (index < 0) {
    index = index + dim_i;
  }
  if (index < 0 || index >= dim_i) {
    return INVALID_INDEX;
  }
  return u32(index);
}

fn atomic_add_f32(update: f32) {
  var old_bits = atomicLoad(&output[0]);
  loop {
    let result = atomicCompareExchangeWeak(
      &output[0], old_bits, bitcast<u32>(bitcast<f32>(old_bits) + update)
    );
    if (result.exchanged) { break; }
    old_bits = result.old_value;
  }
}

