fn main(
  @builtin(global_invocation_id) gid: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>,
  @builtin(num_workgroups) nwg: vec3<u32>
) {
  let total_threads = nwg.x * WG;
  var sum = 0.0;
  for (var i = gid.x; i < params.count; i += total_threads) {
    if (normalize_index(indices[i], 1u) != INVALID_INDEX) {
      sum += updates[i];
