webgpu-kernels/ai.onnx.ScatterElements.scatter-elements-f32-add-axis0-histogram:
// Rank-2 axis-0 f32 add reduction tiled across independent columns and striped
// across the updates axis. ScatterElements preserves every non-axis coordinate,
// so columns cannot collide. One workgroup owns 32 adjacent columns and one
// stripe of update rows, folds that stripe into workgroup bins, then adds each
// bin it touched into the output with a single device atomic. Striping is what
// widens the grid: without it the dispatch is ceil(columns / 32) workgroups
// however many update rows there are, and each of those workgroups walks the
// whole updates axis.
//
// Bins are laid out `[axis row, column lane]`, so adjacent lanes use consecutive
// index, update and output addresses. The copy pass has already materialized
// data into the output, so bins start at zero and a stripe that contributes
// nothing to a cell leaves it untouched.
{{ env.wgsl.resourceDeclarations }}

const COLUMN_LANES: u32 = {{ histogramColumnLanes }}u;
const UPDATE_ROW_LANES: u32 = {{ histogramRowLanes }}u;
const WORKGROUP_THREADS: u32 = COLUMN_LANES * UPDATE_ROW_LANES;
const DATA_ROWS: u32 = {{ dataRows }}u;
const COLUMNS: u32 = {{ columns }}u;
const UPDATE_ROWS: u32 = {{ updateRows }}u;
const ROW_STRIPES: u32 = {{ rowStripes }}u;
const STRIPE_STEP: u32 = ROW_STRIPES * UPDATE_ROW_LANES;
const INVALID_INDEX: u32 = 0xffffffffu;

var<workgroup> bins: array<atomic<u32>, {{ dataRows * histogramColumnLanes }}>;

fn normalize_index(raw: {{ indexScalar }}, dim: u32) -> u32 {
  let dim_i = i32(dim);
  var index = raw;
  if (index < 0) {
    index = index + dim_i;
  }
  if (index < 0 || index >= dim_i) {
    return INVALID_INDEX;
