// Real-input RFFT specialization. Pack even/odd samples into one N/2-point
// complex transform, then reconstruct the N/2+1 non-redundant bins. This cuts
// the Stockham butterfly count almost in half while preserving the same fused
// window load as the full complex STFT kernel.
const N: u32 = {{ fftLength }}u;
const PACKED_N: u32 = N / 2u;
const PACKED_HALF: u32 = PACKED_N / 2u;
const NUM_BINS: u32 = PACKED_N + 1u;
const FFT_LANES: u32 = {{ tunables.WORKGROUP_SIZE }}u;
const TRANSFORMS_PER_WG: u32 = {{ transformsPerWorkgroup | default(1) }}u;
const WG: u32 = FFT_LANES * TRANSFORMS_PER_WG;
const STAGE_TWIDDLES: u32 = PACKED_N - 1u;
const SHARED_STRIDE: u32 = 2u * PACKED_N;

var<workgroup> shRe: array<f32, SHARED_STRIDE * TRANSFORMS_PER_WG>;
var<workgroup> shIm: array<f32, SHARED_STRIDE * TRANSFORMS_PER_WG>;

fn loadPacked(frameBase: u32, packed: u32, validTransform: bool) -> vec2<f32> {
  let even = 2u * packed;
  let odd = even + 1u;
  var value = vec2<f32>(0.0);
  if (validTransform) {
    value.x = signal[frameBase + even] * window[even];
    value.y = signal[frameBase + odd] * window[odd];
  }
  return value;
}

@compute @workgroup_size(WG)
fn main(@builtin(workgroup_id) wgid: vec3<u32>,
        @builtin(local_invocation_id) lid: vec3<u32>) {
  let transform = lid.x / FFT_LANES;
  let tid = lid.x - transform * FFT_LANES;
  let batch = wgid.y;
  let frame = wgid.x * TRANSFORMS_PER_WG + transform;
  let validTransform = frame < params.numFrames;
  let start = frame * params.frameStep;
  let frameBase = batch * params.signalLength + start;
  let sharedBase = transform * SHARED_STRIDE;

  // Fuse pairs of radix-2 Stockham stages into radix-4 butterflies. An odd
  // packed log2 length starts with one radix-2 stage, after which every stage
  // can be paired. The second stage's root B is sufficient: A=B^2 and C=B^3.
  // The first butterfly loads windowed samples directly, avoiding a separate
  // shared-memory load phase and its barrier.
  var srcOff = sharedBase + PACKED_N;
  var dstOff = sharedBase;
  var radix = 1u;
  if ((countTrailingZeros(PACKED_N) & 1u) != 0u) {
    for (var j = tid; j < PACKED_HALF; j = j + FFT_LANES) {
      let a = loadPacked(frameBase, j, validTransform);
      let b = loadPacked(frameBase, PACKED_HALF + j, validTransform);
      shRe[srcOff + 2u * j] = a.x + b.x;
      shIm[srcOff + 2u * j] = a.y + b.y;
      shRe[srcOff + 2u * j + 1u] = a.x - b.x;
      shIm[srcOff + 2u * j + 1u] = a.y - b.y;
    }
    workgroupBarrier();
    radix = 2u;
  } else {
    for (var j = tid; j < PACKED_N / 4u; j = j + FFT_LANES) {
      let x0 = loadPacked(frameBase, j, validTransform);
      let x1 = loadPacked(frameBase, PACKED_N / 4u + j, validTransform);
      let x2 = loadPacked(frameBase, PACKED_N / 2u + j, validTransform);
      let x3 = loadPacked(frameBase, 3u * PACKED_N / 4u + j, validTransform);
      let evenSum = x0 + x2;
      let evenDiff = x0 - x2;
      let oddSum = x1 + x3;
      let oddDiff = x1 - x3;
      shRe[srcOff + 4u * j] = evenSum.x + oddSum.x;
      shIm[srcOff + 4u * j] = evenSum.y + oddSum.y;
      shRe[srcOff + 4u * j + 1u] = evenDiff.x + oddDiff.y;
      shIm[srcOff + 4u * j + 1u] = evenDiff.y - oddDiff.x;
      shRe[srcOff + 4u * j + 2u] = evenSum.x - oddSum.x;
      shIm[srcOff + 4u * j + 2u] = evenSum.y - oddSum.y;
      shRe[srcOff + 4u * j + 3u] = evenDiff.x - oddDiff.y;
      shIm[srcOff + 4u * j + 3u] = evenDiff.y + oddDiff.x;
    }
    workgroupBarrier();
    radix = 4u;
  }
  for (; radix < PACKED_N; radix = radix * 4u) {
    for (var j = tid; j < PACKED_N / 4u; j = j + FFT_LANES) {
      let jm = j & (radix - 1u);
      let outBase = ((j / radix) * (4u * radix)) + jm;

      let x0r = shRe[srcOff + j];
      let x0i = shIm[srcOff + j];
      let x1r = shRe[srcOff + PACKED_N / 4u + j];
      let x1i = shIm[srcOff + PACKED_N / 4u + j];
      let x2r = shRe[srcOff + PACKED_N / 2u + j];
      let x2i = shIm[srcOff + PACKED_N / 2u + j];
      let x3r = shRe[srcOff + 3u * PACKED_N / 4u + j];
      let x3i = shIm[srcOff + 3u * PACKED_N / 4u + j];

      let twiddleIndex = 2u * radix - 1u + jm;
      let br = twiddles[2u * twiddleIndex];
      let bi = twiddles[2u * twiddleIndex + 1u];
      let ar = br * br - bi * bi;
      let ai = 2.0 * br * bi;
      let cr = ar * br - ai * bi;
      let ci = ar * bi + ai * br;

      let u1r = x1r * br - x1i * bi;
      let u1i = x1r * bi + x1i * br;
      let u2r = x2r * ar - x2i * ai;
      let u2i = x2r * ai + x2i * ar;
      let u3r = x3r * cr - x3i * ci;
      let u3i = x3r * ci + x3i * cr;

      let evenSumR = x0r + u2r;
      let evenSumI = x0i + u2i;
      let evenDiffR = x0r - u2r;
      let evenDiffI = x0i - u2i;
      let oddSumR = u1r + u3r;
      let oddSumI = u1i + u3i;
      let oddDiffR = u1r - u3r;
      let oddDiffI = u1i - u3i;

      shRe[dstOff + outBase] = evenSumR + oddSumR;
      shIm[dstOff + outBase] = evenSumI + oddSumI;
      shRe[dstOff + outBase + radix] = evenDiffR + oddDiffI;
      shIm[dstOff + outBase + radix] = evenDiffI - oddDiffR;
      shRe[dstOff + outBase + 2u * radix] = evenSumR - oddSumR;
      shIm[dstOff + outBase + 2u * radix] = evenSumI - oddSumI;
      shRe[dstOff + outBase + 3u * radix] = evenDiffR - oddDiffI;
      shIm[dstOff + outBase + 3u * radix] = evenDiffI + oddDiffR;
    }
    workgroupBarrier();
    let swap = srcOff;
    srcOff = dstOff;
    dstOff = swap;
  }

  let outRow = (batch * params.numFrames + frame) * NUM_BINS;
  for (var k = tid; validTransform && k < NUM_BINS; k = k + FFT_LANES) {
    let packedK = k & (PACKED_N - 1u);
    let mirrorK = (PACKED_N - packedK) & (PACKED_N - 1u);
    let zr = shRe[srcOff + packedK];
    let zi = shIm[srcOff + packedK];
    let mr = shRe[srcOff + mirrorK];
    let mi = shIm[srcOff + mirrorK];
    let sumRe = zr + mr;
    let sumIm = zi - mi;
    let diffRe = zr - mr;
    let diffIm = zi + mi;
    let rootIndex = STAGE_TWIDDLES + k;
    let c = twiddles[2u * rootIndex];
    let sn = twiddles[2u * rootIndex + 1u];
    let outBase = (outRow + k) * 2u;
    output[outBase] = 0.5 * (sumRe + c * diffIm + sn * diffRe);
    output[outBase + 1u] = 0.5 * (sumIm - c * diffRe + sn * diffIm);
  }
}

