    else if (li == 1) { t1 = w0; t2 = w1; }
    else { t2 = w0; }
    // 96-bit add acc += t (bits above 2^96 are multiples of 4, so discarded).
    let n0 = a0 + t0; let c0 = select(0u, 1u, n0 < a0);
    let n1a = a1 + t1; let c1a = select(0u, 1u, n1a < a1);
    let n1 = n1a + c0; let c1b = select(0u, 1u, n1 < n1a);
    let n2 = a2 + t2 + c1a + c1b;
    a0 = n0; a1 = n1; a2 = n2;
  }
  var n = a2 >> 30u;                            // integer part mod 4
  var phi = f32(a2 & 0x3fffffffu) * (1.0 / 1073741824.0)
          + f32(a1) * (1.0 / 4611686018427387904.0);   // fraction in [0,1)
  if (phi >= 0.5) { phi = phi - 1.0; n = n + 1u; }
  var out: Pio2;
  out.octant = n & 3u;
  out.r = phi * PIO2_F;
  return out;
}
{% endmacro %}
{% macro emit_sin_accurate() %}
fn sin_accurate(x: f32) -> f32 {
  if (is_nan_f32(x)) {
    return x;
  }
  if (is_inf_f32(x)) {
    return nan_from_inf_f32(x);
  }
  let ax = abs(x);
  var red: Pio2;
  if (ax < REDUCE_THRESHOLD) { red = reduce_pio2_fast(ax); }
  else { red = reduce_pio2(ax); }
  let reduced = precise_sincos_half_pi(red.r);
  var s: f32;
  switch (red.octant) {
    case 0u: { s = reduced.y; }
    case 1u: { s = reduced.x; }
    case 2u: { s = -reduced.y; }
    default: { s = -reduced.x; }
  }
  // sin is odd: transfer x's sign bit so sin(-0.0) stays -0.0 (x < 0.0 misses it).
  return bitcast<f32>(bitcast<u32>(s) ^ (bitcast<u32>(x) & 0x80000000u));
}
{% endmacro %}
{% macro emit_tan_accurate() %}
fn tan_accurate(x: f32) -> f32 {
  if (is_nan_f32(x)) {
    return x;
  }
  if (is_inf_f32(x)) {
    return nan_from_inf_f32(x);
  }
  let ax = abs(x);
  var red: Pio2;
  if (ax < REDUCE_THRESHOLD) { red = reduce_pio2_fast(ax); }
  else { red = reduce_pio2(ax); }
  let reduced = precise_sincos_half_pi(red.r);
  let sr = reduced.y;
  let cr = reduced.x;
  var sn: f32; var cs: f32;
  switch (red.octant) {
    case 0u: { sn = sr;  cs = cr;  }
    case 1u: { sn = cr;  cs = -sr; }
    case 2u: { sn = -sr; cs = -cr; }
    default: { sn = -cr; cs = sr;  }
  }
  let tn = sn / cs;
  // tan is odd: transfer x's sign bit so tan(-0.0) stays -0.0 (x < 0.0 misses it).
  return bitcast<f32>(bitcast<u32>(tn) ^ (bitcast<u32>(x) & 0x80000000u));
}
{% endmacro %}
