// Generic NCHW Resize/Upsample with full coordinate-transformation math.
// Explicit scales of zero are inferred from the output/input shape ratio.
// Nearest-index rounding is load-bearing for ONNX compatibility:
// round_prefer_ceil ties toward positive infinity, while round_prefer_floor
// uses its specified epsilon.
{% macro flat_index_2d(workgroupSize, name="i", bound="params.count", guardInline=false) %}
{% set wgTerm = workgroupSize ~ "u" if workgroupSize is number else workgroupSize %}
  // 2D-folded flat index: gid.y carries the high bits past the dispatch's
  // per-axis workgroup fold width.
  let {{ name }} = gid.x + gid.y * {{ DISPATCH_FOLD_WIDTH }}u * {{ wgTerm }};{% endmacro %}
{{ env.wgsl.resourceDeclarations }}
{% set wg = workgroupSize if workgroupSize is defined else tunables.WORKGROUP_SIZE %}

fn source_coord(out_coord: u32, in_size: u32, out_size: u32, explicit_scale: f32) -> f32 {
  // With an inferred scale, divide by sizes (out_coord*in/out) rather than by
  // the precomputed reciprocal out/in: the single division keeps exact ties
  // (e.g. a 7->2 downsample at out col 1 == 3.5) exact instead of landing at
  // 3.4999998 after double rounding. An explicit scale uses coord/scale.
  return select(f32(out_coord) * f32(in_size) / f32(out_size), f32(out_coord) / explicit_scale, explicit_scale > 0.0);
}
{% if modeSpec == "nearest" %}

/* Backend-stable nearest-neighbor coordinate selection. Inferred align-corners,
 * asymmetric, and half-pixel transforms use exact integer ratios. This matters
 * at nearest-mode ties: reassociating an f32 division into a reciprocal
 * multiply can move an exact 0.5 to either side of the boundary. */
fn nearest_index(v: f32) -> i32 {
  return i32(floor(v));
}

fn rational_value_nearest_index(numerator: u32, denominator: u32) -> i32 {
  if (numerator == 0u || denominator == 0u) {
    return 0;
  }
  let lower = numerator / denominator;
  return i32(lower);
}

fn rational_nearest_index(coord: u32, numerator: u32, denominator: u32) -> i32 {
  if (coord == 0u || numerator == 0u || denominator == 0u) {
    return 0;
  }
  // Use 0xfffffffe rather than UINT_MAX for the overflow guard: some shader
  // compilers reject division with a UINT_MAX constant dividend. The smaller
  // bound is conservative and sends at most one extra coordinate to the f32 path.
  if (coord > 0xfffffffeu / numerator) {
    return nearest_index(f32(coord) * f32(numerator) / f32(denominator));
  }
  return rational_value_nearest_index(coord * numerator, denominator);
}

fn nearest_coord_index(
  out_coord: u32,
  in_size: u32,
  out_size: u32,
  explicit_scale: f32
) -> i32 {
  if (explicit_scale <= 0.0) {
    return rational_nearest_index(out_coord, in_size, out_size);
  }
  return nearest_index(source_coord(out_coord, in_size, out_size, explicit_scale));
}
{% endif %}

fn input_at(base: u32, h: i32, w: i32) -> f32 {
  let hh = u32(clamp(h, 0, i32(params.inH) - 1));
  let ww = u32(clamp(w, 0, i32(params.inW) - 1));
  return f32(x[base + hh * params.inW + ww]);
}
{% if modeSpec == "linear" %}

// Clamp before choosing neighbors. At an edge both neighbors coincide and
// receive half weight; the four-term order is observable for integer outputs.
fn bilinear_sample(base: u32, source_y: f32, source_x: f32) -> f32 {
  let sy = clamp(source_y, 0.0, f32(params.inH - 1u));
  let sx = clamp(source_x, 0.0, f32(params.inW - 1u));
  let y0 = i32(floor(sy));
  let x0 = i32(floor(sx));
  let y1 = min(y0 + 1, i32(params.inH) - 1);
  let x1 = min(x0 + 1, i32(params.inW) - 1);
  let same_y = y0 == y1;
  let same_x = x0 == x1;
  let wy0 = select(abs(sy - f32(y1)), 0.5, same_y);
  let wy1 = select(abs(sy - f32(y0)), 0.5, same_y);
  let wx0 = select(abs(sx - f32(x1)), 0.5, same_x);
  let wx1 = select(abs(sx - f32(x0)), 0.5, same_x);
  let v00 = input_at(base, y0, x0);
  let v01 = input_at(base, y0, x1);
  let v10 = input_at(base, y1, x0);
  let v11 = input_at(base, y1, x1);
  return wx0 * wy0 * v00 + wx1 * wy0 * v01 + wx0 * wy1 * v10 + wx1 * wy1 * v11;
}
{% endif %}

