  let row = wg.y;
  let rowBase = row * {{ cols }};
{% if biasRow %}
  let biasBase = bias_base(row);
{% endif %}
  let colStart = block * BLOCK_COLS;
  let colEnd = min({{ cols }}, colStart + BLOCK_COLS);

  var m = -FLT_MAX;
  var d = 0.0;
  for (var col = colStart + lid.x; col < colEnd; col = col + WG) {
    let v = {{ "f32(data[rowBase + col]) + f32(bias[biasBase + col])" if biasRow else "f32(x[rowBase + col])" }};
    let mNew = max(m, v);
    d = d * exp_shift(m, mNew) + exp_shift(v, mNew);
    m = mNew;
  }
{% else %}
  let row = wg.x;
