{% if hasActivation %}
// Apply the fused activation in the f32 accumulator before the single output
// cast, avoiding an intermediate convolution tensor.
{% macro fused_act_fn(mode, alpha, beta) %}
fn fused_act(v: f32) -> f32 {
{% if mode == "Relu" %}
  return max(v, 0.0);
{% elif mode == "Clip" %}
  return clamp(v, f32({{ alpha }}), f32({{ beta }}));
{% elif mode == "LeakyRelu" %}
  return select(v * f32({{ alpha }}), v, v >= 0.0);
{% elif mode == "Sigmoid" %}
  return 1.0 / (1.0 + exp(-v));
{% elif mode == "Tanh" %}
  // tanh is already +/-1 to f32 precision at the clamp bounds. Clamping before
  // the builtin preserves that saturated result for larger accumulators.
  return tanh(clamp(v, -10.0, 10.0));
{% elif mode == "HardSigmoid" %}
  return clamp(f32({{ alpha }}) * v + f32({{ beta }}), 0.0, 1.0);
{% elif mode == "QuickGelu" %}
{% if alpha == 1 %}
  // alpha == 1 is SiLU: the multiply folds away (the spelling yolov8-class detectors emit).
  return v * (1.0 / (1.0 + exp(-v)));
{% else %}
  return v * (1.0 / (1.0 + exp(-(f32({{ alpha }}) * v))));
{% endif %}
{% elif mode == "Elu" %}
  return select(f32({{ alpha }}) * (exp(v) - 1.0), v, v >= 0.0);
{% elif mode == "ThresholdedRelu" %}
  return select(0.0, v, v > f32({{ alpha }}));
{% elif mode == "Softplus" %}
  // log(1 + exp(v)) spelled overflow-safe: max(v, 0) + log(1 + exp(-|v|)).
  return max(v, 0.0) + log(1.0 + exp(-abs(v)));
{% elif mode == "Erf" %}
  // Abramowitz & Stegun 7.1.26 (|error| < 1.5e-7), the same polynomial the standalone
  // Erf/Gelu kernels use, so a fused and an unfused graph agree to f32 rounding.
  let a = abs(v);
  let t = 1.0 / (1.0 + 0.3275911 * a);
  let poly = ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t;
  return sign(v) * (1.0 - poly * exp(-a * a));
{% elif mode == "Gelu" and alpha == 0 %}
  // ONNX Gelu, erf form: 0.5 * v * (1 + erf(v / sqrt(2))); activation_params[0] == 0.
  let u = v * 0.70710678118654752;
  let a = abs(u);
  let t = 1.0 / (1.0 + 0.3275911 * a);
  let poly = ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t;
  return 0.5 * v * (1.0 + sign(u) * (1.0 - poly * exp(-a * a)));
{% elif mode == "Gelu" or mode == "FastGelu" %}
  // tanh approximation (ONNX Gelu approximate="tanh" arrives as activation_params[0] != 0;
  // com.microsoft.FastGelu always). tanh saturates to +/-1 well inside the clamp.
  let inner = v * (0.035677408136300125 * v * v + 0.7978845608028654);
  return v * (0.5 + 0.5 * tanh(clamp(inner, -10.0, 10.0)));
{% else %}
  return v * clamp(v * 0.16666666666666666 + 0.5, 0.0, 1.0);
{% endif %}
}{% endmacro %}
{{ fused_act_fn(activation, actAlpha, actBeta) }}
{% endif %}
{% set biasAdd = " + bv" if hasBias else "" %}
{% if hasActivation or hasZ %}
// Fused epilogue: Y = activation(conv + bias + Z), applied at the output store.
// `raw` is the f32 convolution-plus-bias accumulator; Z shares Y's NCHW layout.
fn epi(raw: f32{% if hasZ %}, yIndex: u32{% endif %}) -> {{ T }} {
  var r = raw;
{% if hasZ %}
  r = r + f32(zResidual[yIndex]);
{% endif %}
{% if hasActivation %}
  r = fused_act(r);
{% endif %}
  return {{ T }}(r);
}
{% endif %}
