{% set quantized = quantized | default(false) %}
{% set bits = bits | default(0) %}
{% if useSeqlens is not defined %}{% set useSeqlens = false %}{% endif %}
{% if windowOrigin is not defined %}{% set windowOrigin = false %}{% endif %}
{% set needsOrigin = windowOrigin and (hasRotary or hasBias) %}
{% set ropePos = "(absPos + origin)" if needsOrigin else "absPos" %}
{% set biasStride = "params.biasCols" if needsOrigin else "totalSeq" %}
{% set biasCol = "(origin + j)" if needsOrigin else "j" %}
{{ env.wgsl.resourceDeclarations }}
// f16 inputs widen to f32 on load; computation and shared memory remain f32,
// and results narrow only on store. The casts are identities for f32.
{% set IO = "f16" if usesF16 else "f32" %}

{% if cooperative %}
// One workgroup owns each (batch, qHead, qToken). Lanes partition the key range,
// run local online softmax states, then merge max/rescale/sum through workgroup
// memory. This exposes parallelism when the query count is small.
{% else %}
// One invocation owns each (batch, qHead, qToken) and walks the key range. The
// larger query grid supplies parallelism without a workgroup-level merge.
{% endif %}
// The attention path supports optional per-head qk-norm and
// rotary on Q, causal (+ sliding-window) masking, logit soft-capping, additive
// attention bias, and smooth-softmax / head-sink. The cache is read directly
// (f32), or dequantized from standard INT8 / +8-biased packed INT4 storage when
// `quantized` is enabled.
const HEAD_DIM: u32 = {{ headDim }}u;
{% if hasRotary %}const HALF: u32 = {{ half }}u;{% endif %}
const Q_HEADS: u32 = {{ qHeads }}u;
const KV_HEADS: u32 = {{ kvHeads }}u;
const Q_HIDDEN: u32 = {{ qHidden }}u;
const GROUP: u32 = {{ qHeads }}u / {{ kvHeads }}u;
const PACKED: u32 = {{ packed }}u;
{% if hasQNorm %}const QK_EPS: f32 = {{ qkEps }};{% endif %}
{% if cooperative %}const WG: u32 = {{ gqaCooperativeWorkgroupSize }}u;{% else %}const WG: u32 = {{ scalarWorkgroupSize }}u;{% endif %}
const NEG_INF: f32 = -3.4028234663852886e38;
{% set ATTN_SCALE_DIM = "HEAD_DIM" %}fn scale_value() -> f32 {
  if (params.scale != 0.0) { return params.scale; }
  return inverseSqrt(f32({{ ATTN_SCALE_DIM }}));
}

{% if quantized %}
fn kscale(d: u32, hk: u32) -> f32 { return k_scale[select(0u, hk * HEAD_DIM + d, params.perChannel != 0u)]; }
fn vscale(d: u32, hk: u32) -> f32 { return v_scale[select(0u, hk * HEAD_DIM + d, params.perChannel != 0u)]; }
{% endif %}

fn read_k(base: u32, d: u32{% if quantized %}, hk: u32{% endif %}) -> f32 {
{% if not quantized %}
  return f32(kcache[base + d]);
{% elif bits == 8 %}
  return f32(kcache[base + d]) * kscale(d, hk);
{% else %}
  let byte = kcache[base + (d >> 1u)];
  let nib = i32((byte >> ((d & 1u) * 4u)) & 0xFu) - 8;
  return f32(nib) * kscale(d, hk);
{% endif %}
}
fn read_v(base: u32, d: u32{% if quantized %}, hk: u32{% endif %}) -> f32 {
{% if not quantized %}
  return f32(vcache[base + d]);
{% elif bits == 8 %}
  return f32(vcache[base + d]) * vscale(d, hk);
{% else %}
  let byte = vcache[base + (d >> 1u)];
  let nib = i32((byte >> ((d & 1u) * 4u)) & 0xFu) - 8;
  return f32(nib) * vscale(d, hk);
{% endif %}
}

{% if cooperative %}
// One allocation avoids the per-variable 16-byte padding between arrays.
// The manifest budgets the structure's complete size, rounded to 16 bytes.
struct CooperativeState {
  q: array<f32, HEAD_DIM>,
  acc: array<f32, HEAD_DIM * WG>,
  m: array<f32, WG>,
  l: array<f32, WG>,
}
var<workgroup> state: CooperativeState;

@compute @workgroup_size(WG)
fn main(@builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
  // One workgroup per query; fold large query grids over x/y.
  let qi = wid.x + wid.y * {{ DISPATCH_FOLD_WIDTH }}u;
  let total = params.batch * Q_HEADS * params.qSeq;
  if (qi >= total) { return; }
  let lane = lid.x;
  let s = qi % params.qSeq;
  let tmp = qi / params.qSeq;
  let h = tmp % Q_HEADS;
  let b = tmp / Q_HEADS;
  let hk = h / GROUP;
  let totalSeq = params.totalSeq;
{% if useSeqlens %}
  // Buffer-sharing caches keep capacity in the BNSH dim2 stride; seqlens_k[b]+1
  // is the per-batch active end and rows beyond it are untouched storage.
  let activeEnd = min(totalSeq, max(params.qSeq, u32(seqlens_k[b]) + 1u));
{% else %}
  let activeEnd = totalSeq;
{% endif %}
{% if not bidirectional or hasRotary %}  let absPos = activeEnd - params.qSeq + s;
{% endif %}{% if needsOrigin %}
  // Absolute position of cache row 0 (windowed cache): the query end is the
  // unclamped total while the cache holds only its last `activeEnd` rows.
  let origin = max(params.qSeq, u32(seqlens_k[b]) + 1u) - activeEnd;
{% endif %}

  // Cooperative query-vector prep (post norm/rotary) into shared memory.
  let qBase = (b * params.qSeq + s) * Q_HIDDEN + h * HEAD_DIM;
  for (var d = lane; d < HEAD_DIM; d = d + WG) { state.q[d] = f32(query[qBase + d]); }
  workgroupBarrier();
{% if hasQNorm %}
  var part = 0.0;
  for (var d = lane; d < HEAD_DIM; d = d + WG) { part = part + state.q[d] * state.q[d]; }
  state.m[lane] = part;
  workgroupBarrier();
  var ms = 0.0;
  for (var L = 0u; L < WG; L = L + 1u) { ms = ms + state.m[L]; }
  let invRms = inverseSqrt(ms / f32(HEAD_DIM) + QK_EPS);
  for (var d = lane; d < HEAD_DIM; d = d + WG) { state.q[d] = state.q[d] * invRms * f32(q_norm_weight[d]); }
  workgroupBarrier();
{% endif %}
{% if hasRotary %}
  // Each lane owns disjoint pairs (d, d+HALF), so the in-place rotate is safe.
  for (var d = lane; d < HALF; d = d + WG) {
    let cs = f32(cos_cache[{{ ropePos }} * HALF + d]);
    let sn = f32(sin_cache[{{ ropePos }} * HALF + d]);
    let x0 = state.q[d];
    let x1 = state.q[d + HALF];
    state.q[d] = x0 * cs - x1 * sn;
    state.q[d + HALF] = x1 * cs + x0 * sn;
  }
  workgroupBarrier();
{% endif %}
  let scale = scale_value();
  let maxKj = {% if bidirectional %}activeEnd{% else %}absPos + 1u{% endif %};
  var minKj = 0u;
  if (params.windowSize > 0u && maxKj > params.windowSize) { minKj = maxKj - params.windowSize; }

  let accBase = lane * HEAD_DIM;
  for (var d = 0u; d < HEAD_DIM; d = d + 1u) { state.acc[accBase + d] = 0.0; }
  var m = NEG_INF;
  var l = 0.0;

  // Each lane sweeps a strided slice of the key range.
  for (var j = minKj + lane; j < maxKj; j = j + WG) {
    let base = ((b * KV_HEADS + hk) * totalSeq + j) * PACKED;
    var dot = 0.0;
    for (var d = 0u; d < HEAD_DIM; d = d + 1u) { dot = dot + state.q[d] * read_k(base, d{% if quantized %}, hk{% endif %}); }
    var score = dot * scale;
    if (params.softcap > 0.0) { score = params.softcap * tanh(clamp(score / params.softcap, -30.0, 30.0)); }
{% if hasBias %}
    let bb = select(b, 0u, params.biasBatch == 1u);
    let bh = select(h, 0u, params.biasHeads == 1u);
    score = score + f32(attn_bias[((bb * params.biasHeads + bh) * params.qSeq + s) * {{ biasStride }} + {{ biasCol }}]);
{% endif %}
    let newM = max(m, score);
    let corr = exp(m - newM);
    let p = exp(score - newM);
    l = l * corr + p;
    for (var d = 0u; d < HEAD_DIM; d = d + 1u) { state.acc[accBase + d] = state.acc[accBase + d] * corr + p * read_v(base, d{% if quantized %}, hk{% endif %}); }
    m = newM;
  }

  // Flash merge across the WG lanes: global max, rescale, summed denom.
  state.m[lane] = m;
  workgroupBarrier();
  var gm = NEG_INF;
  for (var L = 0u; L < WG; L = L + 1u) { gm = max(gm, state.m[L]); }
  let fctr = exp(m - gm);
  l = l * fctr;
  for (var d = 0u; d < HEAD_DIM; d = d + 1u) { state.acc[accBase + d] = state.acc[accBase + d] * fctr; }
  state.l[lane] = l;
  workgroupBarrier();
  var glsum = 0.0;
  for (var L = 0u; L < WG; L = L + 1u) { glsum = glsum + state.l[L]; }

  var sink = 0.0;
{% if hasHeadSink %}
  sink = f32(head_sink[h]);
  let useSmooth = true;
{% else %}
  let useSmooth = params.smoothSoftmax != 0u;
{% endif %}
  var finalM = gm;
  var smoothTerm = 0.0;
  if (useSmooth) {
    finalM = max(gm, sink);
    smoothTerm = exp(sink - finalM);
  }
  let accScale = exp(gm - finalM);
  // A query whose every key is masked out leaves the denominator at zero (no
  // head sink to carry mass); emit a zero row instead of 0 * (1/0) = NaN.
  let denom = smoothTerm + glsum * accScale;
  let invDenom = select(0.0, accScale / denom, denom > 0.0);

  // Cross-lane sum of the rescaled V accumulators, written cooperatively.
  let oBase = (b * params.qSeq + s) * Q_HIDDEN + h * HEAD_DIM;
  for (var d = lane; d < HEAD_DIM; d = d + WG) {
    var sumacc = 0.0;
    for (var L = 0u; L < WG; L = L + 1u) { sumacc = sumacc + state.acc[L * HEAD_DIM + d]; }
    output[oBase + d] = {{ IO }}(sumacc * invDenom);
  }
}
{% else %}
@compute @workgroup_size(WG)
fn main(@builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
  // One thread per query; the grid is 2D-folded so the workgroup count stays
  // within the per-axis dispatch fold width for large prefills. Reconstruct the flat
  // thread index from the folded workgroup grid rather than from global_invocation_id,
  // which only spans the clamped axis and would drop the y-folded tail. With no fold
  // wid.y is zero, so this reduces to the ordinary flat index.
  let qi = (wid.x + wid.y * {{ DISPATCH_FOLD_WIDTH }}u) * WG + lid.x;
  let total = params.batch * Q_HEADS * params.qSeq;
  if (qi >= total) { return; }
  let s = qi % params.qSeq;
  let tmp = qi / params.qSeq;
  let h = tmp % Q_HEADS;
  let b = tmp / Q_HEADS;
  let hk = h / GROUP;
  let totalSeq = params.totalSeq;
{% if useSeqlens %}
  // Buffer-sharing caches keep capacity in the BNSH dim2 stride; seqlens_k[b]+1
  // is the per-batch active end and rows beyond it are untouched storage.
  let activeEnd = min(totalSeq, max(params.qSeq, u32(seqlens_k[b]) + 1u));
{% else %}
  let activeEnd = totalSeq;
{% endif %}
{% if not bidirectional or hasRotary %}  let absPos = activeEnd - params.qSeq + s;
{% endif %}{% if needsOrigin %}
  // Absolute position of cache row 0 (windowed cache): the query end is the
  // unclamped total while the cache holds only its last `activeEnd` rows.
  let origin = max(params.qSeq, u32(seqlens_k[b]) + 1u) - activeEnd;
{% endif %}

  // Private query-vector prep (post norm/rotary).
  var q: array<f32, HEAD_DIM>;
  let qBase = (b * params.qSeq + s) * Q_HIDDEN + h * HEAD_DIM;
  for (var d = 0u; d < HEAD_DIM; d = d + 1u) { q[d] = f32(query[qBase + d]); }
{% if hasQNorm %}
  var ss = 0.0;
  for (var d = 0u; d < HEAD_DIM; d = d + 1u) { ss = ss + q[d] * q[d]; }
  let invRms = inverseSqrt(ss / f32(HEAD_DIM) + QK_EPS);
  for (var d = 0u; d < HEAD_DIM; d = d + 1u) { q[d] = q[d] * invRms * f32(q_norm_weight[d]); }
{% endif %}
{% if hasRotary %}
  for (var d = 0u; d < HALF; d = d + 1u) {
    let cs = f32(cos_cache[{{ ropePos }} * HALF + d]);
    let sn = f32(sin_cache[{{ ropePos }} * HALF + d]);
    let x0 = q[d];
    let x1 = q[d + HALF];
    q[d] = x0 * cs - x1 * sn;
    q[d + HALF] = x1 * cs + x0 * sn;
  }
{% endif %}
  let scale = scale_value();
  let maxKj = {% if bidirectional %}activeEnd{% else %}absPos + 1u{% endif %};
  var minKj = 0u;
  if (params.windowSize > 0u && maxKj > params.windowSize) { minKj = maxKj - params.windowSize; }

  var acc: array<f32, HEAD_DIM>;
  for (var d = 0u; d < HEAD_DIM; d = d + 1u) { acc[d] = 0.0; }
  var m = NEG_INF;
  var l = 0.0;

  for (var j = minKj; j < maxKj; j = j + 1u) {
    let base = ((b * KV_HEADS + hk) * totalSeq + j) * PACKED;
    var dot = 0.0;
    for (var d = 0u; d < HEAD_DIM; d = d + 1u) { dot = dot + q[d] * read_k(base, d{% if quantized %}, hk{% endif %}); }
    var score = dot * scale;
    if (params.softcap > 0.0) { score = params.softcap * tanh(clamp(score / params.softcap, -30.0, 30.0)); }
{% if hasBias %}
    let bb = select(b, 0u, params.biasBatch == 1u);
    let bh = select(h, 0u, params.biasHeads == 1u);
    score = score + f32(attn_bias[((bb * params.biasHeads + bh) * params.qSeq + s) * {{ biasStride }} + {{ biasCol }}]);
{% endif %}
    let newM = max(m, score);
    let corr = exp(m - newM);
    let p = exp(score - newM);
    l = l * corr + p;
    for (var d = 0u; d < HEAD_DIM; d = d + 1u) { acc[d] = acc[d] * corr + p * read_v(base, d{% if quantized %}, hk{% endif %}); }
    m = newM;
  }

  var sink = 0.0;
{% if hasHeadSink %}
  sink = f32(head_sink[h]);
  let useSmooth = true;
{% else %}
  let useSmooth = params.smoothSoftmax != 0u;
{% endif %}
  var finalM = m;
  var smoothTerm = 0.0;
  if (useSmooth) {
    finalM = max(m, sink);
    smoothTerm = exp(sink - finalM);
  }
  let accScale = exp(m - finalM);
  // Same all-masked guard as the cooperative epilogue above.
  let denom = smoothTerm + l * accScale;
  let invDenom = select(0.0, accScale / denom, denom > 0.0);

  let oBase = (b * params.qSeq + s) * Q_HIDDEN + h * HEAD_DIM;
  for (var d = 0u; d < HEAD_DIM; d = d + 1u) { output[oBase + d] = {{ IO }}(acc[d] * invDenom); }
}
{% endif %}

webgpu-kernels/com.microsoft.GroupQueryA.attn-materialized-sgmat-f32.wgsl.jinja:
{% set MT = "f16" if (operandF16 is defined and operandF16) else "f32" %}
{% set ST = "f16" if (storageF16 is defined and storageF16) else MT %}
enable subgroups;
{% if pinSubgroupSize32 %}
enable subgroup_size_control;
{% endif %}
enable chromium_experimental_subgroup_matrix;
diagnostic(off, chromium.subgroup_matrix_uniformity);

{{ env.wgsl.resourceDeclarations }}

{% set kvHeadMajor = (kvLayout | default(layout)) == "bhsd" %}
{% set CAUSAL_UPPER_LEFT = false %}
{% set CAUSAL = (causalRightAlign is defined and causalRightAlign) or CAUSAL_UPPER_LEFT %}
{% macro q_index(row, d) %}(b * params.qSeq + {{ row }}) * HIDDEN + h * HEAD_DIM + {{ d }}{% endmacro %}
{% macro kv_index(seq, d) %}{% if kvHeadMajor %}((b * KV_HEADS + h_kv) * params.kvSeq + {{ seq }}) * HEAD_DIM + {{ d }}{% else %}(b * params.kvSeq + {{ seq }}) * KV_HIDDEN + h_kv * HEAD_DIM + {{ d }}{% endif %}{% endmacro %}
{% set OUT_ROW_STRIDE = "HIDDEN" %}
{% set KV_ROW_STRIDE = "HEAD_DIM" if kvHeadMajor else "KV_HIDDEN" %}
{% set SCRATCH_HEAD = "(b * HEADS + h)" %}
{% set scorePhase = phase == "score" %}
{% set SCORE_BIAS = scorePhase and scoreBias is defined and scoreBias %}
{% set SCORE_WINDOW = CAUSAL and scoreWindow is defined and scoreWindow %}
{% set USE_SEQLENS = useSeqlens is defined and useSeqlens %}
{% set FUSED_SOFTMAX = fusedSoftmax is defined and fusedSoftmax %}
{% set PRIVATE_ROW_STATS = FUSED_SOFTMAX and (materializedSgmatPrivateRowStats is defined and materializedSgmatPrivateRowStats) %}
{% macro score_value(index, guard) %}
{% set rowMax = "private_softmax_m" if PRIVATE_ROW_STATS else "softmax_m[" ~ guard[0] ~ "]" %}
{% set rowDenom = "private_softmax_d" if PRIVATE_ROW_STATS else "softmax_d[" ~ guard[0] ~ "]" %}
select(0.0, {{ "exp_shift(scores[" ~ index ~ "], " ~ rowMax ~ ") / " ~ rowDenom if FUSED_SOFTMAX else "scores[" ~ index ~ "]" }}, {{ guard[1] }}){% endmacro %}
{% set TILE_M_VALUE = materializedSgmatQueryTile %}
{% set TILE_N_VALUE = materializedSgmatKeyTile %}
{% set TILE_K_VALUE = materializedSgmatInnerTile %}
{% set SUB_ROWS_VALUE = 16 %}
{% set SUB_COLS_VALUE = 32 %}
{% set ROW_BLOCKS = 2 %}
{% set COL_BLOCKS = 4 %}
{% set SUBGROUP_ROWS = (TILE_M_VALUE / SUB_ROWS_VALUE)|int %}
{% set SUBGROUP_COLS = (TILE_N_VALUE / SUB_COLS_VALUE)|int %}
{% set SUBGROUP_COUNT = SUBGROUP_ROWS * SUBGROUP_COLS %}
{% set WORKGROUP_THREADS = SUBGROUP_COUNT * 32 %}
{% if hasBias is not defined %}{% set hasBias = false %}{% endif %}
{% set EMIT_ROW_STATS = emitRowStats is defined and emitRowStats %}
{% set DIRECT_SCORE_STORE = false %}
{% set DIRECT_APPLY_STORE = false %}
{% set DIRECT_OUTPUT_STORE = DIRECT_SCORE_STORE if scorePhase else DIRECT_APPLY_STORE %}
{% set RUNTIME_DIRECT_STORE = (not DIRECT_OUTPUT_STORE)
   and materializedSgmatRuntimeDirectStore
   and (scorePhase or (not hasBias and MT == "f32" and ST == "f32"))
   and not EMIT_ROW_STATS %}
{% set ANY_DIRECT_STORE = DIRECT_OUTPUT_STORE or RUNTIME_DIRECT_STORE %}
{% set SCALE_IN_Q = DIRECT_SCORE_STORE or (RUNTIME_DIRECT_STORE and scorePhase) %}
{% macro operand_load(name, index) %}{% if ST != MT %}{{ MT }}({% endif %}{{ name }}[{{ index }}]{% if ST != MT %}){% endif %}{% endmacro %}
{% macro q_tile_value(index) %}{% if hasBias %}({{ operand_load("query", index) }} + bias[h * HEAD_DIM + k]){% else %}{{ operand_load("query", index) }}{% endif %}{% if SCALE_IN_Q %} * score_scale{% endif %}{% endmacro %}

const HEADS: u32 = {{ qNumHeads }}u;
const KV_HEADS: u32 = {{ kvNumHeads }}u;
const HEAD_DIM: u32 = {{ headDim }}u;
const HIDDEN: u32 = {{ qHidden }}u;
{% if hasBias %}
/* Packed [Q; K; V] bias. Q folds into the query tile before the GEMM. K is
 * omitted: expanding (q + bq).(k + bk) leaves a (q + bq).bk term that is
 * constant across every key in the row, and softmax is invariant under that
 * constant. V is token-independent, so sum_k p[k] * bv = bv after
 * normalization; it is added after the apply GEMM. */
{% endif %}
{% if not kvHeadMajor %}
// Packed K/V rows span KV_HEADS heads, so they are narrower than the query
// row whenever queries are grouped. Q and the output keep HIDDEN.
const KV_HIDDEN: u32 = KV_HEADS * HEAD_DIM;
{% endif %}
{% if EMIT_ROW_STATS %}
const STAT_SLOTS: u32 = {{ statSlots }}u;
{% endif %}
const TILE_M: u32 = {{ TILE_M_VALUE }}u;
const TILE_N: u32 = {{ TILE_N_VALUE }}u;
const TILE_K: u32 = {{ TILE_K_VALUE }}u;
const SUB_ROWS: u32 = {{ SUB_ROWS_VALUE }}u;
const SUB_COLS: u32 = {{ SUB_COLS_VALUE }}u;
const SUBGROUP_ROWS: u32 = {{ SUBGROUP_ROWS }}u;
{% if (FUSED_SOFTMAX and not PRIVATE_ROW_STATS)
   or not (TILE_M_VALUE == 64 and TILE_N_VALUE == 64 and TILE_K_VALUE == 32 and WORKGROUP_THREADS == 256) %}
const WORKGROUP_THREADS: u32 = {{ WORKGROUP_THREADS }}u;
{% endif %}

var<workgroup> tile_A: array<{{ MT }}, {{ TILE_M_VALUE * TILE_K_VALUE }}>;
var<workgroup> tile_B: array<{{ MT }}, {{ TILE_N_VALUE * TILE_K_VALUE }}>;
{% set SCRATCH = "tile_A" if MT == "f32" else "store_scratch" %}
{% if MT == "f16" %}
// The compact epilogue banks f32 result fragments; an f16 operand tile cannot
// alias them, so the f16 build carries a dedicated store scratch.
var<workgroup> store_scratch: array<f32, {{ TILE_M_VALUE * TILE_K_VALUE }}>;
{% endif %}
{% if FUSED_SOFTMAX and not PRIVATE_ROW_STATS %}
// The tile's rows own their softmax constants for the whole k loop, so they are
// read once per workgroup rather than once per staged element.
var<workgroup> softmax_m: array<f32, {{ TILE_M_VALUE }}>;
var<workgroup> softmax_d: array<f32, {{ TILE_M_VALUE }}>;
{% endif %}
{% if FUSED_SOFTMAX or EMIT_ROW_STATS %}
// FLT_MAX, not -inf, as the online (m, d) accumulator init: merges must keep
// `m - m` finite so an empty lane / all--inf row contributes the exact
// accumulator identity (m, d) = (-FLT_MAX, 0). Operator epilogues interpret
// a zero final denominator according to their public semantics. Using -inf
// here changes +inf-row behavior.
const FLT_MAX: f32 = 3.4028234663852886e38;

fn is_finite_f32(value: f32) -> bool {
  return select(false, value <= FLT_MAX, value >= -FLT_MAX);
}

// x - m that is exactly 0 when x equals a finite m, so exp(shifted) == 1
// exactly at the row max. `x - x` on an infinite max is a legal fast-math
// fold to 0, which would silently turn +inf rows finite — the explicit
// equality test keeps the NaN propagation of the serial kernels.
fn shifted_value(value: f32, maxValue: f32) -> f32 {
  let equalFiniteMax = select(false, value == maxValue, is_finite_f32(maxValue));
  return select(value - maxValue, 0.0, equalFiniteMax);
}

fn exp_shift(value: f32, maxValue: f32) -> f32 {
  return exp(shifted_value(value, maxValue));
}
{% endif %}

@compute @workgroup_size({{ WORKGROUP_THREADS }}, 1, 1){{ " @subgroup_size(32)" if pinSubgroupSize32 else "" }}
fn main(
  @builtin(workgroup_id) wg: vec3<u32>,
  @builtin(local_invocation_index) li: u32{% if not DIRECT_OUTPUT_STORE %},
  @builtin(subgroup_invocation_id) lane: u32{% endif %}
) {
  let h = wg.z % HEADS;
  let b = wg.z / HEADS;
  let h_kv = h / (HEADS / KV_HEADS);
  let m_base = wg.y * TILE_M;
  let n_base = wg.x * TILE_N;
  let subgroup = li / 32u;
  let subtile_idy = subgroup % SUBGROUP_ROWS;
  let subtile_idx = subgroup / SUBGROUP_ROWS;
  let base_A = subtile_idy * SUB_ROWS;
  let base_B = subtile_idx * SUB_COLS;
