  let batch = headFlat / (params.numHeads * params.sequenceLength);
{% else %}
  let token = headFlat % params.sequenceLength;
  let batch = (headFlat / params.sequenceLength) / params.numHeads;
{% endif %}

{{ mrope_cache_index("pair") }}
{% if interleaved %}
