// and feeds TILE_N output columns of each projection from it. LANES threads
// cooperate on one column: thread (column, lane) strides the reduction axis by
// LANES, and the per-column partials are folded within the column's own lane
// group at the end. Codes are dequantized as (code - ZERO) * block_scale, with
// the block scale hoisted out of the inner loop; this operator has no
// zero-point input, so ZERO is the symmetric midpoint for the bit width.
// A workgroup covers ROW_TILE activation rows, reusing each unpacked weight code
// across their accumulators.
const K: u32 = {{ K }}u;
const N: u32 = {{ N }}u;
{% if not decodeVec %}
// The pair and tile walks address codes through the block; the vector walk
// addresses whole vector groups and never needs it.
