// com.microsoft.LinearAttention, chunked prefill: the chunk-local delta transform.
//
// The delta rules apply S_t = (I - beta_t k_t k_t^T) diag(a_t) S_{t-1} + beta_t k_t v_t^T,
// whose per-token correction is what forces the recurrent kernels to serialize. Over
// one chunk the corrections satisfy a unit lower triangular system
//   (I + W) d = beta * (v - S_0^T k_til),   W[t,s] = beta_t * dot(k_til_t, k_hat_s), s < t
// so d = u - wk * S_0 with u = Tb * V and wk = Tb * K_til, Tb = (I + W)^-1 diag(beta).
// Both depend only on this chunk's own key, value and beta -- not on the entry state --
// so every chunk in the sequence computes them at once here, and the sequential pass is
// left with two dense products per chunk instead of one dependent step per token.
const CHUNK: u32 = {{ chunkSize }}u;
const HEAD_DIM_K: u32 = {{ headDimK }}u;
const HEAD_DIM_V: u32 = {{ headDimV }}u;
const KV_PER_KEY_HEAD: u32 = {{ kvPerKeyHead }}u;
const TK: u32 = {{ chunkTileK }}u;
const WG: u32 = {{ workgroupSize }}u;
// Entries of the CHUNK x CHUNK system each thread carries across the reduction tiles.
const ENTRIES: u32 = (CHUNK * CHUNK) / WG;

{{ emit_chunk_operands(needKtil=true) }}
// `wm` holds W while the system is being built, then the inverse in place: row t of
// the inverse is produced from row t of W and the already-final rows above it.
var<workgroup> wm: array<f32, CHUNK * CHUNK>;
var<workgroup> rowbuf: array<f32, CHUNK>;
var<workgroup> betas: array<f32, CHUNK>;
var<workgroup> tile: array<f32, CHUNK * TK>;
// Both W operands are staged: the inner product below runs CHUNK^2 times per tile,
// so a global read there would be paid once per pair rather than once per element.
var<workgroup> tile_til: array<f32, CHUNK * TK>;

@compute @workgroup_size(WG, 1, 1)
fn main(
  @builtin(workgroup_id) wg: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>,
) {
  let tid = lid.x;
  let flat = wg.x + wg.y * {{ DISPATCH_FOLD_WIDTH }}u;
{{ emit_chunk_head_setup() }}
  let chunk = flat % num_chunks;
  let head = (flat / num_chunks) % params.kvNumHeads;
  let batch = flat / (num_chunks * params.kvNumHeads);
  if (batch >= params.batchSize) {
    return;
  }
  let base_t = batch * params.seqLength + chunk * CHUNK;
  // Tokens past the sequence end carry beta 0, which makes their rows of the system
  // the identity and their outputs zero, so the tail chunk needs no separate arm.
  let live = min(CHUNK, params.seqLength - chunk * CHUNK);

  if (tid < CHUNK) {
    var b = 0.0;
    if (tid < live) {
      let bt = base_t + tid;
      b = {{ read_scalar("beta", "select(bt * params.kvNumHeads + head, bt, params.betaPackedDim == 1u)", queryDtype) }};
    }
    betas[tid] = b;
  }
  workgroupBarrier();

  // W = beta * tril(K_til K_hat^T, -1), accumulated over reduction-axis tiles so the
  // two operands share one staging buffer pass instead of a full CHUNK x HEAD_DIM_K copy.
  var acc: array<f32, ENTRIES>;
  for (var m = 0u; m < ENTRIES; m = m + 1u) {
    acc[m] = 0.0;
  }
  for (var kb = 0u; kb < HEAD_DIM_K; kb = kb + TK) {
    for (var e = tid; e < CHUNK * TK; e = e + WG) {
      let t = e / TK;
      let i = kb + e % TK;
      var hat = 0.0;
      var til = 0.0;
      if (t < live && i < HEAD_DIM_K) {
        hat = k_hat(base_t + t, head, i);
        til = k_til(base_t + t, head, i);
      }
      tile[e] = hat;
      tile_til[e] = til;
    }
    workgroupBarrier();
    for (var m = 0u; m < ENTRIES; m = m + 1u) {
      let e = tid + m * WG;
      let t = e / CHUNK;
      let s = e % CHUNK;
      if (s < t) {
        var total = 0.0;
        for (var u = 0u; u < TK; u = u + 1u) {
          total = total + tile_til[t * TK + u] * tile[s * TK + u];
        }
        acc[m] = acc[m] + total;
      }
    }
    workgroupBarrier();
  }
  for (var m = 0u; m < ENTRIES; m = m + 1u) {
    let e = tid + m * WG;
    wm[e] = acc[m] * betas[e / CHUNK];
  }
  workgroupBarrier();

  // Forward substitution for (I + W)^-1, one row per step. W is strictly lower, so
  // row t reads only finished rows; `rowbuf` copies row t out before it is overwritten.
  for (var t = 0u; t < CHUNK; t = t + 1u) {
    if (tid < CHUNK) {
      rowbuf[tid] = wm[t * CHUNK + tid];
    }
    workgroupBarrier();
    if (tid < CHUNK) {
      var a = select(0.0, 1.0, tid == t);
      for (var r = 0u; r < t; r = r + 1u) {
        a = a - rowbuf[r] * wm[r * CHUNK + tid];
      }
      wm[t * CHUNK + tid] = a;
    }
    workgroupBarrier();
  }
  // Tb = T diag(beta): scaling by column completes the transform.
  for (var e = tid; e < CHUNK * CHUNK; e = e + WG) {
    wm[e] = wm[e] * betas[e % CHUNK];
  }
  workgroupBarrier();

  let chunk_base = ((batch * params.kvNumHeads + head) * num_chunks + chunk) * CHUNK;

  // wk = Tb K_til, staged one reduction tile at a time.
  for (var kb = 0u; kb < HEAD_DIM_K; kb = kb + TK) {
    for (var e = tid; e < CHUNK * TK; e = e + WG) {
      let s = e / TK;
      let i = kb + e % TK;
      var v = 0.0;
      if (s < live && i < HEAD_DIM_K) {
        v = k_til(base_t + s, head, i);
      }
      tile[e] = v;
    }
    workgroupBarrier();
    for (var e = tid; e < CHUNK * TK; e = e + WG) {
      let t = e / TK;
      let u = e % TK;
      if (kb + u < HEAD_DIM_K) {
        var total = 0.0;
        for (var s = 0u; s <= t; s = s + 1u) {
          total = total + wm[t * CHUNK + s] * tile[s * TK + u];
        }
        wk[(chunk_base + t) * HEAD_DIM_K + kb + u] = total;
      }
    }
    workgroupBarrier();
  }

  // u = Tb V, over the value axis.
  for (var vb = 0u; vb < HEAD_DIM_V; vb = vb + TK) {
    for (var e = tid; e < CHUNK * TK; e = e + WG) {
      let s = e / TK;
      let j = vb + e % TK;
      var v = 0.0;
      if (s < live && j < HEAD_DIM_V) {
        v = {{ read_scalar("value", "(base_t + s) * params.vPackedDim + head * HEAD_DIM_V + j", queryDtype) }};
      }
      tile[e] = v;
    }
    workgroupBarrier();
    for (var e = tid; e < CHUNK * TK; e = e + WG) {
      let t = e / TK;
      let u = e % TK;
      if (vb + u < HEAD_DIM_V) {
        var total = 0.0;
        for (var s = 0u; s <= t; s = s + 1u) {
          total = total + wm[t * CHUNK + s] * tile[s * TK + u];
        }
        uvec[(chunk_base + t) * HEAD_DIM_V + vb + u] = total;
      }
    }
    workgroupBarrier();
  }
