    let m = base_A + {{ 8 * group }}u + row;
    if (m < rows) {
      let out_base = slot_list[slice_base + m] * INTER;
{% for c in [0, 1, 2, 3] %}
{% if isSwiglu %}
      {
        let out_col = (out_weight_base + col + {{ 8 * c }}u) / 2u;
        if (out_col < INTER) {
          hidden_act[out_base + out_col] = activate(tile_A[(subtile_id * 4u + {{ c }}u) * 64u + row * 8u + col],
