        }
      }
{% else %}
{% for half in ['col', 'col2'] %}
      {
        let out_col = out_weight_base + {{ half }} + {{ 8 * c }}u;
        if (out_col < INTER) {
          hidden_act[out_base + out_col] = activate(tile_A[(subtile_id * 4u + {{ c }}u) * 64u + row * 8u + {{ half }}]);
        }
      }
{% endfor %}
{% endif %}
{% endfor %}
    }
  }
  workgroupBarrier();
{% endfor %}
}

