// different expert tiles and nothing here can sum them. The mix stage that follows applies each
// slot's routing weight and collapses the TOP_K slots into the token's output row.
const HIDDEN: u32 = {{ hidden }}u;
const INTER: u32 = {{ inter }}u;
const MTILE: u32 = {{ groupTileM }}u;
const NTILE: u32 = {{ groupTileN }}u;
const KTILE: u32 = {{ groupTileK }}u;
const THREADS_SIDE: u32 = {{ groupThreads }}u;
const THREADS: u32 = THREADS_SIDE * THREADS_SIDE;
{% set qw = "fc2" %}
{% set qwRows = "HIDDEN" %}
{% set qwPackedCols = fc2PackedCols %}
{% set qwBlocks = fc2ScaleBlocks %}
// Quantized expert weights use unsigned codes offset by 2^(bits-1), so a
// weight is (code - MIDPOINT) * scale. Four-bit codes are packed low-nibble
// first along the reduction axis, two codes per stored word.
const MIDPOINT: f32 = f32({{ quantMidpoint }});
const {{ qw | upper }}_PACKED_COLS: u32 = {{ qwPackedCols }}u;
{% if not colWiseScales %}
// Block-wise scales ({{ qw }}_scales rank 3): one scale per QUANT_BLOCK columns of the reduction
// axis. Column-wise scales (block_size 0) are the rank-2 single-scale-per-row case below.
const QUANT_BLOCK: u32 = {{ quantBlockSize }}u;
const {{ qw | upper }}_BLOCKS: u32 = {{ qwBlocks }}u;
{% endif %}

fn {{ qw }}_weight(expert: u32, row: u32, col: u32) -> f32 {
  let base = expert * {{ qwRows }} + row;
{% if packSize == 2 %}
  let word = {{ qw }}_experts_weights[base * {{ qw | upper }}_PACKED_COLS + col / 2u];
  let code = f32((word >> ((col & 1u) * 4u)) & 15u);
{% else %}
  let code = f32({{ qw }}_experts_weights[base * {{ qw | upper }}_PACKED_COLS + col] & 255u);
{% endif %}
{% if not colWiseScales %}
  return (code - MIDPOINT) * {{ qw }}_scales[base * {{ qw | upper }}_BLOCKS + col / QUANT_BLOCK];
{% else %}
  return (code - MIDPOINT) * {{ qw }}_scales[base];
{% endif %}
}
// Decode the four-code group consumed by the staging loop. The aligned codes
// share one quantization scale: blocks are powers of two of at least 16, and
// this helper requires `col` to be a multiple of four.
fn {{ qw }}_weight_vec4(expert: u32, row: u32, col: u32) -> vec4<f32> {
  let base = expert * {{ qwRows }} + row;
{% if packSize == 2 %}
  let pair = base * {{ qw | upper }}_PACKED_COLS + col / 2u;
  let w0 = {{ qw }}_experts_weights[pair];
  let w1 = {{ qw }}_experts_weights[pair + 1u];
  let codes = vec4<f32>(f32(w0 & 15u), f32((w0 >> 4u) & 15u),
                        f32(w1 & 15u), f32((w1 >> 4u) & 15u));
{% else %}
  let word = base * {{ qw | upper }}_PACKED_COLS + col;
  let codes = vec4<f32>(f32({{ qw }}_experts_weights[word] & 255u), f32({{ qw }}_experts_weights[word + 1u] & 255u),
                        f32({{ qw }}_experts_weights[word + 2u] & 255u), f32({{ qw }}_experts_weights[word + 3u] & 255u));
{% endif %}
{% if not colWiseScales %}
  let scale = {{ qw }}_scales[base * {{ qw | upper }}_BLOCKS + col / QUANT_BLOCK];
{% else %}
  let scale = {{ qw }}_scales[base];
{% endif %}
  return (codes - vec4<f32>(MIDPOINT)) * scale;
}

const KVEC: u32 = {{ groupTileKVec }}u;
