    if (n_full && k_base + KTILE <= {{ kExtent }}) {
{{ stage_group_tiles(aLoad, bLoad, b2Load, kExtent, nExtent, false, bLoadVec4, b2LoadVec4, aLoadVec4) }}
    } else {
{{ stage_group_tiles(aLoad, bLoad, b2Load, kExtent, nExtent, true) }}
