// the tile owns fewer output words than the workgroup has invocations, so the
// value accumulation — which carries as many multiply-adds as the score sweep —
// is spread over the same invocations rather than a fraction of them.
const V_LANES: u32 = QUERY_TILE * HEAD_DIM_V4;
